window.registerCatalog("heritages",[{"id":"y24ykEUfpIu5Gp6D","slug":"warrior-automaton","name":"Автоматон воин","cat":"heritages","type":"heritage","text":"Ваше тело, отличающееся более громоздкой и мощной конструкцией, создано для боя. У вас громоздкая гуманоидная фигура. Размер кости урона вашего кулака увеличивается с 1к4 до 1к6. Вы не получаете штраф при совершении смертельной атаки кулаком или любой другой безоружной атакой.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Пушки и шестерёнки","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Automaton","slug":"automaton","uuid":"Compendium.pf2e.ancestries.Item.kYsBAJ103T44agJF"},"rules":[]}},{"id":"J0eAmntxXywr9sGt","slug":"mage-automaton","name":"Автоматон маг","cat":"heritages","type":"heritage","text":"Камера, в которой находится ваше ядро, имеет более прямую связь с остальной частью вашей гуманоидной формы, что позволяет вам применять магическую энергию своего ядра. Вы получаете одни чары из списка арканных заклинаний. Вы можете по желанию сотворять их как врождённое арканное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Пушки и шестерёнки","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Automaton","slug":"automaton","uuid":"Compendium.pf2e.ancestries.Item.kYsBAJ103T44agJF"},"rules":[]}},{"id":"j1nzBc9Pui7vsJ9o","slug":"sharpshooter-automaton","name":"Автоматон меткий стрелок","cat":"heritages","type":"heritage","text":"Ваша гибкая гуманоидная форма создана для скорости и точности, подходящих для дальнего боя. Вы получаете действие Меткость автоматона.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Пушки и шестерёнки","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Automaton","slug":"automaton","uuid":"Compendium.pf2e.ancestries.Item.kYsBAJ103T44agJF"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Automaton Aim"}]}},{"id":"2kMltxs2rmxRSxfV","slug":"hunter-automaton","name":"Автоматон охотник","cat":"heritages","type":"heritage","text":"Вы были созданы служить разведчиком или ассасином и по телосложению напоминаете стайного охотника, например, крупную кошку или волка. Хотя вы обычно передвигаетесь как четвероногий, вы все равно можете стоять и сражаться на двух ногах, что позволяет вам нормально использовать все снаряжение. Ваше четвероногое телосложение позволяет вам быстро передвигаться; если у вас свободны обе руки, вы можете увеличить свою скорость до 30 футов, когда бежите на всех четырех конечностях.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Пушки и шестерёнки","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Automaton","slug":"automaton","uuid":"Compendium.pf2e.ancestries.Item.kYsBAJ103T44agJF"},"rules":[{"key":"FlatModifier","label":"Двигаться на четырех конечностях","predicate":["on-all-fours"],"selector":"land-speed","value":5}]}},{"id":"B3eATjjSusACHqBR","slug":"newly-minted-automaton","name":"Автоматон с конвейера","cat":"heritages","type":"heritage","text":"Вы — свежеизготовленный автоматон, скорее всего собранный в городе Квантиум. Хотя ваше тело по большей части такое же как у тех, кто был создан многие годы назад, ваш разум свеж, и вы учите новую информацию в быстрее. Вы получаете способность навыка Дополнительные знания в одних Знаниях на ваш выбор. Вы знаете один дополнительный язык из тех, к которым у вас есть доступ.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Automaton","slug":"automaton","uuid":"Compendium.pf2e.ancestries.Item.kYsBAJ103T44agJF"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Additional Lore","grantId":"BocFD2KV0qgUC76x"},{"key":"ActiveEffectLike","mode":"add","path":"system.build.languages.max","value":"1"}]}},{"id":"zPhArF36ZVgLeVUU","slug":"ancient-scale-azarketi","name":"Азаркет древней чешуи","cat":"heritages","type":"heritage","text":"Ваш род происходит от азаркетов, которые остаются верны своим глубоководным корням. Оторванные от земного общества, вы чужестранец в любом мире, находящемся выше глубины в тысячу морских саженей. Вы получаете ночное зрение.\n\nВаше тело усеяно фосфоресцирующими пятнами, которые излучают путеводный свет и помогают вам общаться. Пятна, расположенные в основном на вашем лице, руках и кистях, освещают тусклым светом 10-футовый радиус вокруг вас. Вы можете активировать, деактивировать или изменять расположение огней в качестве действия (1 действие), которое имеет признак концентрация.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Azarketi","slug":"azarketi","uuid":"Compendium.pf2e.ancestries.Item.yFoojz6q3ZjvceFw"},"rules":[{"key":"Sense","selector":"darkvision"}]}},{"id":"DNynADD4xhwTAiE5","slug":"carcharodon-merfolk","name":"Акулий мерфолк","cat":"heritages","type":"heritage","text":"Как страшный акулий мерфолк, ваша нижняя часть тела похожа на тело одного из главных хищников океана. Как и акула, вы можете чувствовать запах крови на довольно большом расстоянии. Вы получаете нюх как неточное чувство с радиусом 30 футов. Однако вы можете учуять пролитую кровь на расстоянии {120 футов} в воздухе и {500 футов} в воде.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Merfolk","slug":"merfolk","uuid":"Compendium.pf2e.ancestries.Item.FUqZRllwn6kmFA8K"},"rules":[{"acuity":"imprecise","key":"Sense","selector":"scent","value":30}]}},{"id":"qiYOFL32pzWFJcDG","slug":"ambitious-human","name":"Амбициозный человек","cat":"heritages","type":"heritage","text":"Вы амбициозны, и уже добились большего, чем ваши сверстники, но также всегда стремитесь вперёд. Вы получаете два умения класса раньше обычного. Поскольку вы получаете эти умения досрочно, вы не можете выбрать их на позднем уровне. Одно умение — общая способность Быстроногий, а второе зависит от вашего класса.\n\nБард: Сведущий\n\nВарвар: Яростное запугивание\n\nМонах: Живучесть\n\nЧародей: Расширение чар\n\nЗаметка: Это наследие относится к Стартовому набору и имеет нестандартные особенности наследия.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Human","slug":"human","uuid":"Compendium.pf2e.ancestries.Item.IiG7DgeLWYrSNXuX"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Fleet","grantId":"Ux73dmoF8KnavyUD"}]}},{"id":"Mmezbef0c1fbJaVV","slug":"impersonator-android","name":"Андроид подражатель","cat":"heritages","type":"heritage","text":"Ваше тело было улучшено процессами и внешностью, предназначенной для более легкого слияния с людьми. Вы становитесь обучены Обману (или другому навыку на свой выбор, если вы уже обучены Обману). Вам не нужен гримёрный набор, когда вы совершаете проверки Обмана, чтобы Перевоплотиться человеком. Кроме того, вы получаете бонус обстоятельства +4 к проверкам \"Перевоплотиться\", чтобы притвориться, что вы являетесь своей человеческой версией, а не андроидом. Этот бонус не применяется к другим проверкам \"Перевоплотиться\" в людей.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Android","slug":"android","uuid":"Compendium.pf2e.ancestries.Item.GfLwE884NoRC7cRi"},"rules":[{"key":"FlatModifier","label":"Impersonator Android (to Impersonate a human version of yourself)","predicate":["action:impersonate","disguise:human-self"],"selector":"deception","type":"circumstance","value":4},{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.deception.rank","value":1}]}},{"id":"BjuZKA7lzFSjKbif","slug":"polyglot-android","name":"Андроид полиглот","cat":"heritages","type":"heritage","text":"Вы были заранее запрограммированы на множество лингвистических навыков, вероятно, чтобы быть переводчиком. Вы изучаете 2 новых языка, выбранных из обычных и необычных языков к которым у вас есть доступ. Эти языки имеют ту же форму (языка жестов или устную), что и другие языки. Если вы выбираете способность Многоязычный, то изучаете 3 новых языка вместо 2.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Android","slug":"android","uuid":"Compendium.pf2e.ancestries.Item.GfLwE884NoRC7cRi"},"rules":[]}},{"id":"MQx7miBXUmOHycqJ","slug":"laborer-android","name":"Андроид рабочий","cat":"heritages","type":"heritage","text":"Ваше тело приспособлено переносить физические невзгоды или длительную тяжелую работу. Вы становитесь обучены Атлетике (или другому навыку на свой выбор, если вы уже обучены Атлетике) и получаете способность навыка Сильный носильщик.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Android","slug":"android","uuid":"Compendium.pf2e.ancestries.Item.GfLwE884NoRC7cRi"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.athletics.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Hefty Hauler","grantId":"C0Tcelg3BAPhML6J"}]}},{"id":"VgL18yU7pysdoZZG","slug":"artisan-android","name":"Андроид ремесленник","cat":"heritages","type":"heritage","text":"Изначально ваше тело было создано для создания произведений искусства, сложных инструментов или обслуживания передовых аппаратов. Вы становитесь обучены Ремеслу (или другому навыку на свой выбор, если вы уже обучены Ремеслу) и получаете способность навыка Специализация в ремесле со специализацией на ваш выбор.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Android","slug":"android","uuid":"Compendium.pf2e.ancestries.Item.GfLwE884NoRC7cRi"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.crafting.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Specialty Crafting","grantId":"QLeMH5mQgh28sa5o"}]}},{"id":"jAX7yavR4lNKwDK8","slug":"ardande","name":"Арданд","cat":"heritages","type":"heritage","text":"Вы ведёте свой род от древесных элементалей или имеете какое-то другое наследие, связанное со стихийным Планом Дерева. У вас может быть зеленая, покрытая мхом кожа, растущие на голове лианы вместо волос или тонкие придатки, напоминающие ветки. Вы получаете признак арданд в дополнение к признакам вашей родословной. Вы также получаете сумеречное зрение или ночное зрение, если ваша родословная уже имеет сумеречное зрение.\n\nПри получении способности родословной вы можете выбирать из способностей ардандов, способностей джинникинов и способностей своей родословной.\n\nАрданд","level":0,"traits":["арданд"],"tags":["ardande"],"rarity":"необычный","remaster":true,"source":"Ярость стихий","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"key":"Sense","selector":"low-light-vision"},{"key":"Sense","predicate":["self:low-light-vision:from-ancestry"],"selector":"darkvision"}]}},{"id":"1dYDucCIaZpCJqBc","slug":"arctic-elf","name":"Арктический эльф","cat":"heritages","type":"heritage","text":"Вы живете глубоко на замерзшем севере и приобрели невероятную устойчивость к холодным средам, получив сопротивление холоду, равное половине вашего уровня (минимум 1). Вы считаете эффекты Холодной окружающей среды так, как если бы они были на одну ступень легче (невероятный холод становится экстремальным, экстремальный холод становится сильным и так далее).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Elf","slug":"elf","uuid":"Compendium.pf2e.ancestries.Item.PgKmsA2aKdbLU6O0"},"rules":[]}},{"id":"L6FwEsrOK3Xno7qM","slug":"ascetic-tanuki","name":"Аскетичный тануки","cat":"heritages","type":"heritage","text":"Говорят, что ваша округлая форма — результат спокойствия и сдержанности, а не потворства. Вы получаете Нюх как Неточное чувство с дистанцией 30 футов. Мастер обычно удваивает дистанцию, если вы находитесь на наветренной стороне от того, что пытаетесь унюхать, или уменьшает её вдвое, если находитесь на подветренной стороне. Кроме того, вы получаете бонус обстоятельства +2 к проверкам Восприятия, если пытаетесь обнаружить пищу, питьё или расходуемый проглатываемый предмет (например зелье или эликсир), используя свой нюх.","level":0,"traits":["Тануки"],"tags":["tanuki"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tanuki","slug":"tanuki","uuid":"Compendium.pf2e.ancestries.Item.pILFsoGsUQkVF5dZ"},"rules":[{"acuity":"imprecise","key":"Sense","range":30,"selector":"scent"},{"key":"FlatModifier","predicate":["locate-food-or-drink"],"selector":"perception","value":2}]}},{"id":"yEQSw61sNRvgPy4T","slug":"hopeful-athamaru","name":"Атамару кандидат","cat":"heritages","type":"heritage","text":"Вы начали готовиться к тому, чтобы стать матриархом атамару, и, вероятно, выходите за пределы своей общины, чтобы лучше подготовиться к роли лидера. В результате физических изменений вы стали значительно выше, чем были раньше. Вместо Среднего размера вы становитесь Большим. Кроме того, вы вселяете в своих союзников чувство надежды. Вы обладаете 10-футовой аурой, которая дает любому союзнику, находящемуся в ней, бонус обстоятельства +1 к спасброскам от страха; это эффект ментальный и эмоции.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Athamaru","slug":"athamaru","uuid":"Compendium.pf2e.ancestries.Item.Cg1AMgp3zrGmimWd"},"rules":[]}},{"id":"CnCFZfuKzAYqy61e","slug":"athamasi","name":"Атамаси","cat":"heritages","type":"heritage","text":"У вас есть пара небольших вспомогательных рук, приспособленных для лазания и свисания с деревьев. Вы не можете держать или доставать объекты с помощью этих конечностей, но вы можете Карабкаться или Схватиться за уступ, даже если одна или обе ваши основные руки заняты. Во время \"Карабканья\" вы не Застигнуты врасплох.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kashrishi","slug":"kashrishi","uuid":"Compendium.pf2e.ancestries.Item.dw2K1AJR9mQ25nDP"},"rules":[]}},{"id":"N36ZR4lh9eCazDaN","slug":"aiuvarin","name":"Аюварин","cat":"heritages","type":"heritage","text":"В вашем роду были эльфы или же другие аюварины. У вас заостренные уши и другие очевидные признаки эльфийского происхождения. Вы получаете признаки эльф и аюварин, а также сумеречное зрение. Когда получаете способность родословной, то вы также можете выбирать из способностей эльфа и аюварина в дополнение к способностям вашей родословной.","level":0,"traits":["аюварин"],"tags":["aiuvarin"],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"key":"Sense","selector":"low-light-vision"},{"key":"ActiveEffectLike","mode":"override","path":"system.details.ancestry.versatile","value":"elf"},{"key":"ActiveEffectLike","mode":"add","path":"system.details.ancestry.countsAs","value":"elf"},{"key":"ActiveEffectLike","mode":"add","path":"system.details.ancestry.countsAs","value":"aiuvarin"}]}},{"id":"sGzhnQpgWErX1bmx","slug":"vigilant-goloma","name":"Бдительный голома","cat":"heritages","type":"heritage","text":"Вы научились осознавать не только очевидные физические опасности, но и заметные магические угрозы. Вы можете по желанию сотворять Обнаружение магии как врождённое арканное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округленного до большего целого. В дополнение, ваша внимательность позволяет вам легче других замечать магические ловушки. Ваше мастерство Восприятия считается на один ранг лучше при попытке обнаружения магических ловушек (обучен считается экспертом, эксперт считается мастером, а мастер считается легендой).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goloma","slug":"goloma","uuid":"Compendium.pf2e.ancestries.Item.c4secsSNG2AO7I5i"},"rules":[]}},{"id":"bsXA1l5mxNnmBh5M","slug":"running-animal","name":"Беговое животное","cat":"heritages","type":"heritage","text":"Вы — животное, приспособленное для бега по земле с огромной скоростью. Обычно вы бегаете на четвереньках, как собака, гепард или игуана, но можете использовать и две ноги, как кенгуру, эму или пингвин.\n\nУ вас наземная Скорость 30 футов и одна атака животного на ваш выбор (обычно, коготь, хвост или челюсти).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Awakened Animal","slug":"awakened-animal","uuid":"Compendium.pf2e.ancestries.Item.GFOgV3MzWkYwJoJW"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.ancestryfeatures.Item.Animal Attack","grantId":"oj532l4YXqzedBBn"}]}},{"id":"x5S4MNQ0aqUmgHcC","slug":"vicious-goloma","name":"Беспощадный голома","cat":"heritages","type":"heritage","text":"Хитин на ваших руках формирует мощные когти, которые позволяют вам защищаться. Вы получаете безоружную атаку когтями, наносящую 1к6 рубящего урона. Ваши когти относятся к группе \"драка\" и имеют признаки безоружное, быстрое и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goloma","slug":"goloma","uuid":"Compendium.pf2e.ancestries.Item.c4secsSNG2AO7I5i"},"rules":[]}},{"id":"Eq42wZ5OTweJLnLU","slug":"gutsy-halfling","name":"Бесстрашный полурослик","cat":"heritages","type":"heritage","text":"Ваш род известен тем, что в решающий момент сохраняет хладнокровие и не поддается страху, делая их мудрыми лидерами, а иногда даже героями. Когда при спасброске против эффекта с признаком эмоция вы получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Halfling","slug":"halfling","uuid":"Compendium.pf2e.ancestries.Item.GgZAHbrjnzWOZy2v"},"rules":[]}},{"id":"erZPj5701KiVAqoi","slug":"forge-blessed-dwarf","name":"Благословленный кузницей дварф","cat":"heritages","type":"heritage","text":"Вы из высокоградской семьи, в которой определённое дварфийское божество почитается превыше всех остальных. Ваше рождение было благословлено божеством-покровителем вашей семьи, наделив вас толикой его силы. Выберите одно божество из дварфийского пантеона. Вы можете раз в неделю сотворять заклинание 1-го ранга, которое божество дарует своим жрецам (например Успокоение, если покровителем вашей семьи является Болка), как врождённое сакральное заклинание.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dwarf","slug":"dwarf","uuid":"Compendium.pf2e.ancestries.Item.BYj5ZvlXZdpaEgA6"},"rules":[]}},{"id":"RuQSx0QsirIKxwKY","slug":"warrior-android","name":"Боевой андроид","cat":"heritages","type":"heritage","text":"Изначально ваше тело было создано для работы в качестве офицера службы безопасности или солдата. Вы от природы одарённый воин, заранее запрограммированный для ведения боя. Вы обучены всему простому и воинскому оружию.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Android","slug":"android","uuid":"Compendium.pf2e.ancestries.Item.GfLwE884NoRC7cRi"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.proficiencies.attacks.simple.rank","value":1},{"key":"ActiveEffectLike","mode":"upgrade","path":"system.proficiencies.attacks.martial.rank","value":1}]}},{"id":"HAo0S8ysFipf6S2B","slug":"roaming-minotaur","name":"Бродячий минотавр","cat":"heritages","type":"heritage","text":"Ваши копыта широкие и мощные, они идеально подходят для расчистки завалов, через которые вы идёте. Вы обучены Выживанию (или другому навыку, если уже обучены Выживанию) и получаете способность навыка Опыт местности. Вы игнорируете сложную местность, вызванную естественной неровностью поверхности, пока находитесь в местности, выбранной вами в способности \"Опыт местности\".","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Minotaur","slug":"minotaur","uuid":"Compendium.pf2e.ancestries.Item.3wQ49DoWFYQgVsq6"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.survival.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Terrain Expertise","grantId":"4tTkRyOQ0VuRBac3"}]}},{"id":"z16zRyLCeTXan0Ae","slug":"fleetwind-centaur","name":"Быстроногий кентавр","cat":"heritages","type":"heritage","text":"Вы обладаете стройной фигурой и способны развивать невероятную скорость на одних только копытах. Ваша Скорость увеличивается на 5 футов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Centaur","slug":"centaur","uuid":"Compendium.pf2e.ancestries.Item.pJkQlFTvpQ5GjZ5e"},"rules":[{"key":"FlatModifier","selector":"land-speed","value":5}]}},{"id":"ClshvrjvBTMm3INX","slug":"bandaagee-vanara","name":"Ванар Бандааги","cat":"heritages","type":"heritage","text":"Ваша семья — одна из многих, кто утверждает, что происходит от царственной миротворческой семьи ванаров называемой Бандааги. Бандааги — самый распространенный вид ванаров. Вы хорошо знакомы с атрибутами цивилизации и легко передвигаетесь по самым людным местам. Вы игнорируете Сложную местность вызванную толпами.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Vanara","slug":"vanara","uuid":"Compendium.pf2e.ancestries.Item.cLtOGIkuSSa4UDHY"},"rules":[]}},{"id":"nUCRd8tmz3C6LM0T","slug":"wajaghand-vanara","name":"Ванар Важаханд","cat":"heritages","type":"heritage","text":"Ваши предки были принуждены к труду бессмертным ракшасом Раваном \"Первым и Последним\". Однако их сообразительность в плену спасла бесчисленное количество жизней, и они больше не пленены, но время оставило на разуме вашего семейства шрамы, которые никогда по-настоящему не заживут, даже через поколения. Вы получаете бонус обстоятельства +1 к спасброскам против эффектов эмоций, и каждый раз, когда вы при спасброске против эффекта эмоций получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Vanara","slug":"vanara","uuid":"Compendium.pf2e.ancestries.Item.cLtOGIkuSSa4UDHY"},"rules":[{"key":"FlatModifier","predicate":["emotion"],"selector":"saving-throw","type":"circumstance","value":1}]}},{"id":"Kq3k1Z6IWGVsLrmg","slug":"lahkgyan-vanara","name":"Ванар Лахъян","cat":"heritages","type":"heritage","text":"Ваши предки ванары могли родиться в образе Рагдьи, но обрели выживание только в служении его врагу — краснолицему Лахъе. У вас острые зубы, чтобы скрежетать и вгрызаться в плоть. Вы можете питаться просто сырым мясом. Вы обладаете безоружной атакой челюстями, которая наносит 1к6 колющего урона. Ваши челюсти относятся к группе оружия \"драка\" и имеют признаки безоружное и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Vanara","slug":"vanara","uuid":"Compendium.pf2e.ancestries.Item.cLtOGIkuSSa4UDHY"},"rules":[]}},{"id":"By1y7HCfVPgX2GmI","slug":"ragdyan-vanara","name":"Ванар Рагдьян","cat":"heritages","type":"heritage","text":"Хранители устоев и рассказчики древних сказаний — ваша семья ведет свой род от тех, кто родился непосредственно по прихоти Рагдьи. Когда вы говорите, другие склонны слушать вас, возможно, благодаря божественной искре вашей связи с Рагдьей. Вы получаете одни чары из списка сакральных заклинаний; эти чары не могут наносить урон или иначе причинять прямой вред. Вы можете по желанию творить эти чары как врождённое сакральное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Vanara","slug":"vanara","uuid":"Compendium.pf2e.ancestries.Item.cLtOGIkuSSa4UDHY"},"rules":[]}},{"id":"kXp8qRh5AgtD4Izi","slug":"witch-kholo","name":"Ведьминский кхоло","cat":"heritages","type":"heritage","text":"Вы лохматый кхоло с тёмным мехом, способный издавать поистине жуткие звуки. Вы можете по желанию сотворять чары Вымысел как врождённое оккультное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону. Дополнительно, вы получаете бонус обстоятельства +1 к проверкам Перевоплотиться и Отвлечь внимание когда используете только свой голос.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kholo","slug":"kholo","uuid":"Compendium.pf2e.ancestries.Item.vxbQ1Yw4qwgjTzqo"},"rules":[{"key":"FlatModifier","predicate":["auditory",{"or":["action:impersonate","action:create-a-diversion"]}],"selector":"deception","type":"circumstance","value":1}]}},{"id":"SqEcb1c3yeoJMxm0","slug":"great-kholo","name":"Великий кхоло","cat":"heritages","type":"heritage","text":"Вы внушительный, мощный кхоло, с рыжевато-коричневой шерстью и коричневыми пятнами на шкуре. Вы получаете 10 Очков Здоровья от своей родословной вместо стандартных 8 и получаете бонус обстоятельства +1 к проверкам Атлетики, чтобы Переставить, Толкнуть или Опрокинуть врагов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kholo","slug":"kholo","uuid":"Compendium.pf2e.ancestries.Item.vxbQ1Yw4qwgjTzqo"},"rules":[{"key":"FlatModifier","predicate":[{"or":["action:shove","action:trip","action:reposition"]}],"selector":"athletics","type":"circumstance","value":1},{"key":"ActiveEffectLike","mode":"override","path":"system.attributes.ancestryhp","value":10}]}},{"id":"PbXqlzRdQbKLQx1R","slug":"old-blood-vishkanya","name":"Вишканья старой крови","cat":"heritages","type":"heritage","text":"Вы имеете прямую матрилинейность с первоначальной группой вишканий на вудранских кораблях, которые прибыли, чтобы вернуть Джалмерэй. С тех пор ваша семья хорошо приспособилась к новой жизни во Внутреннем Море. Вы становитесь обученным Обществу (или другому навыку по вашему выбору, если вы уже обучены Обществу), и получаете на свой выбор способность навыка Аристократическое изящество или Уличная жизнь.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Vishkanya","slug":"vishkanya","uuid":"Compendium.pf2e.ancestries.Item.u1VJEXsVlmh3Fyx0"},"rules":[{"key":"GrantItem","uuid":"{item|flags.system.rulesSelections.feat}"},{"adjustName":false,"choices":[{"value":"Compendium.pf2e.feats-srd.Item.Streetwise"},{"value":"Compendium.pf2e.feats-srd.Item.Courtly Graces"}],"flag":"feat","key":"ChoiceSet","prompt":"Выберите способность навыка."}]}},{"id":"ohOJHeFenX97sBHf","slug":"scalekeeper-vishkanya","name":"Вишканья хранитель чешуи","cat":"heritages","type":"heritage","text":"Вы являетесь членом семьи вишканий в своей общине, и вам поручено вести записи истории и опыта вашего народа. Ваши учёные навыки дают вам быстрый ум. Вы можете раз в день Вспомнить информацию свободным действием .","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Vishkanya","slug":"vishkanya","uuid":"Compendium.pf2e.ancestries.Item.u1VJEXsVlmh3Fyx0"},"rules":[]}},{"id":"dJeiekfqGQ8dkwsO","slug":"wetlander-lizardfolk","name":"Водный людоящер","cat":"heritages","type":"heritage","text":"Ваша семья происходит от самого распространенного наследия людоящеров, и вы привыкли к водной среде. Вы получаете Скорость плавания 15 футов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Lizardfolk","slug":"lizardfolk","uuid":"Compendium.pf2e.ancestries.Item.HWEgF7Gmoq55VhTL"},"rules":[]}},{"id":"5pP2ldUGGixVBkCZ","slug":"aquatic-elf","name":"Водный эльф","cat":"heritages","type":"heritage","text":"Вы — водный эльф, проводящий большую часть своей жизни под водой. Вы можете дышать как воздухом, так и водой, но не можете жить на поверхности неограниченно долго. Вы получаете признак земноводный и Скорость плавания 30 футов. По крайней мере раз в неделю вы должны отдыхать под водой в течение 8 часов. В противном случае вы становитесь Утомлены, и не сможете восстановиться от этого {утомления}, пока не отдохнёте под водой.","level":0,"traits":["земноводный"],"tags":["amphibious"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Elf","slug":"elf","uuid":"Compendium.pf2e.ancestries.Item.PgKmsA2aKdbLU6O0"},"rules":[]}},{"id":"hTl3uc6y1kTuo9ac","slug":"seaweed-leshy","name":"Водорослевый леший","cat":"heritages","type":"heritage","text":"Ваше тело сделано из переплетенных морских водорослей, и под водой вам так же комфортно, как и на суше. Вы получаете Скорость плавания 20 футов, и вы всегда можете дышать под водой. Однако, ваша наземная Скорость снижается на 5 футов (до 20 футов для большинства водорослевых леших).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[{"key":"FlatModifier","selector":"land-speed","value":-5}]}},{"id":"EG0zqAipDIMGBAKz","slug":"homing-drake","name":"Возвращающийся дрейк","cat":"heritages","type":"heritage","text":"У вас короткий, как обрубок, нос и крошечные шипы, напоминающие волоски. У вас может быть ярко окрашенная чешуя или серовато-коричневый цвет. Вы можете сотворять чары Знать путь по желанию как врождённое арканное заклинание. Чары усиливаются до ранга заклинания равного половине вашего уровня округленной вверх.\n\nКроме того, вы всегда знаете расстояние и направление до своего дома. Вы можете назначить новое место своим домом после того, как проведёте там 1 неделю, но одновременно у вас может быть только один назначенный дом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dragonet","slug":"dragonet","uuid":"Compendium.pf2e.ancestries.Item.B5Ewz31nJBOzHSMg"},"rules":[]}},{"id":"t9HOJelfwDo3RBii","slug":"warrior-jotunborn","name":"Воин ётунорожденный","cat":"heritages","type":"heritage","text":"Ваше выносливое тело сделало вас идеальным рекрутом для боя. Размер кости урона вашего кулака увеличивается до 1к6. Вы не получаете штраф при совершении смертельной атаки кулаком.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Боевой клич!","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Jotunborn","slug":"jotunborn","uuid":"Compendium.pf2e.ancestries.Item.gayvFCiQcGNCA7aM"},"rules":[]}},{"id":"0vaeOoECfVD5EGbq","slug":"warrenbred-hobgoblin","name":"Выросший в лабиринте хобгоблин","cat":"heritages","type":"heritage","text":"Ваши предки жили под землёй. Ваши уши больше, чем у других хобгоблинов, и чувствительны к эхо. Пока вы под землёй, когда вы целитесь во врага, который Скрыт Спрятан для вас, уменьшите КС чистой проверки до 3 для {скрытой} цели и до 9 для {спрятанной} цели. В дополнение, если при совершении проверки Акробатики, чтобы Протиснуться, вы получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Hobgoblin","slug":"hobgoblin","uuid":"Compendium.pf2e.ancestries.Item.piNLXUrm9iaGqD2i"},"rules":[]}},{"id":"lBSO9RuEUv2P4rnp","slug":"gandharva","name":"Гандхарва","cat":"heritages","type":"heritage","text":"Вы происходите от самопровозглашённных музыкантов, поэтов и танцоров богов, а ваше тело частично гуманоидное, частично лошадиное или птичье. Если вы обретаете крылья, они приобретают окрас самых разных ярких цветов. Из-за вашей небесной связи обычай любых заклинаний или магических способностей, полученных благодарю наследию или способности спрайта, становится сакральным вместо обычного.\n\nВы становитесь обучены Выступлению (или другому навыку по вашему выбору, если уже обучены Выступлению), и можете сотворять Призыв музыкального инструмента как врождённые сакральные чары.","level":0,"traits":["Спрайт"],"tags":["sprite"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sprite","slug":"sprite","uuid":"Compendium.pf2e.ancestries.Item.TRqoeYfGAFjQbviF"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.performance.rank","value":1}]}},{"id":"TDc9MXLXkgEFoKdD","slug":"flexible-catfolk","name":"Гибкий коточеловек","cat":"heritages","type":"heritage","text":"Вы унаследовали гибкость, превосходящую большинство гуманоидов. Узкие пространства, которые не настолько тесны, чтобы требовать от вас Протиснуться, не считаются для вас Сложной местностью. Дополнительно, вы получаете бонус обстоятельства +1 к проверкам при попытке Вырваться.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Catfolk","slug":"catfolk","uuid":"Compendium.pf2e.ancestries.Item.972EkpJOPv9KkQIW"},"rules":[{"key":"FlatModifier","predicate":["action:escape"],"selector":["acrobatics","athletics","attack"],"type":"circumstance","value":1}]}},{"id":"7p9HtLzWBHc18JDW","slug":"deep-rat","name":"Глубинная крыса","cat":"heritages","type":"heritage","text":"Ваши предки жили глубже под землей, чем остальные крысолюди, что дает вам способность видеть в темноте. Вы получаете Ночное зрение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ratfolk","slug":"ratfolk","uuid":"Compendium.pf2e.ancestries.Item.P6PcVnCkh4XMdefw"},"rules":[{"key":"Sense","selector":"darkvision"}]}},{"id":"6egx1zhQx2s6BEa1","slug":"abyssal-merfolk","name":"Глубинный мерфолк","cat":"heritages","type":"heritage","text":"Вы живете далеко-далеко под поверхностью океана. Ваш хвост может напоминать хаулиода или рыбу-удильщика, у вас могут быть светящиеся глаза или полупрозрачная кожа. У глубинных мерфолков дурная репутация, но они могут существовать даже в самых беспросветных уголках. Вы получаете ночное зрение и иммунны к сокрушительному давлению океанских глубин.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Merfolk","slug":"merfolk","uuid":"Compendium.pf2e.ancestries.Item.FUqZRllwn6kmFA8K"},"rules":[{"key":"Sense","selector":"darkvision"}]}},{"id":"wn4EbYk1QN3tyFhh","slug":"deep-orc","name":"Глубинный орк","cat":"heritages","type":"heritage","text":"Ваши мозолистые руки и красные глаза говорят о жизни, проведенной в кромешной темноте горных пещер, где вы научились сражаться на скалистых утесах и выживать с минимальными ресурсами. Вы получаете способности навыка Опыт местности (Подземная) и Боевой альпинист.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Orc","slug":"orc","uuid":"Compendium.pf2e.ancestries.Item.lSGWXjcbOa6O5fTx"},"rules":[{"key":"GrantItem","preselectChoices":{"terrain":"underground"},"uuid":"Compendium.pf2e.feats-srd.Item.Terrain Expertise","grantId":"4tTkRyOQ0VuRBac3"},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Combat Climber","grantId":"09PurtIanNUPfNRq"}]}},{"id":"k4AU5tjtngDOIqrB","slug":"deep-fetchling","name":"Глубинный фечлинг","cat":"heritages","type":"heritage","text":"Ваши предки жили в самых глубоких и коварных регионах Теневого плана. Вы можете отбрасывать более плотную тень, иметь замедленный пульс или чувствовать себя комфортнее в объятиях тьмы. При выборе этого наследия вы получаете сопротивление холоду или пустоте, равное половине вашего уровня (минимум 1).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fetchling","slug":"fetchling","uuid":"Compendium.pf2e.ancestries.Item.hIA3qiUsxvLZXrFP"},"rules":[{"choices":[{"label":"Холод","value":"cold"},{"label":"Пустота","value":"void"}],"flag":"heritageDeepFetchling","key":"ChoiceSet","prompt":"Выберите тип энергии для сопротивления"}]}},{"id":"etkuQkjkNLPLnjkA","slug":"wellspring-gnome","name":"Гном-исток","cat":"heritages","type":"heritage","text":"Над вами имеет большую власть какой-то другой источник магии, нежели природная магия вашего фейского происхождения. Эта связь может исходить от оккультного плана или древней оккультного отголоска; божества, небожителя или беса; потока магии, оставленного войной магов; или древней рунной магии.\n\nВыберите арканный, сакральный или оккультный обычай. Вы получаете одни чары из списка заклинаний этого магического обычая (Списки заклинаний). Вы можете по желанию сотворять эти чары как врождённое заклинание выбранного обычая. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону. Всякий раз, когда вы получаете врождённое природное заклинание от способности гномьей родословной, измените его магический обычай с природного на выбранный вами для этого наследия.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Gnome","slug":"gnome","uuid":"Compendium.pf2e.ancestries.Item.CYlfsYLJcBOgqKtD"},"rules":[]}},{"id":"D3hTAqgwSank8OyO","slug":"fey-touched-gnome","name":"Гном-фея","cat":"heritages","type":"heritage","text":"Кровь фей настолько сильна в вас, что вы действительно один из них. В дополнение к признакам гном и гуманоид, вы получаете признак фея. Выберите одни чары из списка природных заклинаний (Природные чары). Вы можете сотворять эти чары по желанию, как врождённое природное заклинание. Эти чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону. Раз в день, вы можете изменить эти чары на другие из того же списка, помедитировав для того, чтобы настроить себя на Первый Мир; это 10-минутная активность с признаком концентрация.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Gnome","slug":"gnome","uuid":"Compendium.pf2e.ancestries.Item.CYlfsYLJcBOgqKtD"},"rules":[]}},{"id":"XeXWsvcWU3Zaj5WC","slug":"chameleon-gnome","name":"Гном-хамелеон","cat":"heritages","type":"heritage","text":"Цвет ваших волос и кожи изменчив, возможно, из-за скрытой магии. Вы можете медленно изменять яркость и точный цвет, а окрас вашего тела может быть разным, что позволяет вам создавать узоры или другие красочные рисунки. Это занимает одно действие для незначительных локальных изменений и вплоть до часа для значительных изменений по всему телу. Пока вы спите, цвета меняются сами по себе в соответствии с вашими снами, придавая вам необычную окраску каждое утро. Когда вы находитесь в местности, где ваша окраска примерно похожа на окружающую среду (например, цвет лесной зелени в лесу), вы можете использовать одно действие (1 действие) для небольших локальных изменений, которые помогут вам слиться с окружающей средой. Это даёт вам бонус обстоятельства +2 к проверкам Скрытности, пока цвета или узоры вашего окружения не изменятся.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Gnome","slug":"gnome","uuid":"Compendium.pf2e.ancestries.Item.CYlfsYLJcBOgqKtD"},"rules":[{"key":"FlatModifier","predicate":["coloration-matches"],"selector":"stealth","type":"circumstance","value":2}]}},{"id":"IZqIVO1IOK3fAp30","slug":"mountaineer-samsaran","name":"Горный самсар","cat":"heritages","type":"heritage","text":"Ваши прошлые воплощения обитали в пещерах покрытых снегом горных вершин Тянь-Ся, и теперь ваше тело лучше переносит мороз и бури. Вы получаете сопротивление холоду, равное половине вашего уровня (минимум 1). Вы считаете эффекты Холодной окружающей среды так, как если бы они были на одну ступень легче (невероятный холод становится экстремальным, экстремальный холод становится сильным и так далее).","level":0,"traits":["Самсар"],"tags":["samsaran"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Samsaran","slug":"samsaran","uuid":"Compendium.pf2e.ancestries.Item.l7vjMIbPAUvEIosU"},"rules":[]}},{"id":"nXQxlmjH24Eb8h2Q","slug":"battle-ready-orc","name":"Готовый к битве орк","cat":"heritages","type":"heritage","text":"Вы происходите из рода устрашающих полевых командиров. Вы становитесь обучены Запугиванию и получаете способность навыка Запугивающий взгляд.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Orc","slug":"orc","uuid":"Compendium.pf2e.ancestries.Item.lSGWXjcbOa6O5fTx"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Intimidating Glare","grantId":"xQMz6eDgX75WX2ce"},{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.intimidation.rank","value":1}]}},{"id":"87h0jepQuzIbN7jN","slug":"fungus-leshy","name":"Грибной леший","cat":"heritages","type":"heritage","text":"Ваше тело было сделано из грибов, которые растут в тени пещер и деревьев, и вы чувствуете себя как дома в темных пещерах и ущельях. Вы получаете ночное зрение. Вместо признака растение вы получаете признак грибковый.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[{"key":"Sense","selector":"darkvision"}]}},{"id":"gfXSF1TafBAmZo2u","slug":"grig","name":"Григ","cat":"heritages","type":"heritage","text":"У вас задняя часть сверчка, и вы обожаете искусство и музыку. Ваши ноги сверчка дают вам бонус обстоятельства +2 к проверкам Атлетики для Прыжка в высоту или Прыжка в длину, и вы получаете Призрачный звук как врождённые природные чары.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sprite","slug":"sprite","uuid":"Compendium.pf2e.ancestries.Item.TRqoeYfGAFjQbviF"},"rules":[{"key":"FlatModifier","label":"Для Прыжка в высоту или Прыжка в длину","predicate":[{"or":["action:high-jump","action:long-jump"]}],"selector":"athletics","type":"circumstance","value":2}]}},{"id":"6JKdAZGa8odFzleS","slug":"farsight-goloma","name":"Дальновидный голома","cat":"heritages","type":"heritage","text":"Ваши глаза адаптировались видеть больше в менее предпочитаемых условиях. Вы получаете сумеречное зрение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goloma","slug":"goloma","uuid":"Compendium.pf2e.ancestries.Item.c4secsSNG2AO7I5i"},"rules":[{"key":"Sense","selector":"low-light-vision"}]}},{"id":"UaD5VDoFlILEmbyz","slug":"dhampir","name":"Дампир","cat":"heritages","type":"heritage","text":"Вы — отпрыск вампира, наполовину живой и наполовину нежить, одаренный сверхъестественным обаянием и грацией, бескровной бледностью и удлиненными резцами. В дополнение к признакам своей родословной, вы получаете признак дампир. У вас Исцеление пустотой, а это означает, что вам вредит урон жизненности, а эффекты пустоты исцеляют, как если бы вы были нежитью. Вы также получаете Сумеречное зрение или Ночное зрение, если ваша родословная уже имеет сумеречное зрение. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей дампира и способностей своей родословной.\n\nДампир","level":0,"traits":["дампир"],"tags":["dhampir"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"key":"ActiveEffectLike","mode":"override","path":"system.attributes.hp.negativeHealing","value":true},{"key":"Sense","selector":"low-light-vision"},{"key":"Sense","predicate":["self:low-light-vision:from-ancestry"],"selector":"darkvision"}]}},{"id":"yL6944LrPo2HNdEJ","slug":"ancient-blooded-dwarf","name":"Дварф древней крови","cat":"heritages","type":"heritage","text":"Дварфские герои прошлого могли избавиться от магии своих врагов, и часть этой сопротивляемости проявляется в вас. Вы получаете реакцию Зов древней крови.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dwarf","slug":"dwarf","uuid":"Compendium.pf2e.ancestries.Item.BYj5ZvlXZdpaEgA6"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Call on Ancient Blood"}]}},{"id":"5CqsBKCZuGON53Hk","slug":"forge-dwarf","name":"Дварф кузницы","cat":"heritages","type":"heritage","text":"У вас от предков есть удивительная адаптация к жаркой среде, которые населяли пылающие пустыни или вулканические пещеры под землей. Это дает вам сопротивление огню равное половине вашего уровня (минимум 1), и вы считаете эффекты Жаркой окружающей среды так, как если бы они были на одну ступень лучше (невероятная жара становится экстремальной, экстремальная становится сильной и т.д.)","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dwarf","slug":"dwarf","uuid":"Compendium.pf2e.ancestries.Item.BYj5ZvlXZdpaEgA6"},"rules":[]}},{"id":"kRDsVbhdBVeSlpBa","slug":"anvil-dwarf","name":"Дварф наковальни","cat":"heritages","type":"heritage","text":"Вы потомок знаменитого ремесленника и обладаете собственным удивительным талантом. Другие дварфы могли бы счесть это благословением твоих предков или самого \"Отца кузни\", в зависимости от того, где вы выросли. Вы обучены Ремеслу (или другому навыку, если уже обучены Ремеслу) и получаете способность Специализация в ремесле, но вместо одной, вы можете выбрать две разные специализации.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dwarf","slug":"dwarf","uuid":"Compendium.pf2e.ancestries.Item.BYj5ZvlXZdpaEgA6"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.crafting.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Specialty Crafting","grantId":"QLeMH5mQgh28sa5o"},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Specialty Crafting","grantId":"QLeMH5mQgh28sa5o"}]}},{"id":"UV2sABrTC5teOXTE","slug":"strong-blooded-dwarf","name":"Дварф сильной крови","cat":"heritages","type":"heritage","text":"Ваша кровь течет сильно и энергично, и вы можете избавиться от токсинов. Вы получаете сопротивление яду, равное половине вашего уровня (минимум 1), и каждый из ваших успешных спасбросков против недуга-яда снижает его стадию на 2, или на 1 для вирулентного яда. Каждый критический успех против действующего яда снижает его стадию на 3, или на 2 для вирулентного яда.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dwarf","slug":"dwarf","uuid":"Compendium.pf2e.ancestries.Item.BYj5ZvlXZdpaEgA6"},"rules":[]}},{"id":"MeMAAtUlZmFgKSMF","slug":"elemental-heart-dwarf","name":"Дварф стихийного сердца","cat":"heritages","type":"heritage","text":"Будь то из-за связи с кузней Торага, азерами Плана Огня или другим источником, вы можете излучать взрыв энергии. Дварфы Мбе'ке и Таралу из Просторов Муанги верят, что это наследие — дар драконов или духов стихий. Выберите один из следующих типов урона: кислота, холод, электричество или огонь. Будучи однажды выбранным, его нельзя изменить. Вы получаете активность Энергетическая эманация.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dwarf","slug":"dwarf","uuid":"Compendium.pf2e.ancestries.Item.BYj5ZvlXZdpaEgA6"},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"flags.system.elementalHeartDwarf.damageType","value":"{item|flags.system.rulesSelections.elementalHeartDwarf}"},{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Energy Emanation"},{"choices":[{"label":"Кислота","value":"acid"},{"label":"Холод","value":"cold"},{"label":"Электричество","value":"electricity"},{"label":"Огонь","value":"fire"}],"flag":"elementalHeartDwarf","key":"ChoiceSet","prompt":"Выберите тип урона Стихийного сердца"}]}},{"id":"VTtXwBxrfRUXSL38","slug":"death-warden-dwarf","name":"Дварф страж гробниц","cat":"heritages","type":"heritage","text":"Ваши предки в течение многих поколений были хранителями гробниц, и к вам перешла сила, которую они культивировали, чтобы защищаться от смерти. Если при спасброске против эффекта пустоты или эффекта, исходящего от существа-нежити, вы получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dwarf","slug":"dwarf","uuid":"Compendium.pf2e.ancestries.Item.BYj5ZvlXZdpaEgA6"},"rules":[]}},{"id":"85tRKGZUTFa6pKpG","slug":"oathkeeper-dwarf","name":"Дварф хранитель клятвы","cat":"heritages","type":"heritage","text":"Взрослея, вы никогда не пытались лгать для получения того, что хотели, и даже когда это необходимо, ложь заставляет вас чувствовать себя неловко. Особенно верующие могли даже подумать, что вы благословлены дварфийским богом долга, Колсом.\n\nВы получаете бонус обстоятельства +1 к проверкам Восприятия для Понимания намерения и КС Восприятия против попыток Лгать вам.\n\nБолее того, вы получаете бонус обстоятельства +2 к проверкам Дипломатии, чтобы убедить других, что вы говорите правду, когда вы действительно говорите правду, и получаете штраф обстоятельства −4, чтобы \"Лгать\" и к вашему КС Обмана против \"Понять намерение\".","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dwarf","slug":"dwarf","uuid":"Compendium.pf2e.ancestries.Item.BYj5ZvlXZdpaEgA6"},"rules":[{"key":"FlatModifier","label":"Чтобы Понять намерение","predicate":["action:sense-motive"],"selector":"perception","slug":"oathkeeper-dwarf-to-sense-motive","type":"circumstance","value":1},{"key":"FlatModifier","label":"Сказать правду","predicate":["tell-truth"],"selector":"diplomacy","slug":"oathkeeper-dwarf-tell-the-truth","type":"circumstance","value":2},{"key":"FlatModifier","label":"Лгать","predicate":["action:lie"],"selector":"deception","slug":"oathkeeper-dwarf-lie","type":"circumstance","value":-4},{"hideIfDisabled":true,"key":"FlatModifier","predicate":["action:lie"],"selector":"perception","type":"circumstance","value":1},{"hideIfDisabled":true,"key":"FlatModifier","predicate":["action:sense-motive"],"selector":"deception","type":"circumstance","value":-4}]}},{"id":"TXBsQbzDg1AjJnop","slug":"dijiang","name":"Дижиланг","cat":"heritages","type":"heritage","text":"Вы имеете форму безликого кожистого шара с коротким мехом, шестью ногами и связью с первозданным хаосом. Хотя у вас нет лица, головы, рта, глаз и ушей, вы каким-то образом можете слышать, говорить, видеть, есть и дышать (хотя непонятно, как именно). Из-за своей неустойчивой природы вы часто реагируете на раздражители непредсказуемым образом.\n\nКогда вы получаете провал (но не критический) при спасброске против эффекта эмоций, результат считается успехом.","level":0,"traits":["Спрайт"],"tags":["sprite"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sprite","slug":"sprite","uuid":"Compendium.pf2e.ancestries.Item.TRqoeYfGAFjQbviF"},"rules":[]}},{"id":"9FlpW1nSczH8f85v","slug":"hungerseed","name":"Дитя голода","cat":"heritages","type":"heritage","text":"Одним из ваших родителей был они или дитя голода. Вы обладаете парой рогов, длина которых может заметно варьироваться. У вас могут быть и другие наследуемые признаки, будь то необычный цвет кожи, клыки и когти, или третий глаз на лбу. Вы получаете признак они. Вы получаете безоружную атаку рогами, наносящую 1к6 колющего урона и относящуюся к группе оружия \"драка\". Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей дитяти голода и способностей родословной вашего второго родителя.\n\nДитя голода","level":0,"traits":["они"],"tags":["oni"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[]}},{"id":"fROPRHGyUn4PgcER","slug":"longsnout-rat","name":"Длинномордая крыса","cat":"heritages","type":"heritage","text":"Ваша морда даёт вам более острое обоняние, чем у большинства крысолюдов. Вы получаете неточное сенсорное чувство нюха с дистанцией 30 футов. Это значит, что вы можете использовать свое чувство запаха, чтобы определять местоположение существа, как описано в Особых чувствах. Обычно Мастер удвоит дистанцию если вы с подветренной стороны от существа или уменьшит вдвое, если против ветра.\n\nДополнительно, вы получаете бонус обстоятельства +2 к проверкам Восприятия на Поиск существа или объекта в пределах дистанции нюха.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ratfolk","slug":"ratfolk","uuid":"Compendium.pf2e.ancestries.Item.P6PcVnCkh4XMdefw"},"rules":[{"acuity":"imprecise","key":"Sense","range":30,"selector":"scent"},{"key":"FlatModifier","predicate":["action:seek",{"lte":["target:distance",30]}],"selector":"perception","type":"circumstance","value":2}]}},{"id":"cDElVLonQvUK3vVk","slug":"whipfang-nagaji","name":"Длинношеий нагаджи","cat":"heritages","type":"heritage","text":"У вас длинная, гибкая шея, которая может поразительно скручиваться, как змея. Ваши обманчиво мощные мышцы позволяют вам кусать с неожиданного расстояния и удивительной скоростью. Вы получаете действие Поднять шею.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Nagaji","slug":"nagaji","uuid":"Compendium.pf2e.ancestries.Item.J7T7bDLaQGoY1sMF"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Raise Neck"}]}},{"id":"JtrZ2TcPXP1uIcmd","slug":"virtuous-tanuki","name":"Добродетельный тануки","cat":"heritages","type":"heritage","text":"Многие тануки носят с собой кувшин с алкоголем, чтобы напоминать себе о добродетели, и по этим меркам вы действительно добродетельны. Вы получаете сопротивление яду, равное половине вашего уровня (минимум 1). Вы можете есть и пить когда имеете Тошноту. Вы не можете стать недееспособным из-за обычного алкоголя, если сами того не хотите.","level":0,"traits":["Тануки"],"tags":["tanuki"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tanuki","slug":"tanuki","uuid":"Compendium.pf2e.ancestries.Item.pILFsoGsUQkVF5dZ"},"rules":[]}},{"id":"gf2CfXocpIQgRsCY","slug":"dokkaebi-goblin","name":"Доккэби гоблин","cat":"heritages","type":"heritage","text":"Ваши предки владели магией, основанной на иллюзиях, благодаря чему вы обладаете врождённым пониманием этой магии. Вы можете сотворять Вымысел как врождённые оккультные чары, по желанию. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой вверх. Вы также получаете бонус обстоятельства +1 к спасброскам Воли против иллюзий.","level":0,"traits":["Гоблин"],"tags":["goblin"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goblin","slug":"goblin","uuid":"Compendium.pf2e.ancestries.Item.sQfjTMDaZbT9DThq"},"rules":[{"key":"FlatModifier","predicate":["item:trait:illusion"],"selector":"will","type":"circumstance","value":1}]}},{"id":"WxcbLvufI6JBpLt0","slug":"spindly-anadi","name":"Долговязый анади","cat":"heritages","type":"heritage","text":"Ваши конечности в обеих формах исключительно длинные, что позволяет вам перемещаться с удивительной ловкостью. Ваша Скорость увеличивается с 25 до 30 футов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Anadi","slug":"anadi","uuid":"Compendium.pf2e.ancestries.Item.TQEqWqc7BYiadUdY"},"rules":[{"key":"FlatModifier","selector":"land-speed","value":5}]}},{"id":"8oqAuez98yqAgteo","slug":"house-drake","name":"Домашний дрейк","cat":"heritages","type":"heritage","text":"У вас ярко-синяя и фиолетовая чешуя, серебристые зубы и когти. Ваши челюсти считаются серебряными, и вы получаете бонус обстоятельства +1 к броскам урона против бесов. Вы добавляете Дьявольский язык к своим языкам.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dragonet","slug":"dragonet","uuid":"Compendium.pf2e.ancestries.Item.B5Ewz31nJBOzHSMg"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"system.build.languages.granted","value":{"slug":"diabolic","source":"{item|name}"}},{"key":"FlatModifier","predicate":["target:trait:fiend"],"selector":["jaws-damage"],"type":"circumstance","value":1}]}},{"id":"Qr1foFh24dkTqe1s","slug":"tidepool-dragonet","name":"Дракончик прилива","cat":"heritages","type":"heritage","text":"У вас стройное тело, похожее на угря, покрытое лазурной чешуей. Ваши крылья расположены вдоль тела, как массивные плавники, что делает вас подходящим для жизни к воде.\n\nВы получаете признак земноводный, Скорость плавания 15 футов. Вы добавляете Талассический язык к своим языкам.","level":0,"traits":["земноводный"],"tags":["amphibious"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dragonet","slug":"dragonet","uuid":"Compendium.pf2e.ancestries.Item.B5Ewz31nJBOzHSMg"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"system.build.languages.granted","value":{"slug":"thalassic","source":"{item|name}"}}]}},{"id":"cbbXIV4QBred4lM5","slug":"dragonblood","name":"Драконья кровь","cat":"heritages","type":"heritage","text":"Вы каким-то образом происходите от дракона. Внешне это может проявляться в виде пары драконьих рогов, чешуйчатой кожи или даже хвоста, а может быть, у вас появится внутренний резерв драконьей силы. В дополнение к признакам своей родословной, вы получаете признак драконья кровь. Добавьте Драконий к списку дополнительных языков вашей родословной (позволяя вам выбрать его в качестве языка, если ваш модификатор Интеллекта положительный). Если при спасброске против эффекта страха вы получаете успех, результат считается критическим успехом. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей драконьей крови и способностей своей родословной.\n\nДраконья кровь","level":0,"traits":["драконья кровь"],"tags":["dragonblood"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"actorFlag":true,"choices":[{"label":"Адамантиновый дракон","value":{"damageType":"bludgeoning","dragon":"adamantine","save":"reflex","shape":"cone","speed":"burrow","tradition":"primal"}},{"label":"Силовой дракон","value":{"damageType":"force","dragon":"barrage","save":"reflex","shape":"cone","speed":"none","tradition":"arcane"}},{"label":"Болотный дракон","value":{"damageType":"acid","dragon":"bog","save":"reflex","shape":"cone","speed":"swim","tradition":"primal"}},{"label":"Солевой дракон","value":{"damageType":"bludgeoning","dragon":"brine","save":"reflex","shape":"line","speed":"swim","tradition":"primal"}},{"label":"Пепельный дракон","value":{"damageType":"fire","dragon":"cinder","save":"reflex","shape":"cone","speed":"none","tradition":"primal"}},{"label":"Облачный дракон","value":{"damageType":"electricity","dragon":"cloud","save":"reflex","shape":"cone","speed":"none","tradition":"primal"}},{"label":"Дракон-конспиратор","value":{"damageType":"poison","dragon":"conspirator","save":"fortitude","shape":"cone","speed":"climb","tradition":"occult"}},{"label":"Коралловый дракон","value":{"damageType":"bludgeoning","dragon":"coral","save":"reflex","shape":"line","speed":"swim","tradition":"primal"}},{"label":"Кристаллический дракон","value":{"damageType":"piercing","dragon":"crystal","save":"reflex","shape":"cone","speed":"none","tradition":"primal"}},{"label":"Дракон восторга","value":{"damageType":"spirit","dragon":"delight","save":"reflex","shape":"cone","speed":"none","tradition":"divine"}},{"label":"Дракон отчаяния","value":{"damageType":"sonic","dragon":"despair","save":"will","shape":"cone","speed":"none","tradition":"occult"}},{"label":"Дьявольский дракон","value":{"damageType":"fire","dragon":"diabolic","save":"reflex","shape":"cone","speed":"none","tradition":"divine"}},{"label":"Эмпирейский дракон","value":{"damageType":"spirit","dragon":"empyreal","save":"reflex","shape":"cone","speed":"none","tradition":"divine"}},{"label":"Дракон-душеприказчик","value":{"damageType":"sonic","dragon":"executor","save":"reflex","shape":"cone","speed":"none","tradition":"divine"}},{"label":"Лесной дракон","value":{"damageType":"piercing","dragon":"forest","save":"reflex","shape":"cone","speed":"none","tradition":"primal"}},{"label":"Дракон достатка","value":{"damageType":"force","dragon":"fortune","save":"reflex","shape":"cone","speed":"none","tradition":"arcane"}},{"label":"Рогатый дракон","value":{"damageType":"poison","dragon":"horned","save":"fortitude","shape":"cone","speed":"swim","tradition":"primal"}},{"label":"Магматический дракон","value":{"damageType":"fire","dragon":"magma","save":"reflex","shape":"cone","speed":"burrow","tradition":"primal"}},{"label":"Дракон миража","value":{"damageType":"mental","dragon":"mirage","save":"will","shape":"cone","speed":"climb","tradition":"arcane"}},{"label":"Дракон-пересмешник","value":{"damageType":"bludgeoning","dragon":"mocking","save":"reflex","shape":"cone","speed":"none","tradition":"occult"}},{"label":"Клятвенный дракон","value":{"damageType":"spirit","dragon":"oath","save":"will","shape":"cone","speed":"none","tradition":"divine"}},{"label":"Дракон знамений","value":{"damageType":"mental","dragon":"omen","save":"will","shape":"cone","speed":"none","tradition":"occult"}},{"label":"Фазовый дракон","value":{"damageType":"force","dragon":"phase","save":"reflex","shape":"cone","speed":"none","tradition":"arcane"}},{"label":"Загробный дракон","value":{"damageType":"spirit","dragon":"requiem","save":"will","shape":"line","speed":"swim","tradition":"divine"}},{"label":"Дракон воскрешения","value":{"damageType":"void","dragon":"resurrection","save":"fortitude","shape":"cone","speed":"none","tradition":"divine"}},{"label":"Дракон измороси","value":{"damageType":"cold","dragon":"rime","save":"reflex","shape":"cone","speed":"swim","tradition":"primal"}},{"label":"Рунный дракон","value":{"damageType":"fire","dragon":"rune","save":"reflex","shape":"cone","speed":"none","tradition":"arcane"}},{"label":"Дракон-мудрец","value":{"damageType":"mental","dragon":"sage","save":"will","shape":"cone","speed":"none","tradition":"occult"}},{"label":"Морской дракон","value":{"damageType":"bludgeoning","dragon":"sea","save":"reflex","shape":"cone","speed":"swim","tradition":"arcane"}},{"label":"Небесный дракон","value":{"damageType":"electricity","dragon":"sky","save":"reflex","shape":"cone","speed":"none","tradition":"divine"}},{"label":"Монарший дракон","value":{"damageType":"mental","dragon":"sovereign","save":"will","shape":"cone","speed":"none","tradition":"occult"}},{"label":"Дракон грозовой короны","value":{"damageType":"electricity","dragon":"stormcrown","save":"reflex","shape":"line","speed":"none","tradition":"primal"}},{"label":"Хрональный дракон","value":{"damageType":"force","dragon":"time","save":"will","shape":"cone","speed":"none","tradition":"arcane"}},{"label":"Теневой дракон","value":{"damageType":"void","dragon":"umbral","save":"reflex","shape":"cone","speed":"none","tradition":"occult"}},{"label":"Подземный дракон","value":{"damageType":"fire","dragon":"underworld","save":"reflex","shape":"cone","speed":"burrow","tradition":"arcane"}},{"label":"Дракон-визирь","value":{"damageType":"fire","dragon":"vizier","save":"reflex","shape":"cone","speed":"swim","tradition":"occult"}},{"label":"Стрижающий дракон","value":{"damageType":"void","dragon":"vorpal","save":"will","shape":"cone","speed":"none","tradition":"arcane"}},{"label":"Вопящий дракон","value":{"damageType":"sonic","dragon":"wailing","save":"fortitude","shape":"cone","speed":"none","tradition":"arcane"}},{"label":"Шепчущий дракон","value":{"damageType":"mental","dragon":"whisper","save":"will","shape":"cone","speed":"none","tradition":"occult"}},{"label":"Дракон желания","value":{"damageType":"mental","dragon":"wish","save":"will","shape":"cone","speed":"climb","tradition":"arcane"}}],"flag":"dragonblood","key":"ChoiceSet"}]}},{"id":"zcO93E8gAW1tDYKk","slug":"draxie","name":"Дракси","cat":"heritages","type":"heritage","text":"Вы родственник Фейских дракончиков, и прослеживаете своё наследие к смерти могущественного фейского дракончика из Первого мира. Вы получаете телепатическое касание, позволяющее вам общаться беззвучно и исключительно мысленно с любым существом, которого вы касаетесь, если вы с ним говорите на одном языке.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sprite","slug":"sprite","uuid":"Compendium.pf2e.ancestries.Item.TRqoeYfGAFjQbviF"},"rules":[]}},{"id":"EEvA4uj8h3zDiAfP","slug":"treedweller-goblin","name":"Древесный гоблин","cat":"heritages","type":"heritage","text":"Вы особенно хорошо приспособились к жизни в лесной среде. Пока вы в лесу или джунглях, то получаете бонус обстоятельства +2 к проверкам Скрытности на Спрятаться и Красться, проверок Выживания на Проживание, и вашему КС Выживания для Заметать следы.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goblin","slug":"goblin","uuid":"Compendium.pf2e.ancestries.Item.sQfjTMDaZbT9DThq"},"rules":[{"key":"FlatModifier","label":"Treedweller Goblin (Subsist)","predicate":["action:subsist"],"selector":"survival","type":"circumstance","value":2},{"key":"FlatModifier","label":"Treedweller Goblin (Hide or Sneak)","predicate":[{"or":["action:hide","action:sneak"]}],"selector":"stealth","type":"circumstance","value":2}]}},{"id":"Nd9hdX8rdYyRozw8","slug":"ancient-elf","name":"Древний эльф","cat":"heritages","type":"heritage","text":"За свою долгую жизнь вы занимались множеством всего. Типичный древний эльф имеет возраст хотя бы 100 лет, однако на усмотрение Мастера вы можете быть моложе. Выберите класс отличный от вашего. Вы получаете способность посвящения мультикласса для этого класса, хоть и не соответствуете предварительным условиям по уровню. Вы всё ещё должны соответствовать другим предварительным условиям, чтобы получить эту способность.\n\nЗаметка : Для этого наследия требуется жизнь продолжительностью с эльфийскую (особенность, которой не обладают полуэльфы) и поэтому оно не может быть выбрано полуэльфом с помощью способности Эльфийский атавизм, а лишь полноценными эльфами.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Elf","slug":"elf","uuid":"Compendium.pf2e.ancestries.Item.PgKmsA2aKdbLU6O0"},"rules":[{"key":"GrantItem","uuid":"{item|flags.system.rulesSelections.ancientElf}"},{"choices":{"filter":["item:category:class","item:trait:dedication","item:trait:multiclass"],"itemType":"feat"},"flag":"ancientElf","key":"ChoiceSet","prompt":"Выберите мультиклассовую способность посвящения."}]}},{"id":"CMf0qluB0LXWReew","slug":"ancient-ash","name":"Древний ясень","cat":"heritages","type":"heritage","text":"Ваша память остра и ясна, и вы столько всего помните. Вы помните затишье перед бурей и почву после дождя, едкий привкус магии и шепот песни. Вы помните все это. Вы становитесь обучены 1 навыку на свой выбор. На 5-м уровне вы становитесь экспертом этого навыка.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ghoran","slug":"ghoran","uuid":"Compendium.pf2e.ancestries.Item.tSurOqRcfumadTfr"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.{item|flags.system.rulesSelections.skill}.rank","value":"ternary(gte(@actor.level,5),2,1)"},{"choices":{"config":"skills"},"flag":"skill","key":"ChoiceSet","prompt":"Выберите навык."}]}},{"id":"tLd8Qg82AwEbbmgX","slug":"dromaar","name":"Дромаар","cat":"heritages","type":"heritage","text":"Орочья сила сделала вашу родословную сильнее. У вас кожа зеленого оттенка и другие признаки орочьего происхождения. Вы получаете признаки орк и дромаар, а также сумеречное зрение. Когда получаете способность родословной, то вы также можете выбирать из способностей орка и дромаара в дополнение к способностям вашей родословной.","level":0,"traits":["дромаар"],"tags":["dromaar"],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"key":"Sense","selector":"low-light-vision"},{"key":"ActiveEffectLike","mode":"override","path":"system.details.ancestry.versatile","value":"orc"},{"key":"ActiveEffectLike","mode":"add","path":"system.details.ancestry.countsAs","value":"dromaar"},{"key":"ActiveEffectLike","mode":"add","path":"system.details.ancestry.countsAs","value":"orc"}]}},{"id":"7wdeVadvchdM0aPK","slug":"mistbreath-azarketi","name":"Дышащий туманом азаркет","cat":"heritages","type":"heritage","text":"Вы произошли от азаркетов, которые мигрировали на сушу, в места, которые могли удовлетворить их потребность в воде. Со временем ваши люди адаптировались к жизни на суше в культурном и физическом плане, в результате чего даже появились азаркеты, рожденные с человеческими волосами, как и их предки ацланты. Вам больше не нужно погружаться в воду каждые 24 часа, чтобы сохранять кожу, и вместо этого можете распылять воду на кожу или протирать ее водой, чтобы жить комфортно. Ваша сухопутная Скорость 25 футов, а Скорость плавания лишь 15 футов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Azarketi","slug":"azarketi","uuid":"Compendium.pf2e.ancestries.Item.yFoojz6q3ZjvceFw"},"rules":[{"key":"FlatModifier","selector":"swim-speed","value":-15},{"key":"FlatModifier","selector":"land-speed","value":5}]}},{"id":"gyoN45SVfRZwHMkk","slug":"irongut-goblin","name":"Железнобрюхий гоблин","cat":"heritages","type":"heritage","text":"Вы способны питаться пищей, которую большинство других сочтут испорченной. Вы можете питаться плохой едой в поселении, не используя активность Проживание во время отдыха, пока можете легко находить мусор. Вы можете есть и пить когда вас Тошнит.\n\nВы получаете бонус обстоятельства +2 к спасброскам против недугов, против получения {тошноты}, и чтобы избавиться от {тошноты}. Когда при спасброске Стойкости, к которому применяется этот бонус, вы получаете успех, результат считается критическим успехом. Все эти преимущества применяются только когда недуг или состояние являются результатом чего-то, что вы проглотили.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goblin","slug":"goblin","uuid":"Compendium.pf2e.ancestries.Item.sQfjTMDaZbT9DThq"},"rules":[{"key":"FlatModifier","predicate":["item:trait:ingested",{"or":["inflicts:sickened","item:type:affliction"]}],"selector":"saving-throw","slug":"irongut-save-bonus","type":"circumstance","value":2}]}},{"id":"XQp3uReCgoXS8hCJ","slug":"ironhoof-centaur","name":"Железнокопытный кентавр","cat":"heritages","type":"heritage","text":"Ваши копыта невероятно сильны и служат грозным оружием. Вы получаете безоружную атаку копытом, которая наносит 1к6 дробящего урона. Она относится к группе \"драка\" и имеет признаки безоружное и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Centaur","slug":"centaur","uuid":"Compendium.pf2e.ancestries.Item.pJkQlFTvpQ5GjZ5e"},"rules":[]}},{"id":"Rz0hZM6CFvX5LnXg","slug":"pearl-dragonet","name":"Жемчужный дракончик","cat":"heritages","type":"heritage","text":"У вас перламутровая чешуя и круглое тело с короткими лапками, маленькими крылышками и длинным хвостом. Форма вашего тела позволяет вам принимать удары на себя и откатываться в сторону.\n\nОтскочить в сторону: Реакция","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dragonet","slug":"dragonet","uuid":"Compendium.pf2e.ancestries.Item.B5Ewz31nJBOzHSMg"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Bounce Away"}]}},{"id":"ViKRoVgog172r163","slug":"vivacious-gnome","name":"Жизнерадостный гном","cat":"heritages","type":"heritage","text":"У вас есть невероятно сильная связь с позитивной энергией, которая течет через Первый Мир, что защищает вашу жизненную силу от энергии пустоты. Вы получаете сопротивление урону пустотой, равное половине вашего уровня (минимум 1). Когда у вас есть состояние Обречен, оно действует на вас, как если бы оно было на 1 ниже, чем на самом деле ({обречен 1} не имеет эффекта, {обречен 2} приводит к вашей смерти с При смерти 3 и т.д.).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Gnome","slug":"gnome","uuid":"Compendium.pf2e.ancestries.Item.CYlfsYLJcBOgqKtD"},"rules":[]}},{"id":"Cv7BOjuziOQ0PO9r","slug":"windup-poppet","name":"Заводная кукла","cat":"heritages","type":"heritage","text":"Вы сделаны в основном из мягких металлов, таких как олово или серебро, а ваша жизненная сила обитает в исключительном множестве заводных механизмов в глубине вашего тела. При условии, что вы заводите металлические пружины в своем теле несколько раз в день, то вы не нуждаетесь в пище или воде, чтобы выжить. Как и другим куклам, вам всё ещё надо дышать, чтобы вентилировать свои внутренние механизмы, и спать, чтобы давать своим механизмам отдых.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Poppet","slug":"poppet","uuid":"Compendium.pf2e.ancestries.Item.6F2fSFC1Eo1JdpY4"},"rules":[]}},{"id":"pJ395g22dKNoufIK","slug":"nascent","name":"Зарождающийся","cat":"heritages","type":"heritage","text":"Хотя большинство кашриши полностью адаптируются к окружающей среде к моменту достижения совершеннолетия, некоторые сохраняют нереализованный потенциал вплоть до зрелого возраста, прежде чем раскрыть его. Вы получаете способность родословной кашриши 1-го уровня, для которой вы соответствуете предварительным условиям, если таковые имеются.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kashrishi","slug":"kashrishi","uuid":"Compendium.pf2e.ancestries.Item.dw2K1AJR9mQ25nDP"},"rules":[{"key":"GrantItem","uuid":"{item|flags.system.rulesSelections.nascent}"},{"adjustName":false,"choices":{"filter":["item:level:1","item:category:ancestry","item:trait:kashrishi"],"itemType":"feat"},"flag":"nascent","key":"ChoiceSet","prompt":"Выберите способность родословной 1-го уровня."}]}},{"id":"QOm3CGFgvUyEi9Bs","slug":"defensive-automaton","name":"Защитный автоматон","cat":"heritages","type":"heritage","text":"Ваша конструкция особенно прочна. Вы можете выдерживать больше урона чем другие автоматоны. Вы получаете 10 ОЗ от своей родословной вместо 8. Также вы получаете способность Живучесть.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Automaton","slug":"automaton","uuid":"Compendium.pf2e.ancestries.Item.kYsBAJ103T44agJF"},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"system.attributes.ancestryhp","value":10},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Toughness","grantId":"AmP0qu7c5dlBSath"}]}},{"id":"GAn2cdhBE9Bqa85s","slug":"beastkin","name":"Зверолюд","cat":"heritages","type":"heritage","text":"Кровь зверя течёт по вашим венам, наделяя вас свирепостью и мощью животных. Универсальное наследие зверолюда могут взять только существа с признаком гуманоид. Выберите вид животного, такое как акула, волк, летучая мышь, орёл, оса, паук или тиранозавр. Это вид животного, связанного с вашим наследием и известного как присущее вам. Гибридный облик зверолюда является его естественным. В дополнение к признакам своей родословной, вы получаете признаки чудовище и зверолюд.\n\nВы получаете умение Изменение облика. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей зверолюда и способностей своей родословной.\n\nЗверолюд","level":0,"traits":["зверолюд"],"tags":["beastkin"],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"allowDuplicate":false,"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Change Shape","grantId":"knaVRiZ2QNteat1P"}]}},{"id":"FLWUYM2XxYwnIDQf","slug":"xyloshi","name":"Зилоши","cat":"heritages","type":"heritage","text":"У вас выдающиеся мышцы шеи, что позволяет вам использовать свой лицевой рог в качестве инструмента или оружия. Вы получаете безоружную атаку рогом, которая наносит 1к6 колющего урона. Ваш рог относится к группе оружия \"драка\" и имеет признаки безоружное и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kashrishi","slug":"kashrishi","uuid":"Compendium.pf2e.ancestries.Item.dw2K1AJR9mQ25nDP"},"rules":[]}},{"id":"6dMd4JG0ndrObEUj","slug":"winter-catfolk","name":"Зимний коточеловек","cat":"heritages","type":"heritage","text":"У вас есть толстый слой меха, защищающий вас от холода. Вы получаете сопротивление холоду, равное половине вашего уровня (минимум 1). Вы считаете эффекты Холодной окружающей среды так, как если бы они были на одну ступень легче (невероятный холод становится экстремальным, экстремальный холод становится сильным и так далее).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Catfolk","slug":"catfolk","uuid":"Compendium.pf2e.ancestries.Item.972EkpJOPv9KkQIW"},"rules":[]}},{"id":"hwRWx3hWx8ahBdz0","slug":"winter-kholo","name":"Зимний кхоло","cat":"heritages","type":"heritage","text":"Вы выносливый кхоло, покрытый густым ворсистым мехом, который позволяет вам выживать в суровые зимы на холодных территориях. Вы получаете сопротивление холоду, равное половине вашего уровня (минимум 1). Вы считаете эффекты Холодной окружающей среды так, как если бы они были на одну ступень легче (невероятный холод становится экстремальным, экстремальный холод становится сильным и так далее).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kholo","slug":"kholo","uuid":"Compendium.pf2e.ancestries.Item.vxbQ1Yw4qwgjTzqo"},"rules":[]}},{"id":"pZ1u2ScWrBXSaAqQ","slug":"winter-orc","name":"Зимний орк","cat":"heritages","type":"heritage","text":"Ваши предки выжили в холодном климате. Вы становитесь обучены Выживанию, и считаете эффекты Холодной окружающей среды так, как если бы они были на одну ступень лучше (невероятный холод становится экстремальным, экстремальный холод становится сильным и так далее).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Orc","slug":"orc","uuid":"Compendium.pf2e.ancestries.Item.lSGWXjcbOa6O5fTx"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.survival.rank","value":1}]}},{"id":"KO33MNyY9VqNQmbZ","slug":"wintertouched-human","name":"Зимостойкий человек","cat":"heritages","type":"heritage","text":"Сила зимы течёт сквозь вас. Это наследие наиболее распространено в Иррисене среди Ядвиг, благодаря их происхождению от Бабы-Яги, а так же среди некоторых Эрутаков, получившим силу от духов. Вы получаете сопротивление холоду, равное половине вашего уровня (минимум 1), и считаете эффекты Холодной окружающей среды так, как если бы они были на одну ступень лучше (невероятный холод становится экстремальным, экстремальный становится сильным и т.д.).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Human","slug":"human","uuid":"Compendium.pf2e.ancestries.Item.IiG7DgeLWYrSNXuX"},"rules":[]}},{"id":"EHDYVhJcZ9uPUjfZ","slug":"toy-poppet","name":"Игрушечная кукла","cat":"heritages","type":"heritage","text":"Вы похожи на крошечную детскую игрушку или куколку, но вы не позволяете своему маленькому размеру мешать вам радоваться жизни. Ваш размер Крошечный вместо Маленького. Как и другие крошечные существа, вы автоматически не получаете небольшое укрытие, находясь в пространстве более крупного существа, но обстоятельства могут позволить вам Укрыться. Вы можете покупать оружия, доспехи и другие предметы для своего размера с теми же характеристиками, что и у обычного снаряжения, за исключением того, что у оружия ближнего боя под вас досягаемость 0 (или досягаемость на 5 футов меньше обычной, если оно имеет признак досягаемость). Вы можете входить в пространство другого существа, что крайне важно, потому что обычно вы должны войти в пространство существа, чтобы атаковать его Ударами ближнего боя! Не забудьте скорректировать Массу предметов и ограничение Массы для игрового персонажа Крошечного размера (см. раздел Предметы и размеры). Информация о том, как поступать с Крошечными игровыми персонажами, включая правила для попыток ехать верхом на других персонажах, находится в разделе Игровые персонажи крошечного размера.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Poppet","slug":"poppet","uuid":"Compendium.pf2e.ancestries.Item.6F2fSFC1Eo1JdpY4"},"rules":[]}},{"id":"idJ2lSKEmmwqG5eT","slug":"shifting-skeleton","name":"Изменчивый скелет","cat":"heritages","type":"heritage","text":"Созданные из костей различных изменяющих форму существ, изменчивые скелеты сохраняют определенную способность к реконфигурации, позволяющую им менять форму. Вы получаете действие Переставлять кости.","level":0,"traits":[],"tags":[],"rarity":"редкий","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Skeleton","slug":"skeleton","uuid":"Compendium.pf2e.ancestries.Item.58rL5sg2y4arW1i5"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Rearrange Bones"}]}},{"id":"2cii5ZkBsJ4DYdd2","slug":"cactus-leshy","name":"Кактусовый леший","cat":"heritages","type":"heritage","text":"Ваше тело покрыто шипами. Вы получаете безоружную атаку шипами, которая наносит 1к6 колющего урона. Ваши шипы относятся к группе \"драка\", и имеют признаки безоружное и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[]}},{"id":"1w4npGmPzgdZw3Na","slug":"kaleidoscopic-athamaru","name":"Калейдоскопический атамару","cat":"heritages","type":"heritage","text":"Ваша чешуя переливается на свету спектром цветов. В областях яркого или тусклого света вы получаете бонус обстоятельства +1 к проверкам Выступления. Вы также получаете реакцию Ослепить ищущего.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Athamaru","slug":"athamaru","uuid":"Compendium.pf2e.ancestries.Item.Cg1AMgp3zrGmimWd"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Dazzle Seeker"},{"key":"FlatModifier","predicate":[{"or":["light:bright","light:dim"]}],"selector":"performance","type":"circumstance","value":1}]}},{"id":"VSyOvtgJ1ZNpIVgC","slug":"rock-dwarf","name":"Каменный дварф","cat":"heritages","type":"heritage","text":"Ваши предки жили и работали среди великих древних гор или земляных глубин. Когда вы встаете на ноги, это делает вас твердым, как скала. Вы получаете бонус обстоятельства +2 к своим КС Стойкости и КС Рефлекса против попыток сделать Перестановку, Толкнуть или Опрокинуть вас. Еще этот бонус применяется к спасброскам против заклинаний или эффектов, которые пытаются сбить вас с ног, чтобы вы упали Ничком.\n\nДополнительно, если любой эффект заставит вас сдвинуться на 10 футов или более, то вы двигаетесь только на половину этого расстояния.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dwarf","slug":"dwarf","uuid":"Compendium.pf2e.ancestries.Item.BYj5ZvlXZdpaEgA6"},"rules":[{"hideIfDisabled":true,"key":"FlatModifier","label":"против Толкнуть или Опрокинуть","predicate":[{"or":["action:shove","action:trip","action:reposition"]}],"selector":["fortitude","reflex"],"type":"circumstance","value":2},{"key":"FlatModifier","label":"против эффектов ничком","predicate":["inflicts:prone"],"selector":"saving-throw","type":"circumstance","value":2}]}},{"id":"5GdtQsVHy3cvK6fC","slug":"camouflage-tripkee","name":"Камуфлированный трипки","cat":"heritages","type":"heritage","text":"Узор на вашей коже естественным образом имитирует природный ландшафт и растительность. Выберите один из следующих типов местности: болотистая, водная или лесная. Вы можете Прятаться и Красться в выбранной местности не нуждаясь в укрытии или Сокрытии.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tripkee","slug":"tripkee","uuid":"Compendium.pf2e.ancestries.Item.hXM5jXezIki1cMI2"},"rules":[]}},{"id":"eFsD7W6hnK33jlDQ","slug":"sewer-rat","name":"Канализационная крыса","cat":"heritages","type":"heritage","text":"Вы происходите из длинного рода исоки, относящегося к сообществу, живущему канализации под большим поселением. Вы иммунны к грязной лихорадке. Вы получаете бонус обстоятельства +1 к спасброскам от болезней и ядов. Если при спасброске против болезни или яда вы получаете успех, результат считается критическим успехом. Если у вас есть другое умение, которое должно улучшить этот спасбросок таким же образом (например, особенность воина Закаленный в боях), если при спасброске вы получаете критический провал, результат считается обычным провалом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ratfolk","slug":"ratfolk","uuid":"Compendium.pf2e.ancestries.Item.P6PcVnCkh4XMdefw"},"rules":[{"key":"FlatModifier","predicate":[{"or":["item:trait:disease","item:trait:poison"]}],"selector":"saving-throw","type":"circumstance","value":1}]}},{"id":"5WkhF3JYISElgMLL","slug":"kanchil","name":"Канчил","cat":"heritages","type":"heritage","text":"У вас голова малого оленёка и копыта вместо ног, и репутация умной и убедительной личности, способной выкрутиться из сложной ситуации с помощью игры слов и везения. Вы становитесь обучены Обману (или другому навыку по вашему выбору, если уже обучены Обману). Вы получаете бонус обстоятельства +1 к проверкам Обмана, чтобы Лгать, когда специально пытаетесь избежать опасности или наказания (например, убедить дракона не есть вас), к КС Обмана против проверок Понять намерение, чтобы раскрыть эту ложь, и к броскам инициативы, когда используете для них Обман.","level":0,"traits":["Спрайт"],"tags":["sprite"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sprite","slug":"sprite","uuid":"Compendium.pf2e.ancestries.Item.TRqoeYfGAFjQbviF"},"rules":[{"key":"FlatModifier","predicate":[{"or":[{"and":[{"or":["action:lie","action:sense-motive"]},"to-avoid-danger"]},"initiative"]}],"selector":"deception","type":"circumstance","value":1},{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.deception.rank","value":1}]}},{"id":"13vilUcBjqMV2gxP","slug":"climbing-animal","name":"Карабкающееся животное","cat":"heritages","type":"heritage","text":"Вы — животное, чьи конечности приспособлены для хватания и лазания. Вы можете быть ловким и готовым к использованию инструментов, как шимпанзе или выдра, а можете быть просто быстрым лазальщиком, как медведь, енот или ленивец.\n\nУ вас Скорость 20 футов, Скорость карабканья 20 футов и одна атака животного на ваш выбор (обычно, коготь, кулак или челюсти).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Awakened Animal","slug":"awakened-animal","uuid":"Compendium.pf2e.ancestries.Item.GFOgV3MzWkYwJoJW"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.ancestryfeatures.Item.Animal Attack","grantId":"oj532l4YXqzedBBn"}]}},{"id":"PQuJEYI0UFl8W7fH","slug":"cataphract-fleshwarp","name":"Катафракт деформированный","cat":"heritages","type":"heritage","text":"Ваш закаленный в боях скелет снабжен дополнительными хрящами и мышцами, помогающими ходить в доспехах по обширным областям, а кожа покрыта крошечными отростками гибкого, упругого кератина, чтобы оптимизировать сцепление и распределение веса доспехов. Вы получаете способность Мастерство доспехов.\n\nЕсли вы от своего класса становитесь обучены ношению всех видов доспехов, то вместо этого вы становитесь обучены Атлетике (или навыку по вашему выбору, если уже обучены Атлетике) и получаете навык Помощь с доспехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fleshwarp","slug":"fleshwarp","uuid":"Compendium.pf2e.ancestries.Item.FXlXmNBFiiz9oasi"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Armor Proficiency","grantId":"BStw1cANwx5baL6d"}]}},{"id":"3aKeX3q9hRdxgP1J","slug":"mottle-coat-centaur","name":"Кентавр в крапинку","cat":"heritages","type":"heritage","text":"Ваш подшерсток окрашен в крапинку или полосками, что даёт вам естественный камуфляж в родной среде. Выберите тип местности из следующих: арктический, болотный, горный, лесной, полевой или пустынный. В выбранной местности, вы получаете бонус обстоятельства +1 к проверкам Скрытности, чтобы Прятаться или Красться, и к проверкам Обмана, чтобы делать Финт.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Centaur","slug":"centaur","uuid":"Compendium.pf2e.ancestries.Item.pJkQlFTvpQ5GjZ5e"},"rules":[{"key":"FlatModifier","predicate":["terrain:{item|flags.system.rulesSelections.terrain}",{"or":["action:hide","action:sneak","action:feint"]}],"selector":["stealth","deception"],"type":"circumstance","value":1},{"choices":[{"label":"Арктическая","value":"arctic"},{"label":"Пустынная","value":"desert"},{"label":"Лесная","value":"forest"},{"label":"Горная","value":"mountain"},{"label":"Равнинная","value":"plain"},{"label":"Болотная","value":"swamp"}],"flag":"terrain","key":"ChoiceSet","prompt":"Выберите тип местности."}]}},{"id":"raDHBXYpc2MvWWgh","slug":"stoutheart-centaur","name":"Кентавр каменного сердца","cat":"heritages","type":"heritage","text":"Вы — выносливый кентавр, твердый духом и сильный сердцем. Вы получаете 10 Очков Здоровья от своей родословной, вместо стандартных 8, и получаете бонус обстоятельства +1 к проверкам Акробатики, чтобы Балансировать, и к КС Рефлекса, чтобы избежать Опрокидывания.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Centaur","slug":"centaur","uuid":"Compendium.pf2e.ancestries.Item.pJkQlFTvpQ5GjZ5e"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.attributes.ancestryhp","priority":51,"value":10},{"key":"FlatModifier","predicate":["action:balance"],"selector":"acrobatics","type":"circumstance","value":1},{"key":"FlatModifier","predicate":["action:trip"],"selector":"reflex-dc","type":"circumstance","value":1}]}},{"id":"1FmcZqnmDm8H0DRB","slug":"budding-speaker-centaur","name":"Кентавр начинающий оратор","cat":"heritages","type":"heritage","text":"Вы родились с искрой магии, которая может поставить вас на путь Гласа природы или Гласа веры . Выберите сакральный или природный обычай. Если вы выбрали сакральный, вы — Глас веры. Если вы выбрали природный, вы — Глас природы. Этот выбор нельзя изменить. Вы получаете одни чары из списка выбранного обычая. Вы можете сотворять это заклинание по желанию как врождённое заклинание. усиливается до ранга заклинания, равного половине вашего уровня, округленного в большую сторону. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Centaur","slug":"centaur","uuid":"Compendium.pf2e.ancestries.Item.pJkQlFTvpQ5GjZ5e"},"rules":[{"choices":[{"label":"Сакральный","value":"faithspeaker"},{"label":"Природный","value":"greenspeaker"}],"key":"ChoiceSet","rollOption":"centaur-speaker"}]}},{"id":"2GmWdSNbH4yx9pzY","slug":"ponygait-centaur","name":"Кентавр с походкой пони","cat":"heritages","type":"heritage","text":"Вы меньше, чем большинство других кентавров, но не менее быстроходны. Вместо Большого, ваш размер — Средний. Вы получаете бонус обстоятельства +1 к спасброскам Рефлекса.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Centaur","slug":"centaur","uuid":"Compendium.pf2e.ancestries.Item.pJkQlFTvpQ5GjZ5e"},"rules":[{"key":"FlatModifier","selector":"reflex","type":"circumstance","value":1}]}},{"id":"8Uw1E3L2Mgo6PxwB","slug":"kijimuna-gnome","name":"Киджимуна гном","cat":"heritages","type":"heritage","text":"Ваши предки жили на деревьях и ловили рыбу во всех водах Тянь Ся. Вы получаете на выбор одно из следующих преимуществ. Этот выбор нельзя изменить.\n\nВы можете взобраться на любой баньян. Вы получаете способность Боевой альпинист, и если при проверке Атлетики, чтобы \"Карабкаться\", вы получаете успех, результат считается критическим успехом.\n\nВы можете поймать любую рыбу. Вы получаете Скорость плавания 15 футов.","level":0,"traits":["Гном"],"tags":["gnome"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Gnome","slug":"gnome","uuid":"Compendium.pf2e.ancestries.Item.CYlfsYLJcBOgqKtD"},"rules":[{"key":"GrantItem","predicate":["kijimuna-gnome:climb"],"uuid":"Compendium.pf2e.feats-srd.Item.Combat Climber","grantId":"09PurtIanNUPfNRq"},{"choices":[{"label":"Карабканье","value":"climb"},{"label":"Плавание","value":"swim"}],"key":"ChoiceSet","prompt":"Выберите тип движения.","rollOption":"kijimuna-gnome"}]}},{"id":"SienSObWb4deLQig","slug":"palace-echoes-kitsune","name":"Кицунэ дворцовых отголосков","cat":"heritages","type":"heritage","text":"Вы — потомок кицунэ, обладавших таким даром убеждения, что они могли зайти на рассвете во дворец и к исходу дня стать тем, кто дёргает за ниточки в тени трона. Вы получаете действие Подстрекающий шёпот.\n\nВаша альтернативная форма — обычная гуманоидная родословная Среднего размера, распространённая там, где вы выросли (обычно человек), называемая бесхвостой формой.","level":0,"traits":["Кицунэ"],"tags":["kitsune"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kitsune","slug":"kitsune","uuid":"Compendium.pf2e.ancestries.Item.4BL5wf1VF9feC2rY"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Nudging Whisper"}]}},{"id":"Wk4HyaZtC1j221i1","slug":"earthly-wilds-kitsune","name":"Кицунэ земных чащ","cat":"heritages","type":"heritage","text":"Вы существо материального мира, сроднившееся скорее с дикой природой, чем с городским обществом. Вы получаете безоружную атаку челюстями, которая наносит 1к6 колющего урона. Ваши челюсти относятся к группе \"драка\", и имеют признаки безоружное и точное. Ваша альтернативная форма — лиса, имеющая характеристики Формы вредителя 1-го ранга.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kitsune","slug":"kitsune","uuid":"Compendium.pf2e.ancestries.Item.4BL5wf1VF9feC2rY"},"rules":[]}},{"id":"kHT9dFJt5yTjeYoB","slug":"frozen-wind-kitsune","name":"Кицунэ морозного ветра","cat":"heritages","type":"heritage","text":"Ваши предки пересекли Корону Мира или поселились на заснеженных вершинах. Вы получаете сопротивляемость холоду, равную половине вашего уровня (минимум 1). Вы считаете эффекты Холодной окружающей среды так, как если бы они были на одну ступень легче (невероятный холод становится экстремальным, экстремальный холод становится сильным и так далее). Ваша альтернативная форма — обычная гуманоидная родословная Среднего размера, распространенная там, где вы выросли (обычно человек), называемая бесхвостой формой.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kitsune","slug":"kitsune","uuid":"Compendium.pf2e.ancestries.Item.4BL5wf1VF9feC2rY"},"rules":[]}},{"id":"IFg2tqmAFFnU8UNU","slug":"celestial-envoy-kitsune","name":"Кицунэ небесный посланник","cat":"heritages","type":"heritage","text":"Будь то из-за милости Дайкицу или верующих предков, у вас сильная связь с божественным, что дает вам определенную защиту. Вы получаете реакцию Призвать небесную привилегию. Ваша альтернативная форма — обычная гуманоидная родословная Среднего размера, распространенная там, где вы выросли (обычно человек), называемая бесхвостой формой.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kitsune","slug":"kitsune","uuid":"Compendium.pf2e.ancestries.Item.4BL5wf1VF9feC2rY"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Invoke Celestial Privilege"}]}},{"id":"mBH1L01kYmB8EL56","slug":"empty-sky-kitsune","name":"Кицунэ пустого неба","cat":"heritages","type":"heritage","text":"Ваш дух открыт запредельным тайнам, что дает вам огромный доступ к магии кицунэ. Вы получаете способность родословной Знакомство с магией кицунэ. Ваша альтернативная форма — обычная гуманоидная родословная Среднего размера, распространенная там, где вы выросли (обычно человек), называемая бесхвостой формой.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kitsune","slug":"kitsune","uuid":"Compendium.pf2e.ancestries.Item.4BL5wf1VF9feC2rY"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Kitsune Spell Familiarity","grantId":"Zz7isE8Td2xDWqR8"}]}},{"id":"NWbdAN5gDse0ad7C","slug":"dark-fields-kitsune","name":"Кицунэ темных полей","cat":"heritages","type":"heritage","text":"Вы можете использовать свой тревожащий внешний вид, чтобы изощренно Деморализовать других. Когда вы так делаете, действие \"Деморализовать\" теряет слуховой признак и получает визуальный, а вы не получаете штраф, когда пытаетесь \"Деморализовать\" существо не понимающее вашего языка. Еще вы получаете реакцию Бодрящий страх. Ваша альтернативная форма — лиса, имеющая характеристики Формы вредителя 1-го ранга.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kitsune","slug":"kitsune","uuid":"Compendium.pf2e.ancestries.Item.4BL5wf1VF9feC2rY"},"rules":[{"allowDuplicate":false,"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Invigorating Fear"}]}},{"id":"2hLDilS6qbjHxgVS","slug":"dogtooth-tengu","name":"Клыкастый тэнгу","cat":"heritages","type":"heritage","text":"Помимо клюва, у вас во рту есть несколько неровных острых зубов. Некоторые легенды утверждают, что ваши мощные челюсти могут прокусить даже сталь. Хотя вы ещё не так сильны, ваши клыки могут оставлять ужасные раны. Ваша безоружная атака клювом получает признак смертельное к8.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tengu","slug":"tengu","uuid":"Compendium.pf2e.ancestries.Item.18xDKYPDBLEv2myX"},"rules":[]}},{"id":"ZW8GX14n3ZGievK1","slug":"tunnelflood-kobold","name":"Кобольд затопленных туннелей","cat":"heritages","type":"heritage","text":"Вы выросли в лабиринте, пересечённом подводными ходами, естественными или выкопанными, и попали под влияние могущественной водной сущности или существа первородной воды. Вы получаете Скорость плавания 15 футов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kobold","slug":"kobold","uuid":"Compendium.pf2e.ancestries.Item.7oQxL6wgsokD3QXG"},"rules":[]}},{"id":"G61eBHmsQaPM4Xge","slug":"heavenscribe-kobold","name":"Кобольд небесный писарь","cat":"heritages","type":"heritage","text":"Ваша связь с мудрыми и небесными императорскими драконами заставила других искать вашего совета. Вы можете говорить на Драконьем языке. Всякий раз, когда вы критически проваливаете проверку Дипломатии при попытке Произвести впечатление или высказать Просьбу, результат считается обычным провалом.","level":0,"traits":["Кобольд"],"tags":["kobold"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kobold","slug":"kobold","uuid":"Compendium.pf2e.ancestries.Item.7oQxL6wgsokD3QXG"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"system.build.languages.granted","value":{"slug":"draconic","source":"{item|name}"}}]}},{"id":"5A1wMPdzN1OWE4cY","slug":"caveclimber-kobold","name":"Кобольд пещерный скалолаз","cat":"heritages","type":"heritage","text":"Вы живете в доме выстроенном вертикально и являетесь прирожденным верхолазом. Вы получаете способность навыка Боевой альпинист, даже если не соответствуете предварительным условиям. Вы можете использовать когтистые ноги и хвост, чтобы Карабкаться, благодаря чему руки остаются свободными. Дополнительно, если вы совершаете успешную проверку Атлетики, чтобы \"Карабкаться\", результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kobold","slug":"kobold","uuid":"Compendium.pf2e.ancestries.Item.7oQxL6wgsokD3QXG"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Combat Climber","grantId":"09PurtIanNUPfNRq"}]}},{"id":"WaCn0mcivFv1omNK","slug":"strongjaw-kobold","name":"Кобольд с крепкой челюстью","cat":"heritages","type":"heritage","text":"Ваш род известен своими мощными челюстями и острыми зубами, либо для защиты от естественных хищников, либо как знак поклонения могучему чудовищу. Вы получаете безоружную атаку челюстями, которая наносит 1к6 колющего урона. Ваши челюсти относятся к группе \"драка\", и имеют признаки безоружное и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kobold","slug":"kobold","uuid":"Compendium.pf2e.ancestries.Item.7oQxL6wgsokD3QXG"},"rules":[]}},{"id":"VRyX00OuPGsJSurM","slug":"spellhorn-kobold","name":"Кобольд с магическим рогом","cat":"heritages","type":"heritage","text":"Поскольку вы вылупились вблизи мощного источника магии, её след течет по вашим венам. Выберите одни чары из арканного списка заклинаний. Вы можете по желанию колдовать его как врождённое арканное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону. Вы становитесь обучены атаке заклинаниями и КС заклинаний, и ваш ключевой атрибут колдовства — Харизма.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kobold","slug":"kobold","uuid":"Compendium.pf2e.ancestries.Item.7oQxL6wgsokD3QXG"},"rules":[]}},{"id":"P8BP1un5BTrwXoBy","slug":"dragonscaled-kobold","name":"Кобольд с чешуёй дракона","cat":"heritages","type":"heritage","text":"Благодаря связи вашего логова с драконом, ваша чешуя прочнее, чем у других кобольдов. Вы получаете 10 Очков Здоровья от своей родословной вместо 6. Вы получаете бонус обстоятельства +1 к спасброскам против дыхания дракона, эффектов с признаком сон и эффектов, которые Парализуют вас.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kobold","slug":"kobold","uuid":"Compendium.pf2e.ancestries.Item.7oQxL6wgsokD3QXG"},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"system.attributes.ancestryhp","value":10},{"key":"FlatModifier","predicate":[{"or":["item:trait:sleep","inflicts:paralyzed",{"and":["action:breath-weapon","origin:trait:dragon"]}]}],"selector":"saving-throw","type":"circumstance","value":1}]}},{"id":"dbj1cbkYeAAdkDSM","slug":"elementheart-kobold","name":"Кобольд стихийного сердца","cat":"heritages","type":"heritage","text":"Когда вы вылупились, на вас оставило след существо, сильно связанное с одним из Стихийных Планов, например на элементале или гении. Выберите воду, воздух, дерево, землю, металл или огонь для вашего стихийного покровителя. Вы получаете сопротивление, равное половине вашего уровня (минимум 1) к типу урона, связанное с вашем стихийным покровителем: кислота для воды, холод для воздуха, яд для дерева, электричество для земли, звук для металла, или огонь для огня.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kobold","slug":"kobold","uuid":"Compendium.pf2e.ancestries.Item.7oQxL6wgsokD3QXG"},"rules":[{"choices":[{"label":"Воздух","value":"cold"},{"label":"Земля","value":"electricity"},{"label":"Огонь","value":"fire"},{"label":"Металл","value":"sonic"},{"label":"Вода","value":"acid"},{"label":"Дерево","value":"poison"}],"flag":"element","key":"ChoiceSet","prompt":"Выберите стихию."}]}},{"id":"bLhIBwqdjTiVJ5qm","slug":"clawed-catfolk","name":"Когтистый коточеловек","cat":"heritages","type":"heritage","text":"У вашей семьи есть особенно длинные острые когти, способные грозным ударом нанести кровоточащие раны. Вы получаете безоружную атаку когтями, которая наносит 1к6 рубящего урона. Ваши когти относятся к группе \"драка\" и имеют признаки безоружное, быстрое и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Catfolk","slug":"catfolk","uuid":"Compendium.pf2e.ancestries.Item.972EkpJOPv9KkQIW"},"rules":[]}},{"id":"qM566kCXljkOpocA","slug":"taloned-tengu","name":"Когтистый тэнгу","cat":"heritages","type":"heritage","text":"Ваши когти столь же острые и сильные, как и ваш клюв. Вы получаете безоружную атаку когтями, которая наносит 1к4 рубящего урона. Ваши когти относятся к группе \"драка\", и имеют признаки безоружное, быстрое, универсальное К и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tengu","slug":"tengu","uuid":"Compendium.pf2e.ancestries.Item.18xDKYPDBLEv2myX"},"rules":[]}},{"id":"6KhxY5ArGFhLF7r1","slug":"thorned-rose","name":"Колючая роза","cat":"heritages","type":"heritage","text":"Ваши прекрасные лепестки и, казалось бы, гладкая кожа скрывают безмолвные шипы, способные пронзить кого-то неосторожного. Ваше тело покрыто опасными острыми шипами, чтобы отпугнуть тех, кто может посчитать вас своей добычей. Вы получаете реакцию Опасные шипы.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ghoran","slug":"ghoran","uuid":"Compendium.pf2e.ancestries.Item.tSurOqRcfumadTfr"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Wicked Thorns"}]}},{"id":"9Iu1gFEuvVz9zaYU","slug":"spined-azarketi","name":"Колючий азаркет","cat":"heritages","type":"heritage","text":"Ваши плавники скрывают выпускаемые ядовитые шипы. У вас есть дистанционная безоружная атака шипами, наносящая 1к4 урона ядом, имеющая шаг дистанции 10 футов и относящаяся к группе оружия \"дротик\".","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Azarketi","slug":"azarketi","uuid":"Compendium.pf2e.ancestries.Item.yFoojz6q3ZjvceFw"},"rules":[]}},{"id":"mZqaKQkvadBbNubM","slug":"compact-skeleton","name":"Компактный скелет","cat":"heritages","type":"heritage","text":"Для задач, требующих деликатности, останки гномов, гоблинов и полуросликов подходят лучше, чем останки более крупных существ. Эти более мелкие и проворные скелеты удачно помещаются в дорожном сундуке, их можно пропихнуть в узкие пространства и легче избежать обнаружения. Ваш размер — Маленький, а не Средний. Вы получаете способность Быстро протиснуться даже если вы не обучены Акробатике. Тесные пространства, не являющиеся настолько тесными, чтобы требовалась активность Протиснуться, для вас не являются Сложной местностью.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Skeleton","slug":"skeleton","uuid":"Compendium.pf2e.ancestries.Item.58rL5sg2y4arW1i5"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Quick Squeeze","grantId":"3G8xUlgCjRmRJNfP"}]}},{"id":"4BczMv4EnLcgrEJE","slug":"coral-athamaru","name":"Коралловый атамару","cat":"heritages","type":"heritage","text":"Кораллы покрывают участки вашего тела, обеспечивая естественный защитный слой. Коралловые атамару часто выбирают Коралловых симбионтов и другие связанные с ними способности родословной. Корраловые пластины являются средним доспехом из группы латных, дающая бонус предмета +4 к КБ, и ограничение модификатора Ловкости к КБ равное +1, штраф проверки −2, штраф Скорости −5 футов, значение Силы +3 и признаки обтекаемый и удобный. Вы никогда не сможете надеть другой доспех или снять кораллы. Вы можете гравировать на кораллы руны доспехов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Athamaru","slug":"athamaru","uuid":"Compendium.pf2e.ancestries.Item.Cg1AMgp3zrGmimWd"},"rules":[]}},{"id":"CZx9HMmoOwcpkLY8","slug":"root-leshy","name":"Корневой леший","cat":"heritages","type":"heritage","text":"Ваше тело состоит из крепких корней, которые крепко прикрепляют вас к земле. От своей родословной вы получаете 10 ОЗ вместо 8 ОЗ. Вы можете обходиться без солнечного света в течение 2 недель, прежде чем начнете голодать. Вы получаете бонус обстоятельства +2 к вашим КС Стойкости и КС Рефлекса против попыток сделать Перестановку, Толкнуть или Опрокинуть вас. Еще этот бонус применяется к спасброскам от заклинаний или эффектов, которые пытаются сдвинуть вас или уронить вас Ничком.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"system.attributes.ancestryhp","value":10},{"hideIfDisabled":true,"key":"FlatModifier","label":"против Толкнуть или Опрокинуть","predicate":[{"or":["action:shove","action:trip","action:reposition","inflicts:prone","forced-movement"]}],"selector":["fortitude","reflex"],"type":"circumstance","value":2}]}},{"id":"rQJBtQ9uKUzK9ktK","slug":"shortshanks-hobgoblin","name":"Коротконогий хобгоблин","cat":"heritages","type":"heritage","text":"У вас более длинный торс и более широкие плечи, чем у большинства хобгоблинов, поэтому по сравнению с ними ваши ноги кажутся короткими. Это дает вам сильный, мускулистый стержень и снижает центр тяжести — те особенности, которые помогают вам при верховой езде и карабканье, и вы с самого раннего возраста тренировались в седле. Вы получаете способность Езда верхом. Дополнительно, при Карабканье вы не становитесь Застигнуты врасплох.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Hobgoblin","slug":"hobgoblin","uuid":"Compendium.pf2e.ancestries.Item.piNLXUrm9iaGqD2i"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Ride","grantId":"Rq5wkA8DtsmbzoGV"}]}},{"id":"HpqQ5VQ0w4HqYgVC","slug":"jungle-catfolk","name":"Коточеловек джунглей","cat":"heritages","type":"heritage","text":"Вы происходите от следопытов джунглей и можете быстро передвигаться через кустарники и заросли. Вы игнорируете Сложную местность, вызванную зарослями, а Особо сложная местность от зарослей для вас считается просто сложной местностью.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Catfolk","slug":"catfolk","uuid":"Compendium.pf2e.ancestries.Item.972EkpJOPv9KkQIW"},"rules":[]}},{"id":"hOPOyyt7qZXYYCOU","slug":"nine-lives-catfolk","name":"Коточеловек с 9-ю жизнями","cat":"heritages","type":"heritage","text":"Ваша семья всегда оправлялась от катастроф, но не благодаря физической выносливости или специальным навыкам, а будто бы по чистой удаче. Другие котолюди шепчутся, что у вас 9 жизней. Пока вы При смерти, вы не добавляете своё значение {при смерти} к КС проверок восстановления (это означает, что ваш КС обычно 10). В дополнение, вы получаете общую способность Несгибаемый.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Catfolk","slug":"catfolk","uuid":"Compendium.pf2e.ancestries.Item.972EkpJOPv9KkQIW"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Diehard","grantId":"I0BhPWqYf1bbzEYg"},{"key":"ActiveEffectLike","mode":"subtract","path":"system.attributes.dying.recoveryDC","predicate":["self:condition:dying"],"value":"@actor.conditions.dying.badge.value"}]}},{"id":"idGDjqi1q3Ft8bAZ","slug":"nomadic-halfling","name":"Кочующий полурослик","cat":"heritages","type":"heritage","text":"Ваши предки в течение многих поколений путешествовали с места на место, никогда не соглашаясь с тем, чтобы осесть. Вы получаете два дополнительных языка на свой выбор, выбираемых из доступных вам обычных и необычных, а всякий раз, когда вы берёте способность Многоязычный, то получаете другой новый язык.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Halfling","slug":"halfling","uuid":"Compendium.pf2e.ancestries.Item.GgZAHbrjnzWOZy2v"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"system.build.languages.max","value":2},{"key":"ActiveEffectLike","mode":"override","path":"flags.system.multilingualTaken","priority":19,"value":0},{"key":"ActiveEffectLike","mode":"add","path":"system.build.languages.max","priority":21,"value":"@actor.flags.system.multilingualTaken"}]}},{"id":"35k2aujXYvqUCSS1","slug":"cavernstalker-kobold","name":"Крадущийся в пещерах кобольд","cat":"heritages","type":"heritage","text":"Вы вылупились в лабиринте с узкими туннелями, который также является домом для первичных энергий земли, что сделало вас более гибким и подвижным.\n\nКогда вы Карабкаетесь по каменным стенам, сталактитам и другим особенностям натурального камня, то двигаетесь с половиной Скорости при успехе и с полной Скоростью при критическом успехе (а если у вас есть способность навыка Быстро карабкаться, то вы двигаетесь с полной Скоростью при успехе). Это не действует, если вы используете Скорость карабканья.\n\nЕсли вы при совершении проверки Акробатики, чтобы Протиснуться, получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kobold","slug":"kobold","uuid":"Compendium.pf2e.ancestries.Item.7oQxL6wgsokD3QXG"},"rules":[]}},{"id":"KcozzlkFAqShDEzo","slug":"stronggut-shisk","name":"Крепкобрюхий шиск","cat":"heritages","type":"heritage","text":"У вас медленный метаболизм, что позволяет вам в течение нескольких дней обходиться без еды и медленнее поддаваться недугам. Вы можете прожить 1 неделю без еды, прежде чем начнёте голодать. Кроме того, периоды возникновения и длительности стадий для всех болезней и ядов, которые влияют на вас, увеличиваются на 50%. Если период возникновения или стадия мгновенные или длятся всего 1 раунд, это умение не имеет никакого эффекта.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Shisk","slug":"shisk","uuid":"Compendium.pf2e.ancestries.Item.x1YinOddgUxwOLqP"},"rules":[]}},{"id":"B89BCo6LtI3SJq54","slug":"sweetbreath-kholo","name":"Кхоло свежего дыхания","cat":"heritages","type":"heritage","text":"Вы — полосатый кхоло с бледной шерстью и странно приятным дыханием, которым вы можете восхитить свою жертву. Вы обучены Дипломатии (или другому навыку, если вы уже были обучены Дипломатии). Еще вы получаете бонус обстоятельства +1 к проверкам Произвести впечатление, если цель может унюхать ваше дыхание.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kholo","slug":"kholo","uuid":"Compendium.pf2e.ancestries.Item.vxbQ1Yw4qwgjTzqo"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.diplomacy.rank","value":1},{"key":"FlatModifier","predicate":["action:make-an-impression","sweet-breath"],"selector":"diplomacy","slug":"sweetbreath-kholo","type":"circumstance","value":1}]}},{"id":"xtRIYizCjLg9qe1Z","slug":"wildwood-halfling","name":"Лесной полурослик","cat":"heritages","type":"heritage","text":"Вы родом из глубин джунглей или леса, и вы научились использовать свой маленький размер, чтобы пробираться через заросли, лозы и другие препятствия. Вы игнорируете Сложную местность из-за растений и грибов, таких как кусты, лозы и заросли.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Halfling","slug":"halfling","uuid":"Compendium.pf2e.ancestries.Item.GgZAHbrjnzWOZy2v"},"rules":[]}},{"id":"nW1gi13E62Feto2w","slug":"woodland-elf","name":"Лесной эльф","cat":"heritages","type":"heritage","text":"Вы приспособлены к жизни в лесу или глубоких джунглях, и знаете как лазить по деревьям и использовать растительность в своих интересах. Когда вы Карабкаетесь на деревья, лианы и другую растительность, вы двигаетесь с половиной своей Скорости при успехе, и полной Скоростью при критическом успехе (и если у вас есть Быстро карабкаться), вы двигаетесь с полной Скоростью при успехе). Если вы используете Скорость карабканья, эти бонусы не применяются.\n\nВы всегда можете использовать действие Укрыться, когда находитесь в лесной местности, чтобы получить укрытие, даже если вы не рядом с преградой, за которой можете \"Укрыться\".","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Elf","slug":"elf","uuid":"Compendium.pf2e.ancestries.Item.PgKmsA2aKdbLU6O0"},"rules":[]}},{"id":"QZv2taQQAdeR8Vmg","slug":"flying-animal","name":"Летающее животное","cat":"heritages","type":"heritage","text":"Вы — животное, которое может долго или продолжительно летать, например орел, летучая мышь, пчела или белка-летяга.\n\nПроцесс пробуждения нарушил вашу способность летать так же свободно, как раньше. То, что раньше было автоматическим процессом, теперь требует от вас определенных умственных усилий, пока снова не станет автоматическим. Вы всё ещё можете замедлить свое падение, поэтому вы не получаете урона от падения, независимо от расстояния, на которое вы падаете. Большинство летающих пробуждённых животных выбирают способность родословной В полёт на 1-м уровне, чтобы восстановить ограниченную способность к полёту. У вас наземная Скорость 20 футов и одна атака животного на ваш выбор (обычно, клюв, коготь, коготь птицы, крыло или челюсти).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Awakened Animal","slug":"awakened-animal","uuid":"Compendium.pf2e.ancestries.Item.GFOgV3MzWkYwJoJW"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.ancestryfeatures.Item.Animal Attack","grantId":"oj532l4YXqzedBBn"}]}},{"id":"Csezts78L4FMaskB","slug":"lethoci","name":"Летоси","cat":"heritages","type":"heritage","text":"Вы из семьи кашриши, адаптировавшейся к прибрежным берегам или прудам и озерам в глубине земель. Вы получаете бонус обстоятельства +2 к проверкам Атлетики для Плавания. Если вы критически проваливаете проверку Атлетики для \"Плавания\", результат считается обычным провалом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kashrishi","slug":"kashrishi","uuid":"Compendium.pf2e.ancestries.Item.dw2K1AJR9mQ25nDP"},"rules":[{"key":"FlatModifier","predicate":["action:swim"],"selector":"athletics","type":"circumstance","value":2}]}},{"id":"evXJISqyhl3fHE9u","slug":"vine-leshy","name":"Леший из лоз","cat":"heritages","type":"heritage","text":"Цепкие лозы, вплетенные в ваше тело, дают вам непревзойденное мастерство в лазании. Чтобы Карабкаться вам не нужны свободные руки. Дополнительно, если при проверке Атлетики вы получаете успех, чтобы \"Карабкаться\", результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[]}},{"id":"3F5ffk7cmnrBhPcT","slug":"liminal-catfolk","name":"Лиминальный коточеловек","cat":"heritages","type":"heritage","text":"Вы унаследовали близость к далеким уголкам мира, где границы между измерениями истончаются. Вы можете по желанию сотворять Обнаружение магии как врождённые оккультные чары, усиленные до половины вашего уровня, округленной вверх.\n\nВы также получаете бонус обстоятельства +1 к проверкам Оккультизма, чтобы Вспомнить информацию о существах родом с планов, отличных от Вселенной.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Catfolk","slug":"catfolk","uuid":"Compendium.pf2e.ancestries.Item.972EkpJOPv9KkQIW"},"rules":[{"key":"FlatModifier","predicate":["action:recall-knowledge","target:not-from-universe"],"selector":"occultism","type":"circumstance","value":1}]}},{"id":"PwxbD5VSJ0Yroqvp","slug":"liminal-fetchling","name":"Лиминальный фечлинг","cat":"heritages","type":"heritage","text":"Вы происходите из рода фечлингов, имеющих более тесную связь с Эфирным и Теневым планами, и вы разделяете родство этих миров с незримым и тем, что находится между. Вы получаете бонус обстоятельства +1 к обнаружению существ с состоянием Необнаружен в радиусе 60 футов при использовании действия Поиск. Ваш КС чистой проверки для прицеливания в существ с состоянием Скрыт равен КС 3 (КС 3) вместо 5, а КС прицеливания в существ с состоянием {спрятан} равен КС 9 (КС 9) вместо 11.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fetchling","slug":"fetchling","uuid":"Compendium.pf2e.ancestries.Item.hIA3qiUsxvLZXrFP"},"rules":[{"key":"FlatModifier","predicate":["action:seek","target:condition:undetected","target:distance:60"],"selector":"perception","type":"circumstance","value":1}]}},{"id":"rFdVYKtHsZzRCsSd","slug":"stickytoe-tripkee","name":"Липкопалый трипки","cat":"heritages","type":"heritage","text":"Ваши руки и ноги выделяют пленку, которая помогает им прилипать к поверхностям. Вы получаете бонус обстоятельства +2 к вашим КС Стойкости и КС Рефлекса против попыток Разоружить, Толкнуть или Опрокинуть вас. При подъеме на деревья, лианы и другую растительность, если при совершении проверки Атлетики, чтобы Карабкаться, вы получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tripkee","slug":"tripkee","uuid":"Compendium.pf2e.ancestries.Item.hXM5jXezIki1cMI2"},"rules":[{"key":"FlatModifier","predicate":[{"or":["action:disarm","action:shove","action:trip","action:reposition"]}],"selector":["fortitude-dc","reflex-dc"],"type":"circumstance","value":2}]}},{"id":"dQqurQys37aJYb26","slug":"leaf-leshy","name":"Лиственный леший","cat":"heritages","type":"heritage","text":"Ваше тело сделано в основном из естественной листвы, и подобно листу, падающему с дерева, после падения вы приземляетесь с особой грацией. Вы не получаете урон от падения, независимо от расстояния.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[]}},{"id":"cwOUw7kofcAiY01I","slug":"snaring-anadi","name":"Ловчий анади","cat":"heritages","type":"heritage","text":"Вы вылупились с крючковатыми клыками, которые дают вам преимущество при охоте в своей истинной форме. Ваша атака клыками получает признаки захват и опрокидывание.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Anadi","slug":"anadi","uuid":"Compendium.pf2e.ancestries.Item.TQEqWqc7BYiadUdY"},"rules":[]}},{"id":"ievKYUc53q0mroGp","slug":"lotus-leshy","name":"Лотосовый леший","cat":"heritages","type":"heritage","text":"Вы легко держитесь на поверхности воды. Вы можете ходить по поверхности стоячей воды и других жидкостей не наносящих урон, двигаясь с половиной своей обычной Скорости. Еще вы можете попытаться пройти по поверхности текущей воды, всё ещё двигаясь с половиной Скорости, но для этого требуется преуспеть в проверке Акробатики, чтобы Балансировать, используя КС для проверки Плыть; при провале вы падаете в воду.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[]}},{"id":"OIW3UYrdaWLwUZCh","slug":"bakuwa-lizardfolk","name":"Людоящер бакува","cat":"heritages","type":"heritage","text":"Ваше тело покрыто костяными пластинами. Ваши пластины являются средним доспехом из группы латных, дающие бонус предмета +4 к КБ, ограничение Ловкости +1, штраф проверки −2, штраф Скорости −5 футов, значение Силы +3, и признаки обтекаемый и удобный. Вы никогда не сможете надеть другие доспехи или снять свои пластины. Вы можете гравировать руны доспехов на своих пластинах.","level":0,"traits":["Людоящер"],"tags":["lizardfolk"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Lizardfolk","slug":"lizardfolk","uuid":"Compendium.pf2e.ancestries.Item.HWEgF7Gmoq55VhTL"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.equipment-srd.Item.Bakuwa Lizardfolk Bony Plates","grantId":"mrgtvEbYTjGpOi7F"}]}},{"id":"sEnMG5zbnXdJvVPz","slug":"cloudleaper-lizardfolk","name":"Людоящер воздушный прыгун","cat":"heritages","type":"heritage","text":"Ваше тело легкое, с лоскутами кожи вдоль конечностей, которые улавливают проходящий под вами воздух. Пока вы можете действовать и имеете достаточно места, вы можете открывать перепонки, чтобы замедлить любое падение, ровно настолько, чтобы избежать получения урона (есть ли у вас для этого место, зависит от решения Мастера).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Lizardfolk","slug":"lizardfolk","uuid":"Compendium.pf2e.ancestries.Item.HWEgF7Gmoq55VhTL"},"rules":[]}},{"id":"TQFE10VFvh9wb8zb","slug":"woodstalker-lizardfolk","name":"Людоящер лесной лазутчик","cat":"heritages","type":"heritage","text":"Вы легко перемещаетесь через густой лес и джунгли, используя каждую ветку или куст. Когда находитесь в лесу или джунглях, вы всегда можете Укрыться, чтобы получить укрытие, даже если не находитесь рядом с преградой, необходимой, чтобы за ней \"Укрыться\". Вы получаете способность Лазутчик местности даже если не обучены Скрытности, и вы должны выбрать заросли.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Lizardfolk","slug":"lizardfolk","uuid":"Compendium.pf2e.ancestries.Item.HWEgF7Gmoq55VhTL"},"rules":[{"key":"GrantItem","preselectChoices":{"terrain-stalker":"underbrush"},"uuid":"Compendium.pf2e.feats-srd.Item.Terrain Stalker","grantId":"beyw5bdA5hkQbmaG"}]}},{"id":"e6ykfotynKPzR2PT","slug":"makari-lizardfolk","name":"Людоящер макари","cat":"heritages","type":"heritage","text":"У вас хоботоподобная морда и связь с сакральным. Обычай любых заклинаний или магических способностей, полученных благодаря наследию или способности родословной людоящера становится сакральным вместо обычного обычая (обычно природная).\n\nВы получаете на выбор Божественное копьё или Запрещающая защита, и можете сотворять его как врождённые сакральные чары. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой вверх. Когда вы сотворяете эти чары, оно теряют признак воздействие, так как вы сотворяете его исключительно с помощью рёва и раздувания хобота.","level":0,"traits":["Людоящер"],"tags":["lizardfolk"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Lizardfolk","slug":"lizardfolk","uuid":"Compendium.pf2e.ancestries.Item.HWEgF7Gmoq55VhTL"},"rules":[{"adjustName":false,"choices":{"filter":[{"or":["item:slug:forbidding-ward","item:slug:divine-lance"]}],"itemType":"spell","slugsAsValues":true},"flag":"cantrip","key":"ChoiceSet","prompt":"Выберите чары."}]}},{"id":"6rIIsZg3tOyIU3g3","slug":"frilled-lizardfolk","name":"Людоящер с воротником","cat":"heritages","type":"heritage","text":"Вы можете раздуть воротник на шее и сгибать спинные шипы, Деморализуя своих врагов. Когда вы это делаете, \"Деморализация\" теряет признак слуховой и получает признак визуальный, и вы не получаете штраф, когда пытаетесь \"Деморализовать\" существо, которое не понимает ваш язык. Еще вы получаете действие Угрожающее приближение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Lizardfolk","slug":"lizardfolk","uuid":"Compendium.pf2e.ancestries.Item.HWEgF7Gmoq55VhTL"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Threatening Approach"}]}},{"id":"OoUqJJB77VfWbWRM","slug":"cliffscale-lizardfolk","name":"Людоящер с утёсов","cat":"heritages","type":"heritage","text":"Ваши пальцы ног приспособлены, чтобы цепляться и лазать. Вы получаете способность навыка Боевой альпинист как бонусную, пока вы не носите обувь, вы можете использовать липкие подушечки на ногах, чтобы карабкаться, что освобождает ваши руки. Дополнительно, если при совершении проверки Атлетики, чтобы Карабкаться вы получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Lizardfolk","slug":"lizardfolk","uuid":"Compendium.pf2e.ancestries.Item.HWEgF7Gmoq55VhTL"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Combat Climber","grantId":"09PurtIanNUPfNRq"}]}},{"id":"wxQwFQGsg6yDiMmN","slug":"leungli","name":"Люнгли","cat":"heritages","type":"heritage","text":"У вас голова золотой рыбки или карпа, и чешуя, имеющая благоприятное сочетание белого, чёрного, оранжевого, красного и золотого цветов. Если вы обретаете крылья, они становятся похожими на развевающиеся волосы дракона. Вы получаете Скорость плавания 10 футов и признак земноводный. Как и все существа с признаком земноводный, вы можете дышать как водой, так и воздухом.","level":0,"traits":["Спрайт"],"tags":["sprite"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sprite","slug":"sprite","uuid":"Compendium.pf2e.ancestries.Item.TRqoeYfGAFjQbviF"},"rules":[]}},{"id":"23MEmXuyw75jiGKq","slug":"littlehorn-minotaur","name":"Малорогий минотавр","cat":"heritages","type":"heritage","text":"Хотя вы не менее сильны, ваше тело (и рога) меньше, чем у большинства других минотавров. Вместо Большого, ваш размер — Средний. Ваша безоружная атака рогами наносит 1к6 колющего урона вместо 1к8, но у неё есть признак быстрое.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Minotaur","slug":"minotaur","uuid":"Compendium.pf2e.ancestries.Item.3wQ49DoWFYQgVsq6"},"rules":[]}},{"id":"K124fCpU03SJvmeP","slug":"warmarch-hobgoblin","name":"Марширующий хобгоблин","cat":"heritages","type":"heritage","text":"Вы происходите из рода бродячих наемников, постоянно находящихся в походе и добывающих пищу на тракте. Если вы проваливаете, но не критически проваливаете проверку на Проживание в дикой местности, вы все равно можете обеспечить себя скудную пищу. Во время исследования, вы можете Спешить в два раза дольше, прежде чем вам придется остановиться.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Hobgoblin","slug":"hobgoblin","uuid":"Compendium.pf2e.ancestries.Item.piNLXUrm9iaGqD2i"},"rules":[]}},{"id":"TYvzNoL5ldmB5F76","slug":"melixie","name":"Меликси","cat":"heritages","type":"heritage","text":"У вас черты пчелы, бабочки или другого насекомого, любящего сладкое. Вы можете задавать вопросы и получать ответы от членистоногих (насекомых, пауков, скорпионов, крабов и подобных беспозвоночных животных), а также использовать Дипломатию, чтобы Произвести впечатление на них и Попросить у них что-либо. Большинство пчел, бабочек, мотыльков и жуков изначально относятся к вам Безразлично или Дружелюбно и дают вам время изложить свои доводы, однако другие членистоногие реагируют на вас, как и на любого другого искателя приключений.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sprite","slug":"sprite","uuid":"Compendium.pf2e.ancestries.Item.TRqoeYfGAFjQbviF"},"rules":[]}},{"id":"mPVEc7hFZQhv0gqJ","slug":"slabsoul-minotaur","name":"Минотавр гранитной души","cat":"heritages","type":"heritage","text":"Глубокая связь с камнем и стенами позволяет вам призывать массивные гранитные плиты, которые обрушиваются на ваших врагов. Вы получаете активность Поднять плиты.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Minotaur","slug":"minotaur","uuid":"Compendium.pf2e.ancestries.Item.3wQ49DoWFYQgVsq6"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Raise Slabs"}]}},{"id":"jP9ORt0jgY5VHyD3","slug":"glacier-cavern-minotaur","name":"Минотавр ледниковой пещеры","cat":"heritages","type":"heritage","text":"Ваш мех становится густым и тёплым, хорошо подходящим для замёрзших гор, в которых вы живёте. Вы получаете сопротивление холоду, равное половине вашего уровня (минимум 1). Вы считаете эффекты Холодной окружающей среды так, как если бы они были на одну ступень легче (невероятный холод становится экстремальным, экстремальный холод становится сильным и так далее).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Minotaur","slug":"minotaur","uuid":"Compendium.pf2e.ancestries.Item.3wQ49DoWFYQgVsq6"},"rules":[]}},{"id":"tYrb9KOv1etjE5wK","slug":"stalker-minotaur","name":"Минотавр ловчий","cat":"heritages","type":"heritage","text":"Несмотря на тяжелую фигуру, вы ходите на мохнатых копытах, которые заглушают ваши шаги, позволяя вам застать добычу врасплох. Вы обучены Скрытности (или другому навыку, если уже обучены Скрытности) и получаете способность навыка Лазутчик местности, но вы должны выбрать обломки, и вы можете Красться не больше 10 футов вместо 5 без необходимости делать проверку Скрытности.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Minotaur","slug":"minotaur","uuid":"Compendium.pf2e.ancestries.Item.3wQ49DoWFYQgVsq6"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.stealth.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Terrain Stalker","grantId":"beyw5bdA5hkQbmaG"}]}},{"id":"bHgGh3vtXL7fkhIy","slug":"ghost-bull-minotaur","name":"Минотавр призрачный бык","cat":"heritages","type":"heritage","text":"Ваш мех бледный, как смерть, возможно, из-за вашей или семейной связи с загробным миром, что позволяет вам сверхъестественным образом находить дорогу. Вы можете сотворять Знать путь по желанию как оккультное врождённое заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону. Кроме того, вы получаете бонус обстоятельства +1 против заклинаний и эффектов, вызывающих Замешательство.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Minotaur","slug":"minotaur","uuid":"Compendium.pf2e.ancestries.Item.3wQ49DoWFYQgVsq6"},"rules":[{"key":"FlatModifier","predicate":["inflicts:confused"],"selector":"saving-throw","type":"circumstance","value":1}]}},{"id":"daaXga11ov9YQVNq","slug":"polychromatic-anadi","name":"Многоцветный анади","cat":"heritages","type":"heritage","text":"Ваше тело покрыто исключительно цветастыми волосками, которые создают яркие, привлекающие внимание узоры, часть из которых могут проявляться даже в вашей человеческой форме. Вы становитесь обучены Выступлению (или другому навыку на свой выбор, если вы уже обучены Выступлению) и получаете способность навыка Впечатляющее выступление.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Anadi","slug":"anadi","uuid":"Compendium.pf2e.ancestries.Item.TQEqWqc7BYiadUdY"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.performance.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Impressive Performance","grantId":"xqAdXRd2gSQcqp5E"}]}},{"id":"VvEAFoxuddYNBmNc","slug":"grave-orc","name":"Могильный орк","cat":"heritages","type":"heritage","text":"Вы подверглись воздействию мощных некромантских энергий, которые должны были убить вас, но вы выжили. Ваша кожа холодная, липкая и серая. Вы получаете сопротивление урону пустотой, равное половине вашего уровня (минимум 1). Еще вы получаете бонус обстоятельства +1 к спасброскам против эффектов с признаками пустота или смерть.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Orc","slug":"orc","uuid":"Compendium.pf2e.ancestries.Item.lSGWXjcbOa6O5fTx"},"rules":[{"key":"FlatModifier","predicate":[{"or":["item:trait:death","item:trait:void"]}],"selector":["saving-throw"],"type":"circumstance","value":1}]}},{"id":"SPcTcZgUMy5J4kzs","slug":"mightyfall-kobold","name":"Могучий кобольд","cat":"heritages","type":"heritage","text":"Ваша близость к могущественным кайдзю сделала вас сильным и выносливым. Вы получаете 10 ОЗ от своей родословной вместо 6. Вместо обычных повышений и недостатков атрибутов вы можете выбрать повышение Силы, повышение Харизмы и недостаток Интеллекта.","level":0,"traits":["Кобольд"],"tags":["kobold"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kobold","slug":"kobold","uuid":"Compendium.pf2e.ancestries.Item.7oQxL6wgsokD3QXG"},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"system.attributes.ancestryhp","value":10}]}},{"id":"wB8xiQB4RDbzOOvR","slug":"monstrous-skeleton","name":"Монструозный скелет","cat":"heritages","type":"heritage","text":"Нечеловеческие скелеты часто создаются как из-за их смертоносных физических атак, так и из-за ужасающего внешнего вида. Чудовища и монструозные гуманоиды с самыми странными скелетами, как правило, занимают центральное место в коллекции некроманта, достаточно искусного, чтобы оживить себе такого. Вы получаете атаку когтями, рогом, хвостом или крылом, наносящую 1к6 урона. Коготь наносит рубящий урон, рог — колющий урон, а хвост или крыло — дробящий. Эта безоружная атака относится к группе \"драка\" и имеет признаки безоружное и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Skeleton","slug":"skeleton","uuid":"Compendium.pf2e.ancestries.Item.58rL5sg2y4arW1i5"},"rules":[{"adjustName":false,"choices":[{"label":"Коготь","value":"claw"},{"label":"Рог","value":"horn"},{"label":"Хвост","value":"tail"},{"label":"Крыло","value":"wing"}],"flag":"primaryStrike","key":"ChoiceSet","prompt":"Выберите безоружный удар.","rollOption":"ancestry:skeleton:monstrous"}]}},{"id":"NUUWs7jFwsIPmx3p","slug":"sage-jotunborn","name":"Мудрец ётунорожденный","cat":"heritages","type":"heritage","text":"Вас назначили хранить устные и вытканные истории своей семьи, клана, или даже поселения. Вы обучены Обществу и получаете общую способность Дополнительные знания со Знаниями на свой выбор.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Боевой клич!","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Jotunborn","slug":"jotunborn","uuid":"Compendium.pf2e.ancestries.Item.gayvFCiQcGNCA7aM"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.society.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Additional Lore","grantId":"BocFD2KV0qgUC76x"}]}},{"id":"udMXXjFirjARYr4p","slug":"ant-kholo","name":"Муравьиный кхоло","cat":"heritages","type":"heritage","text":"Вы — большеухий кхоло с острыми чертами, ростом около {3 футов}. Многие скептически относятся к тому, что вы на самом деле кхоло. Вы Маленького размера вместо Среднего. Вы обучены Обману (или другому навыку, если вы уже были обучены Обману). Вы получаете бонус обстоятельства +1 к проверкам Обмана, чтобы Лгать о своей невиновности, к КС Обмана против проверок Понять намерение для раскрытия такой лжи, и к броскам инициативы, когда используете для них Обман.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kholo","slug":"kholo","uuid":"Compendium.pf2e.ancestries.Item.vxbQ1Yw4qwgjTzqo"},"rules":[{"key":"FlatModifier","predicate":["deception"],"selector":"initiative","type":"circumstance","value":1},{"key":"FlatModifier","predicate":["action:lie"],"selector":"deception","type":"circumstance","value":1},{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.deception.rank","value":1}]}},{"id":"CCwTBSNTw0caN1jd","slug":"mutated-fleshwarp","name":"Мутировавший деформированный","cat":"heritages","type":"heritage","text":"Трансформированные неконтролируемой магией, вы происходите из Пустошей Маны или другого региона, также опустошённом неконтролируемой магией. Из-за ваших прочных или дублирующих органов, КС ваших чистых проверок при восстановлении от продолжительного урона кровотечением равняется КС 10 (КС 10) (вместо КС 15), и он снижается до КС 5 (КС 5) вместо КС 10 при получении особенно эффективной помощи восстановления от продолжительного урона.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fleshwarp","slug":"fleshwarp","uuid":"Compendium.pf2e.ancestries.Item.FXlXmNBFiiz9oasi"},"rules":[]}},{"id":"MtH5bq0MhaMQbJEL","slug":"murkeyed-azarketi","name":"Мутноглазый азаркет","cat":"heritages","type":"heritage","text":"Вы живете в мутной воде и привыкли к жизни в условиях плохой видимости. Когда вы целитесь в противника, который имеет состояние Скрыт или Спрятан для вас, снизьте КС чистой проверки до КС 3 (КС 3) для {скрытой} цели или до КС 9 (КС 9) для {спрятанной}.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Azarketi","slug":"azarketi","uuid":"Compendium.pf2e.ancestries.Item.yFoojz6q3ZjvceFw"},"rules":[]}},{"id":"Svk2CHwvurK1QQhD","slug":"naari","name":"Наари","cat":"heritages","type":"heritage","text":"Вы происходите от огненных элементалей или несете на себе метку Внутренних Сфер, и ваши черты демонстрируют это влияние, которое оказывает на вас элементальный огонь. В дополнение к признакам своей родословной, вы получаете признак наари. Вы получаете сопротивление огню, равное половине вашего уровня (минимум 1), и считаете эффекты Жаркой окружающей среды так, как если бы они были на одну ступень лучше (невероятная жара становится экстремальной, экстремальная становится сильной и т.д.) Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей наари и способностей своей родословной.\n\nНаари","level":0,"traits":["наари"],"tags":["naari"],"rarity":"необычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[]}},{"id":"7kHg780SAsu2FNfP","slug":"stuffed-poppet","name":"Набивная кукла","cat":"heritages","type":"heritage","text":"Внутри вас почти ничего нет, кроме хлопка, опилок или сухих листьев. Вы не получаете урона от падения, независимо от дистанции падения.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Poppet","slug":"poppet","uuid":"Compendium.pf2e.ancestries.Item.6F2fSFC1Eo1JdpY4"},"rules":[]}},{"id":"Lp7ywxabmm88Gei6","slug":"observant-halfling","name":"Наблюдательный полурослик","cat":"heritages","type":"heritage","text":"Ваши тонко отточенные чувства быстро подсказывают вам об опасности или обмане. Вы получаете бонус обстоятельства +1 к вашему КС Восприятия, однако не к своим проверкам Восприятия.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Halfling","slug":"halfling","uuid":"Compendium.pf2e.ancestries.Item.GgZAHbrjnzWOZy2v"},"rules":[{"key":"FlatModifier","selector":"perception-dc","type":"circumstance","value":1}]}},{"id":"Cmj0pI0GPHl7kBUB","slug":"shimmertongue-nagaji","name":"Нагаджи мерцающего языка","cat":"heritages","type":"heritage","text":"Вы родились с обострённым чувством магии, способным ощущать её уникальные эффекты в воздухе. Вы получаете чутьё магии как смутное чувство с радиусом 30 футов. Как и все смутные чувства, оно примерно так же точно, как обоняние обычного человека, то есть вы можете почувствовать только присутствие магии; однако каждый обычай магии имеет для вас уникальное ощущение, что позволяет вам определить, какой обычай магии присутствует.","level":0,"traits":["Нагаджи"],"tags":["nagaji"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Nagaji","slug":"nagaji","uuid":"Compendium.pf2e.ancestries.Item.J7T7bDLaQGoY1sMF"},"rules":[{"acuity":"vague","key":"Sense","range":30,"selector":"magicsense"}]}},{"id":"tf3edMCyS15GhFPx","slug":"hooded-nagaji","name":"Нагаджи с капюшоном","cat":"heritages","type":"heritage","text":"У вас голова плюющейся кобры, покрытая капюшоном, и, подобно таким кобрам, можете выпускать из пасти струи яда. Вы получаете безоружную дистанционную атаку ядовитым плевком с шагом дистанции 10 футов и наносящую 1к4 урона ядом. При критическом попадании цель получает продолжительный урон ядом, равный количеству костей урона оружия. У вашего плевка нет группы оружия или эффекта критической специализации.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Nagaji","slug":"nagaji","uuid":"Compendium.pf2e.ancestries.Item.J7T7bDLaQGoY1sMF"},"rules":[]}},{"id":"0Anj61DzUimJ1uMS","slug":"elytron-surki","name":"Надкрыльный суркай","cat":"heritages","type":"heritage","text":"Верхний слой вашего панциря особенно подвижен, и вы можете развернуть его, чтобы грациозно подхватывать воздух при падении. Вы не получаете урона от падения, независимо от дистанции.\n\nЭволюция: Ваши плечевые узлы развились в пару шипов, которые вы можете зарядить энергией, чтобы проецировать пару светящихся крыльев. Один раз в день вы можете сотворять на себя Полёт как врождённое заклинание. Пока ваши крылья заряжены энергией, вы испускаете яркий свет в радиусе 20 футов и тусклый свет на следующие 20 футов.\n\nЭволюция: Ваши плечевые узлы превратились в веер тонких мембран, которые резонируют, когда через них пропускается магия. Вы получаете действие Пронзительная песнь.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Surki","slug":"surki","uuid":"Compendium.pf2e.ancestries.Item.ALOmLePjbc37ca3Y"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"flags.system.surki.evolutions","value":{"label":"Светящиеся крылья","predicate":[{"not":"evolution:glowing-wings"}],"value":"glowing-wings"},"resolvedValues":{}},{"key":"ActiveEffectLike","mode":"add","path":"flags.system.surki.evolutions","value":{"label":"Резонирующие мембраны","predicate":[{"not":"evolution:resonating-membranes"}],"value":"resonating-membranes"},"resolvedValues":{}},{"allowDuplicate":false,"key":"GrantItem","predicate":["evolution:resonating-membranes"],"reevaluateOnUpdate":true,"uuid":"Compendium.pf2e.actionspf2e.Item.Stridulating Song"}]}},{"id":"rKV11HWREwjjMIum","slug":"skyborn-tengu","name":"Небесный тэнгу","cat":"heritages","type":"heritage","text":"Ваши кости могут быть особенно лёгкими, вы можете быть редким тэнгу с крыльями, или ваша связь с духами ветра и неба может быть сильнее, чем у большинства, замедляя ваше падение по воздуху. Вы не получаете никакого урона от падения, независимо от расстояния, которое вы падаете.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tengu","slug":"tengu","uuid":"Compendium.pf2e.ancestries.Item.18xDKYPDBLEv2myX"},"rules":[]}},{"id":"xaTTN5anLEBzWCzv","slug":"windweb-tripkee","name":"Невесомый трипки","cat":"heritages","type":"heritage","text":"Прочные перепонки на руках и ногах могут замедлить любое падение. Пока у вас есть одна свободная рука, вы не получаете урон от падения, независимо от расстояния, на которое падаете.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tripkee","slug":"tripkee","uuid":"Compendium.pf2e.ancestries.Item.hXM5jXezIki1cMI2"},"rules":[]}},{"id":"uAo0wK1JL9kePcZb","slug":"even-tempered-tanuki","name":"Невозмутимый тануки","cat":"heritages","type":"heritage","text":"Вы обладаете спокойствием, несвойственным другим тануки, всегда выходящим из себя. Вы получаете бонус обстоятельства +1 к спасброскам против эффектов эмоций. При успешном спасброске против эффекта эмоций, результат считается критическим успехом, а при проваленном спасброске против эффекта эмоций, результат считается критическим провалом.","level":0,"traits":["Тануки"],"tags":["tanuki"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tanuki","slug":"tanuki","uuid":"Compendium.pf2e.ancestries.Item.pILFsoGsUQkVF5dZ"},"rules":[{"key":"FlatModifier","predicate":["item:trait:emotion"],"selector":"saving-throw","type":"circumstance","value":1}]}},{"id":"VYfpTUuXJM3iBOz0","slug":"unseen-lizardfolk","name":"Незаметный людоящер","cat":"heritages","type":"heritage","text":"Вы можете изменять цвет своей кожи, чтобы слиться с окружающим миром, делая незначительные локальные изменения одиночным действием (1 действие) и значительные изменения по всему телу в течение часа.\n\nКогда вы находитесь в местности, где ваша окраска примерно похожа на окружающую среду (например, цвет лесной зелени в лесу), вы можете использовать небольшое применение этого умения за одно действие (1 действие), чтобы сделать небольшие локальные изменения, которые помогут вам слиться с окружающей средой, давая вам бонус обстоятельства +2 к проверкам Скрытности, пока цвета или узоры вашего окружения не изменятся.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Lizardfolk","slug":"lizardfolk","uuid":"Compendium.pf2e.ancestries.Item.HWEgF7Gmoq55VhTL"},"rules":[{"key":"FlatModifier","predicate":["coloration-matches"],"selector":"stealth","type":"circumstance","value":2}]}},{"id":"5gqcEsJ4gkE6W5jj","slug":"steadfast-tanuki","name":"Непоколебимый тануки","cat":"heritages","type":"heritage","text":"Ваша гордость за свою истинную форму тануки не знает границ. Вы получаете на свой выбор способность Повседневная форма или способность Форма чайника в качестве бонусной способсности родословной.","level":0,"traits":["Тануки"],"tags":["tanuki"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tanuki","slug":"tanuki","uuid":"Compendium.pf2e.ancestries.Item.pILFsoGsUQkVF5dZ"},"rules":[{"key":"GrantItem","uuid":"{item|flags.system.rulesSelections.steadfastTanuki}"},{"adjustName":false,"choices":[{"value":"Compendium.pf2e.feats-srd.Item.Everyday Form"},{"value":"Compendium.pf2e.feats-srd.Item.Teakettle Form"}],"flag":"steadfastTanuki","key":"ChoiceSet","prompt":"Выберите способность."}]}},{"id":"ULj56ZoW7dWdnBvu","slug":"unbreakable-goblin","name":"Несокрушимый гоблин","cat":"heritages","type":"heritage","text":"Вы можете легко оправиться от травм благодаря исключительно толстому черепу, хрящевым костям или другим смешанным особенностям. Вы получаете 10 Очков Здоровья от своей родословной, вместо стандартных 6. Когда вы падаете, снизьте получаемый урон от падения, как если бы вы падали только половину расстояния.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goblin","slug":"goblin","uuid":"Compendium.pf2e.ancestries.Item.sQfjTMDaZbT9DThq"},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"system.attributes.ancestryhp","value":10}]}},{"id":"ywNXVLZtwrAStyh1","slug":"elusive-vishkanya","name":"Неуловимый вишканья","cat":"heritages","type":"heritage","text":"Ваше гибкое тело кажется некоторым неестественно подвижным, хотя они редко могут определить, что именно в вас кажется странным. Вы можете с легкостью ускользать от врагов. Вы получаете бонус обстоятельства +1 к проверкам Вырваться. Кроме того, когда Протискиваетесь, вы двигаетесь в 2 раза быстрее.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Vishkanya","slug":"vishkanya","uuid":"Compendium.pf2e.ancestries.Item.u1VJEXsVlmh3Fyx0"},"rules":[{"key":"FlatModifier","predicate":["action:escape"],"selector":["athletics","acrobatics"],"type":"circumstance","value":1}]}},{"id":"1oLMOmLpurfWTTff","slug":"nephilim","name":"Нефилим","cat":"heritages","type":"heritage","text":"На вашу природу повлияли небожители, исчадия или наблюдатели. Это проявляется в сочетании черт, не соответствующих вашей родословной — такими как золотые глаза, нимб, рога или хвост. Вы получаете признак нефилим в дополнение к признакам вашей родословной. Вы также получаете Сумеречное зрение или Ночное зрение, если ваша родословная уже имеет сумеречное зрение. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей нефилима и способностей родословной своего другого родителя.\n\nНефилим","level":0,"traits":["нефилим"],"tags":["nephilim"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"key":"Sense","selector":"low-light-vision"},{"key":"Sense","predicate":["self:low-light-vision:from-ancestry"],"selector":"darkvision"}]}},{"id":"h2VKMYAlUIFAAXVG","slug":"nyktera","name":"Никтера","cat":"heritages","type":"heritage","text":"У вас есть черты летучей мыши, близость с летучими мышами и непревзойденный слух. Пока вы можете нормально слышать, то можете использовать действие Поиск, чтобы ощущать Необнаруженных существ в 60-футовом конусе, вместо 30-футового. Также вы получаете бонус обстоятельства +2 к поиску {необнаруженных} существ действием \"Поиск\" в радиусе 30 футов, которых можете слышать.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sprite","slug":"sprite","uuid":"Compendium.pf2e.ancestries.Item.TRqoeYfGAFjQbviF"},"rules":[{"key":"FlatModifier","label":"To seek undetected you can hear within 30 feet (Nyktera)","predicate":["action:seek","target:audible","target:condition:undetected","target:within-30"],"selector":"perception","type":"circumstance","value":2}]}},{"id":"RZHr0olieS6YdYE9","slug":"fodder-skeleton","name":"Никчёмный скелет","cat":"heritages","type":"heritage","text":"Люди и те, кто физически наиболее близок к ним, являются излюбленным материалом некромантов. Они легко доступны, а их физиология изучена наиболее полно, поэтому такие скелеты можно легко производить массово. Несмотря на свое название, из никчемных скелетов получаются довольно мобильные пехотинцы благодаря тому, как эффективно они переносят некромантическую энергию внутри своего тела. Ваша базовая Скорость составляет 30 футов вместо 25 футов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Skeleton","slug":"skeleton","uuid":"Compendium.pf2e.ancestries.Item.58rL5sg2y4arW1i5"},"rules":[]}},{"id":"9mS8EGLlGUOzSAzP","slug":"nightglider-strix","name":"Ночной стрикс","cat":"heritages","type":"heritage","text":"Вы посвященная ночная птица, наблюдающая и охотящаяся в самых темных условиях. Вы получаете ночное зрение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Strix","slug":"strix","uuid":"Compendium.pf2e.ancestries.Item.GXcC6oVa5quzgNHD"},"rules":[{"key":"Sense","selector":"darkvision"}]}},{"id":"WEzgrxBRFBGdj8Hx","slug":"wavediver-tengu","name":"Ныряющий тэнгу","cat":"heritages","type":"heritage","text":"Вы один из редких тэнгу, которые могут рассекать воду так же легко как птицы — воздух, и вы часто прячетесь в реках и океанах, где вас мало кто ожидает. Вы получаете Скорость плавания 15 футов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tengu","slug":"tengu","uuid":"Compendium.pf2e.ancestries.Item.18xDKYPDBLEv2myX"},"rules":[]}},{"id":"aPqNdvtKHv4amLcO","slug":"respite-of-cloudless-paths","name":"Облегчение безоблачных путей","cat":"heritages","type":"heritage","text":"Вы дали обет защищать заблудших и потерянных. Эффекты окружающей жары и холода становятся для вас на одну степень менее экстремальными (невероятная жара становится экстремальной, экстремальный холод становится сильным и т.д.), и вы получаете бонус обстоятельства +1 к спасброскам против особенностей и опасностей окружающей среды, таких как наводнения, лавины и песчаные бури.\n\nДополнительный эдикт: Помогать потерявшимся или недееспособным путешественникам","level":0,"traits":["Якша"],"tags":["yaksha"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaksha","slug":"yaksha","uuid":"Compendium.pf2e.ancestries.Item.k3zyr6du4gV0Ftuh"},"rules":[{"key":"FlatModifier","predicate":["environmental-hazard"],"selector":"saving-throw","type":"circumstance","value":1}]}},{"id":"WczVM4KQq7xybsPZ","slug":"respite-of-loam-and-leaf","name":"Облегчение суглинка и листвы","cat":"heritages","type":"heritage","text":"Вы поклялись сохранить саму основу святилища; великую землю и всё, что на ней растёт. Ваш обет даёт вам духовную силу земли, вы получаете одни чары из списка природных заклинаний. Вы можете по желанию сотворять эти чары как врождённое природное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону. Ваши корни в этом мире дают вам признак растение.\n\nДополнительный эдикт: Излечивать или удалять встреченную вами порчу и загрязнение с растений и почвы","level":0,"traits":["растение","Якша"],"tags":["plant","yaksha"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaksha","slug":"yaksha","uuid":"Compendium.pf2e.ancestries.Item.k3zyr6du4gV0Ftuh"},"rules":[]}},{"id":"q7b4yu3Nty0jZLOi","slug":"respite-of-a-thousand-roofs","name":"Облегчение тысячи крыш","cat":"heritages","type":"heritage","text":"Вы дали обет приютить и накормить бедняков. Обет даёт вам мастерство в плотницком деле, приготовлении пищи и ткани; вы становитесь обучены Ремеслу и Кулинарным знаниям , а также получаете способность навыка Импровизированный инструмент.\n\nДополнительный эдикт: Помогать обедневшим в меру своих сил, ремонтируя их жилища и одежду, или кормя их","level":0,"traits":["Якша"],"tags":["yaksha"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaksha","slug":"yaksha","uuid":"Compendium.pf2e.ancestries.Item.k3zyr6du4gV0Ftuh"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.crafting.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Improvise Tool","grantId":"3HChkcD1IRqv4DbA"}]}},{"id":"GpnHIonrLN8TFZci","slug":"rite-of-invocation","name":"Обряд заклинания","cat":"heritages","type":"heritage","text":"Вы усилили свой экзоскелет магией. Вы получаете одни чары из списка арканных или оккультных заклинаний. Вы можете по желанию сотворять это заклинание как врождённое. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Conrasu","slug":"conrasu","uuid":"Compendium.pf2e.ancestries.Item.tZn4qIHCUA6wCdnI"},"rules":[]}},{"id":"faLb2rczsrxAuOTt","slug":"rite-of-knowing","name":"Обряд познания","cat":"heritages","type":"heritage","text":"Вы улучшили свой экзоскелет связью с Осью, что позволило вам получить доступ к бесконечным знаниям этого плана. Вы получаете действие Воззвать к Оси.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Conrasu","slug":"conrasu","uuid":"Compendium.pf2e.ancestries.Item.tZn4qIHCUA6wCdnI"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Call to Axis"}]}},{"id":"yVtcyAbLmWCIHHZi","slug":"rite-of-passage","name":"Обряд прохождения","cat":"heritages","type":"heritage","text":"Ваш экзоскелет остаётся связанным с создавшими его растениями. Вы можете игнорировать Сложную местность и Неровную землю вызванные зарослями. Дополнительно, когда вы используете навык Акробатики, чтобы Балансировать на Узких поверхностях или неровной земле в лесах, то вы не Застигнуты врасплох. Когда при броске одной из таких проверок Акробатики вы получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Conrasu","slug":"conrasu","uuid":"Compendium.pf2e.ancestries.Item.tZn4qIHCUA6wCdnI"},"rules":[]}},{"id":"EoWwvDdoMqN5x0c9","slug":"rite-of-light","name":"Обряд света","cat":"heritages","type":"heritage","text":"Ваш экзоскелет имеет маленькие побеги, которые могут делиться жизнью. При использовании своего Исцеления солнечным светом, вместо своих Очков Здоровья вы можете восстановить ОЗ соседнего союзника. Этот союзник становится временно иммунен ко всем применениям \"Исцеления солнечным светом\" на 1 день.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Conrasu","slug":"conrasu","uuid":"Compendium.pf2e.ancestries.Item.tZn4qIHCUA6wCdnI"},"rules":[]}},{"id":"q2omqJ9t0skGTYki","slug":"rite-of-reinforcement","name":"Обряд укрепления","cat":"heritages","type":"heritage","text":"Ваш тканый экзоскелет не уступает самым прочным доспехам, из тех, которые только можно найти. Ваш экзоскелет является средним доспехом относящимся к группе \"латных\", дающий бонус предмета +4 к КБ, ограничение Ловкости +1, штраф проверки −2, штраф скорости −5 футов, значение Силы +3 и признак удобный. Вы никогда не можете надеть другой доспех или снять свой экзоскелет. Вы можете гравировать руны доспехов на свой экзоскелет как обычно.\n\nЭкзоскелет обряда укрепления","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Conrasu","slug":"conrasu","uuid":"Compendium.pf2e.ancestries.Item.tZn4qIHCUA6wCdnI"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.equipment-srd.Item.Rite of Reinforcement Exoskeleton","grantId":"0KHgAaDi3tmu32Hq"}]}},{"id":"32oX6hHUY6K8N70Q","slug":"charhide-goblin","name":"Обугленный гоблин","cat":"heritages","type":"heritage","text":"Ваши предки всегда имели связь с огнем и более толстую кожу, которая позволяет вам противостоять горению. Вы получаете сопротивление огню, равное половине вашего уровня (минимум 1). Так же, вы можете легче избавить от горения. Ваша чистая проверка, чтобы избавиться от продолжительного урона огнем — КС 10 (КС 10), вместо КС 15, и снижается до КС 5 (КС 5) если другое существо использует особенно подходящее действие для помощи.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goblin","slug":"goblin","uuid":"Compendium.pf2e.ancestries.Item.sQfjTMDaZbT9DThq"},"rules":[]}},{"id":"d7NC4C19AgkspQQg","slug":"battle-trained-human-bb","name":"Обученный битве человек (СН)","cat":"heritages","type":"heritage","text":"Ваша семья из поколения в поколение обучалась сражаться, что дает вам преимущества против ваших врагов. Вы получаете бонус +1 к броскам инициативы. Кроме того, вы получаете способность Несгибаемый.\n\nЗаметка: Это наследие относится к Стартовому набору и имеет нестандартные особенности наследия.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Human","slug":"human","uuid":"Compendium.pf2e.ancestries.Item.IiG7DgeLWYrSNXuX"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Diehard","grantId":"I0BhPWqYf1bbzEYg"},{"key":"FlatModifier","selector":["initiative"],"type":"circumstance","value":1}]}},{"id":"ITgkqfnAOJCbcIys","slug":"oread","name":"Ореад","cat":"heritages","type":"heritage","text":"На вашу линию крови повлиял предок земляной элементаль, и ваши черты подчеркивают эту стихийную планарную связь. У вас может быть кристаллический или металлический блеск на коже или волосах, грубая и каменистая кожа или блестящие глаза как из драгоценных камней. В дополнение к признакам своей родословной, вы получаете признак ореад. Вы также получаете Сумеречное зрение или Ночное зрение, если ваша родословная уже имеет сумеречное зрение. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей ореада и способностей своей родословной.\n\nОреад","level":0,"traits":["ореад"],"tags":["oread"],"rarity":"необычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"key":"Sense","selector":"low-light-vision"},{"key":"Sense","predicate":["self:low-light-vision:from-ancestry"],"selector":"darkvision"}]}},{"id":"8Gsa8KFsHizEwSHU","slug":"badlands-orc","name":"Орк пустошей","cat":"heritages","type":"heritage","text":"Вы родом из выжженных солнцем бесплодных земель, где вам помогли преуспеть длинные ноги и способность противостоять стихиям. Вы можете Спешить в два раза дольше, пока исследуете, прежде чем вам будет нужно остановиться, и вы считаете эффекты Жаркой окружающей среды так, как если бы они были на одну ступень лучше (невероятная жара становится экстремальной, экстремальная жара становится суровой и так далее).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Orc","slug":"orc","uuid":"Compendium.pf2e.ancestries.Item.lSGWXjcbOa6O5fTx"},"rules":[]}},{"id":"MTTU2t7x6TjvUDnE","slug":"hold-scarred-orc","name":"Орк со шрамами холда","cat":"heritages","type":"heritage","text":"Вы являетесь частью сообщества орков, которое практикует ритуальное шрамирование или татуирование. Отметины на вашей коже показывают вашу исключительную выносливость и жизненную силу. Вы получаете 12 ОЗ от своей родословной вместо 10. Также вы получаете способность Несгибаемый.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Orc","slug":"orc","uuid":"Compendium.pf2e.ancestries.Item.lSGWXjcbOa6O5fTx"},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"system.attributes.ancestryhp","value":12},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Diehard","grantId":"I0BhPWqYf1bbzEYg"}]}},{"id":"dwKCwwtWetvPmJks","slug":"rainfall-orc","name":"Орк тропического леса","cat":"heritages","type":"heritage","text":"Вы родились в тропическом лесу, где только сплетение деревьев обеспечивает защиту от проливных ливней и внезапных наводнений. Вы научились ловко передвигаться по джунглям и противостоять различным болезням, распространенным во влажной окружающей среде. Вы получаете бонус обстоятельства +2 к проверкам Атлетики, чтобы Карабкаться или Плыть и бонус обстоятельства +1 к спасброскам против болезней.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Orc","slug":"orc","uuid":"Compendium.pf2e.ancestries.Item.lSGWXjcbOa6O5fTx"},"rules":[{"key":"FlatModifier","predicate":[{"or":["action:climb","action:swim"]}],"selector":"athletics","type":"circumstance","value":2},{"key":"FlatModifier","predicate":["disease"],"selector":"saving-throw","type":"circumstance","value":1}]}},{"id":"a6F2WjYU8D0suT8T","slug":"razortooth-goblin","name":"Острозубый гоблин","cat":"heritages","type":"heritage","text":"В вашем роду, зубы — грозное оружие. У вас есть безоружная атака челюстями, наносящая 1к6 колющего урона. Ваши челюсти относятся к группе \"драка\" и имеют признаки безоружное и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goblin","slug":"goblin","uuid":"Compendium.pf2e.ancestries.Item.sQfjTMDaZbT9DThq"},"rules":[]}},{"id":"NWsZ0cIeghyzk9bU","slug":"sharp-eared-catfolk","name":"Остроухий коточеловек","cat":"heritages","type":"heritage","text":"Вы родились с большими, выразительными ушами, которые двигаются в соответствии с вашим настроением и оживляются при любом неожиданном звуке. Вы получаете бонус обстоятельства +2 к поиску Необнаруженных существ с помощью действия Поиск, которых вы можете слышать в радиусе 30 футов. Пока вы осведомлены о существе благодаря звуку, раз в раунд ваши уши могут помочь вам Указать своим союзникам на это существо свободным действием .","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Catfolk","slug":"catfolk","uuid":"Compendium.pf2e.ancestries.Item.972EkpJOPv9KkQIW"},"rules":[{"key":"FlatModifier","predicate":["action:seek",{"lte":["target:distance",30]}],"selector":"perception","type":"circumstance","value":2}]}},{"id":"BhbwjTFw2V67XF35","slug":"keen-venom-vishkanya","name":"Остроядый вишканья","cat":"heritages","type":"heritage","text":"Вы практикуетесь в использовании своего яда в бою, что позволяет вам применять его в мгновение ока. Ваше действие Отравить не провоцирует реакции, которые обычно срабатывают на действие воздействия. Кроме того, вы получаете действие Отравляющий выхват.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Vishkanya","slug":"vishkanya","uuid":"Compendium.pf2e.ancestries.Item.u1VJEXsVlmh3Fyx0"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Venom Draw"}]}},{"id":"S1062No0sYH35AhN","slug":"tactile-azarketi","name":"Осязающий азаркет","cat":"heritages","type":"heritage","text":"Ваша кожа может улавливать малейшие изменения океанских течений. Вы получаете неточное чувство Волночувствительность с расстоянием 30 футов, что позволяет вам ощущать движение в воде вокруг вас. Вы также получаете бонус обстоятельства +1 к проверкам Выживания для Определить направление в водной среде.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Azarketi","slug":"azarketi","uuid":"Compendium.pf2e.ancestries.Item.yFoojz6q3ZjvceFw"},"rules":[{"key":"FlatModifier","predicate":["action:sense-direction","terrain:aquatic"],"selector":"survival","type":"circumstance","value":1},{"acuity":"imprecise","key":"Sense","range":30,"selector":"wavesense"}]}},{"id":"OtqOC3ElpF444qMe","slug":"discarded-fleshwarp","name":"Отбракованный деформированный","cat":"heritages","type":"heritage","text":"Биоманты и мутагенисты, исказившие вашу форму, заклеймили вас как \"отбраковать при обнаружении\" — эвфемизм для уничтожения на месте. Аномалия среди аномалий — ваше тело упорно отвергает усилия мастеров плоти, пытающихся вылепить из вас свои грандиозные видения, а ваши иммунные реакции ослабляют худшие эффекты нежелательных попыток формирования плоти. Если при спасброске против эффекта `трансмутации` вы получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fleshwarp","slug":"fleshwarp","uuid":"Compendium.pf2e.ancestries.Item.FXlXmNBFiiz9oasi"},"rules":[]}},{"id":"hqh4zKHYBtDE26g8","slug":"courageous-tanuki","name":"Отважный тануки","cat":"heritages","type":"heritage","text":"В вашем сердце бьётся отвага тех, кто был до вас, что придаёт вам храбрость, которую может продемонстрировать только тануки. Когда вы получаете состояние Бегства, вы также получаете бонус обстоятельства +10 футов к своей Скорости, пока вы {бежите}. Когда у вас есть состояние {бегства}, вы можете действовать нормально в течение одного действия, но должны потратить оставшуюся часть своих действий на бегство. Вы также получаете действие Тактическое отступление.","level":0,"traits":["Тануки"],"tags":["tanuki"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tanuki","slug":"tanuki","uuid":"Compendium.pf2e.ancestries.Item.pILFsoGsUQkVF5dZ"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Tactical Retreat"},{"key":"FlatModifier","predicate":["self:condition:fleeing"],"selector":"speed","type":"circumstance","value":10}]}},{"id":"YoDvQ5fvpbgcoG3V","slug":"deny-the-traitors-rebirth","name":"Отвергание возрождения предателей","cat":"heritages","type":"heritage","text":"Вы дали обет избавлять других от ракшас и асур, которых легенды якш осуждают как порочных сородичей. Чтобы противостоять их коварным планам, ваш обет даёт вам ночное зрение и бонус обстоятельства +1 к проверкам Восприятия, чтобы Искать или Понимать намерения ракшас и асур.\n\nДополнительный эдикт: Противостоять ракшасам и асурам, которых вы встретите (если у вас есть приемлемые шансы на успех); в том маловероятном случае, когда вы встречаете доброжелательного ракшаса или асуру, вам не нужно противостоять ему","level":0,"traits":["Якша"],"tags":["yaksha"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaksha","slug":"yaksha","uuid":"Compendium.pf2e.ancestries.Item.k3zyr6du4gV0Ftuh"},"rules":[{"key":"Sense","selector":"darkvision"},{"key":"FlatModifier","predicate":[{"or":["target:trait:asura","target:trait:rakshasa"]},{"or":["action:seek","action:sense-motive"]}],"selector":"perception","value":1}]}},{"id":"qeFCDRSgFRR2ElWK","slug":"deny-lady-nanbyos-charity","name":"Отвергание милосердия Госпожи Наньбо","cat":"heritages","type":"heritage","text":"Вы дали обет освобождать других от природных бедствий. Ваша клятва даёт вам силу нести на 1 Массу больше груза, чем обычно, прежде чем вы станете Перегруженным, и на 2 Массы больше, прежде чем вы достигнете максимума, а также бонус обстоятельства +1 к проверкам Атлетики, чтобы Вырываться и Открывать силой.\n\nДополнительный эдикт: Делать всё возможное, чтобы помогать или спасать тех, кто попал в ловушку или пострадал от стихийных бедствий","level":0,"traits":["Якша"],"tags":["yaksha"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaksha","slug":"yaksha","uuid":"Compendium.pf2e.ancestries.Item.k3zyr6du4gV0Ftuh"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"inventory.bulk.encumberedAfterAddend","value":1},{"key":"ActiveEffectLike","mode":"add","path":"inventory.bulk.maxAddend","value":2},{"key":"FlatModifier","predicate":[{"or":["action:force-open","action:escape"]}],"selector":"athletics","type":"circumstance","value":1}]}},{"id":"AWLcCe69nzxZzWQc","slug":"deny-the-firstborn-pursuit","name":"Отвергание стремления перворождённых","cat":"heritages","type":"heritage","text":"Вы дали обет укрывать других от жестокостей Первого Мира. Осведомлённый о способностях фей влиять на разум, ваш обет даёт вам ментальное сопротивление, равное половине вашего уровня (минимум 1), и бонус обстоятельства +2 к проверкам Природы, чтобы Вспомнить информацию о феях.\n\nДополнительный эдикт: Противостоять жестоким феям, которых вы встречаете (если у вас есть приемлемые шансы на успех)","level":0,"traits":["Якша"],"tags":["yaksha"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaksha","slug":"yaksha","uuid":"Compendium.pf2e.ancestries.Item.k3zyr6du4gV0Ftuh"},"rules":[{"key":"FlatModifier","predicate":["action:recall-knowledge","target:trait:fey"],"selector":"nature","type":"circumstance","value":2}]}},{"id":"gKLTlzAVapXTQ86V","slug":"reflection","name":"Отражение","cat":"heritages","type":"heritage","text":"Вы были случайно или намеренно созданы как дубликат другого существа, однако вы можете и не знать о своем происхождении. За исключением незначительной отметины или двух, вы выглядите так же, как и ваш прародитель. В дополнение к признакам своей родословной, вы получаете признак отражение. Чтобы Перевоплотиться в своего прародителя, вам не нужно совершать проверку Обмана, если только вы не взаимодействуете с личностями, которые знают его лично, или не делаете что-то, что, как известно, не в его характере. Мастер может потребовать от вас броска проверки Обмана в других обстоятельствах, например, если вы Появившийся из зеркала и общаетесь с кем-то, кто видел точное подобие вашего прародителя и может заметить отличительную черту не на той стороне. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей отражения и способностей своей родословной.\n\nОтражение","level":0,"traits":["отражение"],"tags":["reflection"],"rarity":"редкий","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[]}},{"id":"1lv7RMp7t5iqeUFT","slug":"hunting-catfolk","name":"Охотничий коточеловек","cat":"heritages","type":"heritage","text":"Вы происходите из целого поколения опытных охотников и следопытов и обладаете особенно острым обонянием.\n\nВы получаете неточное сенсорное чувство нюха с дистанцией 30 футов. Это значит, что вы можете использовать свое чувство запаха, чтобы определять местоположение существа, как описано в Особых чувствах. Обычно Мастер удвоит дистанцию, если вы с подветренной стороны от существа, или уменьшит вдвое, если против ветра.\n\nВ дополнение, вы получаете бонус обстоятельства +2 для Выслеживания существа или объекта, если вы ощущали его запах ранее.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Catfolk","slug":"catfolk","uuid":"Compendium.pf2e.ancestries.Item.972EkpJOPv9KkQIW"},"rules":[{"key":"FlatModifier","label":"Hunting Catfolk (Track smelled creatures)","predicate":["action:track","target:previously-smelled"],"selector":"survival","type":"circumstance","value":2},{"acuity":"imprecise","key":"Sense","range":30,"selector":"scent"}]}},{"id":"VqgrYMaAwnNjT9Mn","slug":"enchanting-lily","name":"Очаровывающая лилия","cat":"heritages","type":"heritage","text":"Вы так сладко пахнете — нежным, цветочным букетом, похожим на пьянящий аромат лилий и мягкий запах сирени. Вы обучены Дипломатии (или другому навыку, если вы уже были обучены Дипломатии). Вы также получаете бонус обстоятельства +1 к проверкам Произвести впечатление, если цель может чувствовать ваш аромат.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ghoran","slug":"ghoran","uuid":"Compendium.pf2e.ancestries.Item.tSurOqRcfumadTfr"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.diplomacy.rank","value":1},{"key":"FlatModifier","predicate":["action:make-an-impression","enchanting-lily"],"selector":"diplomacy","type":"circumstance","value":1}]}},{"id":"qKn9k3TQt0gsOLn7","slug":"hardshell-surki","name":"Панцирный суркай","cat":"heritages","type":"heritage","text":"Ваш панцирь гораздо плотнее, чем у других суркаев, и представляет собой ваш собственный доспех. Ваш панцирь является средним доспехом из группы латных, дающий бонус предмета +4 к КБ, и ограничение модификатора Ловкости к КБ равное +1, штраф проверки −2, штраф Скорости −5 футов, значение Силы +3 и признак удобный. Вы никогда не сможете надеть другой доспех или снять панцирь. Вы можете гравировать на панцирь руны доспехов.\n\nЭволюция: Система магических сосудов, соединяющая ваши узлы, превратилась в армирующую сеть, укрепляющую ваш панцирь магической энергией. Если вы получаете критическое попадание, наносящее физический урон, вы можете использовать свою реакцию (Реакция), чтобы совершить Чистую проверку (КС 17). При успехе атака становится обычным попаданием.\n\nЭволюция: Ваши брюшинные узлы могут проецировать поле вокруг вас, которое охраняет вас от наиболее знакомого вам типа магии. Вы получаете действие Гасящие гармоники.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Surki","slug":"surki","uuid":"Compendium.pf2e.ancestries.Item.ALOmLePjbc37ca3Y"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"flags.system.surki.evolutions","value":{"label":"Усиленный панцирь","predicate":[{"not":"evolution:strengthened-carapace"}],"value":"strengthened-carapace"},"resolvedValues":{}},{"key":"ActiveEffectLike","mode":"add","path":"flags.system.surki.evolutions","value":{"label":"Гасящие гармоники","predicate":[{"not":"evolution:dampening-field"}],"value":"dampening-field"},"resolvedValues":{}},{"allowDuplicate":false,"key":"GrantItem","predicate":["evolution:dampening-field"],"reevaluateOnUpdate":true,"uuid":"Compendium.pf2e.actionspf2e.Item.Dampening Harmonics"},{"key":"GrantItem","uuid":"Compendium.pf2e.equipment-srd.Item.Hardshell Surki Carapace","grantId":"iwsNMFqLdORjkotL"}]}},{"id":"4BiGekRGfBRC7DoI","slug":"sailfish-merfolk","name":"Парусниковый мерфолк","cat":"heritages","type":"heritage","text":"Нижняя половина вашего тела напоминает мощного парусника с большим спинным плавником. С помощью этого плавника вы можете быстрее передвигаться по воде и прыгать дальше. Ваша скорость плавания увеличивается до 30 футов. Когда вы пытаетесь совершить Прыжок в высоту или Прыжок в длину, вы получаете бонус обстоятельства +1 к проверке Атлетики, а перед прыжком можете \"Плыть\", а не \"Перемещаться\".","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Merfolk","slug":"merfolk","uuid":"Compendium.pf2e.ancestries.Item.FUqZRllwn6kmFA8K"},"rules":[{"key":"FlatModifier","predicate":[{"or":["action:high-jump","action:long-jump"]}],"selector":"athletics","type":"circumstance","value":1}]}},{"id":"fWT7Mo2vFC10H4Wq","slug":"songbird-strix","name":"Певчий стрикс","cat":"heritages","type":"heritage","text":"Вы происходите из талантливого рода стриксов рассказчиков. С самых высоких гор и чистейших пейзажей, где ваши легкие наполняются великолепным чистым воздухом, вы издаете трели, свист и нежные песни. В то время как естественные звуки делают вас предрасположенным к пению, голос делает вас предрасположенным к подражанию. Вы получаете бонус обстоятельства +1 к проверкам Обмана, чтобы Подражать имитации голоса, в тех случаях когда звук голоса является единственным фактором; если вы являетесь мастером Обмана, то вместо этого получаете бонус обстоятельства +2. Вы также получаете бонус обстоятельства +1 к проверкам Выступления при пении; если вы являетесь мастером Выступления, то вместо этого получаете бонус обстоятельства +2.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Strix","slug":"strix","uuid":"Compendium.pf2e.ancestries.Item.GXcC6oVa5quzgNHD"},"rules":[{"key":"FlatModifier","predicate":["action:impersonate","voice-only"],"selector":"deception","type":"circumstance","value":"ternary(gte(@actor.system.skills.deception.rank,3),2,1)"},{"key":"FlatModifier","predicate":["action:perform:singing"],"selector":"performance","type":"circumstance","value":"ternary(gte(@actor.system.skills.performance.rank,3),2,1)"}]}},{"id":"OOkgTzDU4mBvV98Z","slug":"pelagic-merfolk","name":"Пелагический мерфолк","cat":"heritages","type":"heritage","text":"Вы — мерфолк открытых морей. Ваш хвост повторяет узор серебристого тунца и сельди, которые миллионами снуют в ваших охотничьих угодьях. Вода повинуется вашей воле, и одним коротким словом вы можете создать вокруг себя оболочку из неё. Вы получаете действие Защитная волна.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Merfolk","slug":"merfolk","uuid":"Compendium.pf2e.ancestries.Item.FUqZRllwn6kmFA8K"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Shielding Wave"}]}},{"id":"G5U7zxwxDmERm3EY","slug":"peachchild-leshy","name":"Персиковый леший","cat":"heritages","type":"heritage","text":"Ваш дух лешего поселился в огромном персиковом плоде, после чего из него вышло ваше тело, возможно подражая прошлому герою, родившемуся таким же образом. Вы похожи на человеческого ребенка, но с вечным розовым румянцем на лице и, возможно, несколькими персиковыми листьями, растущими из вашего тела. Дух природы, живущий в вас, не дает покоя некоторым животным.\n\nВы можете задавать вопросы и получать ответы от домашних животных и скота, таких как собаки и фазаны, а также использовать Дипломатию, чтобы попытаться Произвести впечатление и высказать Просьбу им. Большинство домашних животных изначально относятся к вам безразлично или дружественно и дают вам время, чтобы привести свои доводы, хотя другие животные реагируют на вас, как на любого другого авантюриста.","level":0,"traits":["Леший"],"tags":["leshy"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[]}},{"id":"6xxXtgj3fcCi53lt","slug":"sandstrider-lizardfolk","name":"Песчаный людоящер","cat":"heritages","type":"heritage","text":"Ваши толстые чешуйки помогают вам удерживать воду и бороться с солнечными бликами. Вы получаете сопротивление огню, равное половине своего уровня (минимум 1). Вы считаете эффекты Жаркой окружающей среды так, как если бы они были на одну ступень лучше (невероятная жара становится экстремальной, экстремальная жара становится суровой и так далее), и вы можете в 10 раз дольше обходиться без воды и еды, прежде чем начнете подвергаться эффектам голода или жажды. Однако, если только вы не носите защищающее снаряжение или сидите в укрытии, эффекты Холодной окружающей среды для вас на одну ступень хуже.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Lizardfolk","slug":"lizardfolk","uuid":"Compendium.pf2e.ancestries.Item.HWEgF7Gmoq55VhTL"},"rules":[]}},{"id":"JW45oQRHaqthjmIx","slug":"cave-kholo","name":"Пещерный кхоло","cat":"heritages","type":"heritage","text":"Говорят, что кхоло жили в пещерах и под землей ещё до того, как большинство представителей вашего вида выбрались на свет. Вы напоминаете тех древних, с широкой грудью и отметинами, похожими на короткие черные полосы, а не на пятна. Ваши глаза развиты так, что прекрасно видят в темноте, что является ценным преимуществом для вашего клана. Вы получаете Ночное зрение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kholo","slug":"kholo","uuid":"Compendium.pf2e.ancestries.Item.vxbQ1Yw4qwgjTzqo"},"rules":[{"key":"Sense","selector":"darkvision"}]}},{"id":"NfIAGatB1KIzt8G7","slug":"cavern-elf","name":"Пещерный эльф","cat":"heritages","type":"heritage","text":"Вы родились или провели много лет в подземных туннелях или пещерах, где недостаточно света. Вы получаете Ночное зрение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Elf","slug":"elf","uuid":"Compendium.pf2e.ancestries.Item.PgKmsA2aKdbLU6O0"},"rules":[{"key":"Sense","selector":"darkvision"}]}},{"id":"KbG2BZ3Sbr3xU1sW","slug":"pixie","name":"Пикси","cat":"heritages","type":"heritage","text":"Вы больше других спрайтов. Вместо Крошечного размера, вы имеете Маленький размер.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sprite","slug":"sprite","uuid":"Compendium.pf2e.ancestries.Item.TRqoeYfGAFjQbviF"},"rules":[]}},{"id":"nlhVoQDfLKYM3j1l","slug":"swimming-animal","name":"Плавающее животное","cat":"heritages","type":"heritage","text":"Вы — водное животное, которому комфортнее всего в воде. Вы можете проводить большую часть времени в воде, как аллигатор, тюлень, кит или дельфин, или же вам нужна вода, чтобы дышать, как рыбе или некоторым ракообразным.\n\nУ вас есть одна атака животного (обычно коготь, челюсти или хвост). Выберите, являетесь ли вы водным существом или обитающим в воде.\n\nВодное: Вы получаете признак водный и Скорость плаванья 30 футов. Признак водный означает, что вы дышите водой, но не воздухом, и ваши дробящие или рубящие безоружные \"Удары\" не получают обычный штраф −2 за нахождение под водой.\n\nОбитающее в воде: Вы можете задерживать дыхание под водой на 10 минут прежде чем начать Задыхаться. У вас Скорость плавания 20 футов, и если вы можете двигаться по суше, ваша базовая Скорость 20 футов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Awakened Animal","slug":"awakened-animal","uuid":"Compendium.pf2e.ancestries.Item.GFOgV3MzWkYwJoJW"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.ancestryfeatures.Item.Animal Attack","grantId":"oj532l4YXqzedBBn"},{"key":"ActiveEffectLike","mode":"upgrade","path":"flags.system.remainingAir.rounds","predicate":["swimming-animal:water-dwelling"],"value":"100"},{"adjustName":false,"choices":[{"label":"Водный","value":"aquatic"},{"label":"Обитающее в воде","value":"water-dwelling"}],"key":"ChoiceSet","prompt":"Выберите, являетесь ли вы водным или обитающим в воде животным","rollOption":"swimming-animal"}]}},{"id":"EKY9v7SF1hVsUdbH","slug":"changeling","name":"Подменыш","cat":"heritages","type":"heritage","text":"Вашей матерью была карга. Ваша гетерохромия — наиболее очевидный признак этого происхождения, но вы, вероятно, также имеете более тонкое телосложение, более бледную кожу и более темные волосы, чем у большинства представителей родословной вашего другого родителя. Вы получаете признак подменыш. Вы также получаете Сумеречное зрение или Ночное зрение, если ваша родословная уже имеет сумеречное зрение. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей подменыша и способностей родословной своего другого родителя.\n\nПодменыш","level":0,"traits":["подменыш"],"tags":["changeling"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"key":"Sense","selector":"low-light-vision"},{"key":"Sense","predicate":["self:low-light-vision:from-ancestry"],"selector":"darkvision"}]}},{"id":"CkrTRdLfDDDUOCqP","slug":"quilled-athamaru","name":"Покрытый иглами атамару","cat":"heritages","type":"heritage","text":"Острые иглы на вашей голове могут глубоко пронзить врага. Большинство атамару используют такие иглы для защиты, но вовремя нанесенный удар головой может оказаться разрушительным. Вы получаете безоружную атаку ближнего боя иглами, наносящую 1к6 колющего урона. Ваши иглы относятся к группе \"драка\" и имеют признаки безоружное, быстрое и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Athamaru","slug":"athamaru","uuid":"Compendium.pf2e.ancestries.Item.Cg1AMgp3zrGmimWd"},"rules":[]}},{"id":"vDEfNzjLpGJU54cz","slug":"quillcoat-shisk","name":"Покрытый иглами шиск","cat":"heritages","type":"heritage","text":"Ваше тело приспособило защитный механизм, чтобы сломать ваши иглы об нападающего, что позволяет вам защищаться от агрессивных хищников, однако, чтобы иглы выросли, требуется время. Вы получаете реакцию Колючие иглы.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Shisk","slug":"shisk","uuid":"Compendium.pf2e.ancestries.Item.x1YinOddgUxwOLqP"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Barbed Quills"}]}},{"id":"G9Gwfi8ZIva52uGp","slug":"jinxed-halfling","name":"Полурослик со сглазом","cat":"heritages","type":"heritage","text":"Вы родились со странным благословением: лишившись обычной удачи полурослика, вместо этого вы можете манипулировать удачей других. Вы ни при каких условиях не можете взять способность Удача полурослика и получаете действие Сглаз.","level":0,"traits":[],"tags":[],"rarity":"необычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Halfling","slug":"halfling","uuid":"Compendium.pf2e.ancestries.Item.GgZAHbrjnzWOZy2v"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Jinx"}]}},{"id":"RxNBBMFZwPA3Vlg3","slug":"shoreline-strix","name":"Прибрежный стрикс","cat":"heritages","type":"heritage","text":"Вы потомок стриксов, которые путешествовали по побережью. Ваши перья обладают особой водоотталкивающей способностью и имеют гладкий угол для ныряния, что позволяет ловить рыбу и другую добычу на мелководье. Вы обучены Атлетике и получаете способность навыка Подводный мародер как бонусную способность навыка.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Strix","slug":"strix","uuid":"Compendium.pf2e.ancestries.Item.GXcC6oVa5quzgNHD"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.athletics.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Underwater Marauder","grantId":"iOY6YfGBaOvMNAor"}]}},{"id":"7ZDCShtRg5QZggrU","slug":"inured-azarketi","name":"Привыкший азаркет","cat":"heritages","type":"heritage","text":"Вашим предкам приходилось выживать в загрязненной воде, каждый вдох которой был пагубным. Вы получаете сопротивление яду, равное половине вашего уровня (минимум 1). Кроме того, вы можете выжить вне воды 72 часа, прежде чем начнёте задыхаться.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Azarketi","slug":"azarketi","uuid":"Compendium.pf2e.ancestries.Item.yFoojz6q3ZjvceFw"},"rules":[]}},{"id":"HFHSh2RWuxa4GhhQ","slug":"benthic-azarketi","name":"Придонный азаркет","cat":"heritages","type":"heritage","text":"Ваше наследие восходит к азаркетам, живущим глубоко под океаном, и вы можете справиться с леденящими глубинами легче, чем большинство. Вы получаете сопротивление холоду, равное половине вашего уровня (минимум 1), и когда вы мокрый, то не считаете воздействие эффектов Холодной окружающей среды так, как если бы они были на одну ступень хуже. Вы автоматически приспосабливаетесь к перепадам давления из-за того, что находитесь глубоко под водой, без вредных последствий.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Azarketi","slug":"azarketi","uuid":"Compendium.pf2e.ancestries.Item.yFoojz6q3ZjvceFw"},"rules":[]}},{"id":"sLYYvpSWzCWDfAHq","slug":"benthic-athamaru","name":"Придонный атамару","cat":"heritages","type":"heritage","text":"Вы адаптировались к быстрому подъёму и спуску глубинах океана, умело управляя своим плавательным пузырем. Плаванье вверх и вниз не считается для вас Сложной местностью. Также, ваше зрение адаптировалось к тёмной воде, обеспечивая вам Ночное зрение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Athamaru","slug":"athamaru","uuid":"Compendium.pf2e.ancestries.Item.Cg1AMgp3zrGmimWd"},"rules":[{"acuity":"precise","key":"Sense","selector":"darkvision"}]}},{"id":"vrU3lmDO7FYzmuQc","slug":"prismatic-vishkanya","name":"Призматический вишканья","cat":"heritages","type":"heritage","text":"Ваша чешуя мерцает и переливается на свету пьянящим разнообразием цвета. Вы становитесь обучены Выступлению (или другому навыку на свой выбор, если вы уже обучены Выступлению) и получаете способность навыка Завораживающее выступление.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Vishkanya","slug":"vishkanya","uuid":"Compendium.pf2e.ancestries.Item.u1VJEXsVlmh3Fyx0"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.performance.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Fascinating Performance","grantId":"7LB00jkh6JaJr3vS"}]}},{"id":"Je15UGsLWYaaGJSW","slug":"ghost-poppet","name":"Призрачная кукла","cat":"heritages","type":"heritage","text":"Вы пробудились, когда в ваше созданное тело попали частица жизненной силы другой персоны и фрагмент его души, возможно, в момент его смерти, но это не всегда так. Вы не помните ничего, кроме смутных вспышек о своей \"жизни до\", но эта жизненная сущность по-прежнему защищает вас. Вы получаете сопротивление негативному урону, равное половине вашего уровня (минимум 1).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Poppet","slug":"poppet","uuid":"Compendium.pf2e.ancestries.Item.6F2fSFC1Eo1JdpY4"},"rules":[]}},{"id":"7gGcpQMqnZhBDZLI","slug":"adaptive-anadi","name":"Приспособляющийся анади","cat":"heritages","type":"heritage","text":"Вы происходите из рода анади, которые работали над совершенствованием своей магии трансформации, позволяя им интегрироваться в более широкий спектр культур. Выберите обычную, гуманоидную родословную среднего размера. Ваша человеческая форма заменяется этой формой, соответствующей вашему выбору. Вы также получаете способность Заимствованная родословная для выбранной вами гуманоидной родословной.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Anadi","slug":"anadi","uuid":"Compendium.pf2e.ancestries.Item.TQEqWqc7BYiadUdY"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Adopted Ancestry","grantId":"ihN8gkHSdPG9Trte"}]}},{"id":"g4FRxyuHndZu4KTo","slug":"jinxed-tengu","name":"Проклятый тэнгу","cat":"heritages","type":"heritage","text":"Ваш род подвергался проклятию за проклятием, и теперь они соскальзывают с ваших перьев, как дождь. Если вы преуспеваете в спасброске против проклятия или эффекта неудачи, результат считается критическим успехом.\n\nКогда вы получите состояние Обречен, совершите Чистую проверку (КС 17). В случае успеха, снизьте величину состояния {обречён}, которое вы получите, на 1.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tengu","slug":"tengu","uuid":"Compendium.pf2e.ancestries.Item.18xDKYPDBLEv2myX"},"rules":[]}},{"id":"cnbwtbDmlD0KoLqY","slug":"insightful-goloma","name":"Проницательный голома","cat":"heritages","type":"heritage","text":"Вы научились следить за явными признаками опасных чувств, что помогает вам избегать неприятностей. Вы получаете бонус обстоятельства +1 к вашему КС Восприятия против попыток Лгать вам, и к вашим проверкам Восприятия, чтобы Понять намерение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goloma","slug":"goloma","uuid":"Compendium.pf2e.ancestries.Item.c4secsSNG2AO7I5i"},"rules":[{"key":"FlatModifier","predicate":["action:sense-motive"],"selector":"perception","slug":"insightful-goloma-sense-motive","type":"circumstance","value":1},{"key":"FlatModifier","predicate":["action:lie"],"selector":"perception-dc","slug":"insightful-goloma-lie","type":"circumstance","value":1}]}},{"id":"P8Rl3dUsq8AzXLHC","slug":"sturdy-skeleton","name":"Прочный скелет","cat":"heritages","type":"heritage","text":"Некоторые опасные условия не подходят для обычного скелета, поэтому некромант может выбрать для оживления кости дварфа, орка или другого существа, имеющего репутацию выносливого. Вы получаете 10 Очков Здоровья вместо 6 и получаете способность Несгибаемый.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Skeleton","slug":"skeleton","uuid":"Compendium.pf2e.ancestries.Item.58rL5sg2y4arW1i5"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Diehard","grantId":"I0BhPWqYf1bbzEYg"},{"key":"ActiveEffectLike","mode":"override","path":"system.attributes.ancestryhp","value":10}]}},{"id":"twayjFuXbsvyHUwy","slug":"desert-rat","name":"Пустынная крыса","cat":"heritages","type":"heritage","text":"Вы родом из засушливых равнин и, вероятно, выросли, путешествуя по дорогам. Если обе ваши руки свободны, то можете увеличить свою Скорость до 30 футов, так как вы бегаете на всех четырех. Кроме того, вы считаете эффекты Жаркой окружающей среды так, как если бы они были на одну ступень лучше (невероятная жара становится экстремальной, экстремальная жара становится суровой и так далее), и вы можете в 10 раз дольше обходиться без воды и еды, прежде чем начнете подвергаться эффектам голода или жажды. Однако, если только вы не носите защищающее снаряжение или сидите в укрытии, эффекты Холодной окружающей среды для вас на одну ступень хуже.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ratfolk","slug":"ratfolk","uuid":"Compendium.pf2e.ancestries.Item.P6PcVnCkh4XMdefw"},"rules":[{"key":"FlatModifier","predicate":["hands-free:2"],"selector":"land-speed","value":5}]}},{"id":"kiKxnKd7Dfegk9dM","slug":"desert-elf","name":"Пустынный эльф","cat":"heritages","type":"heritage","text":"Вы живете под палящим зноем пустыни, приобретая невероятную устойчивость к жаркой окружающей среде. Вы получаете сопротивление огню, равное половине вашего уровня (минимум 1), и считаете эффекты Жаркой окружающей среды так, как если бы они были на одну ступень лучше (невероятная жара становится экстремальной, экстремальная жара становится сильной и так далее).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Elf","slug":"elf","uuid":"Compendium.pf2e.ancestries.Item.PgKmsA2aKdbLU6O0"},"rules":[]}},{"id":"hFBwsVcSnNCJoimo","slug":"versatile-human","name":"Разносторонний человек","cat":"heritages","type":"heritage","text":"Многогранность и амбиции человечества способствовали тому, что они стали самой распространенной родословной в большинстве наций мира. Выберите общую способность для которой вы подходите по предварительным условиям (как и в случае со способностью родословной, вы можете выбрать эту способность на любом этапе создания персонажа).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Human","slug":"human","uuid":"Compendium.pf2e.ancestries.Item.IiG7DgeLWYrSNXuX"},"rules":[{"key":"GrantItem","uuid":"{item|flags.system.rulesSelections.versatileHeritage}"},{"adjustName":false,"choices":{"filter":["item:level:1","item:trait:general"],"itemType":"feat"},"flag":"versatileHeritage","key":"ChoiceSet","prompt":"Выберите общую способность 1-го уровня."}]}},{"id":"GlejQr3rBh3sn8sL","slug":"river-azarketi","name":"Речной азаркет","cat":"heritages","type":"heritage","text":"Вы родом из азаркетов, которые покинули океаны ради пресной воды наземной жизни. Разнообразная география рек требовала от вас развития высоких физических навыков, чтобы плавать против стремнин, перепрыгивать каскадные воды и ловко перемещаться по мелким и узким руслам.\n\nКогда вы получаете успех проверки Атлетики, чтобы Плыть, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Azarketi","slug":"azarketi","uuid":"Compendium.pf2e.ancestries.Item.yFoojz6q3ZjvceFw"},"rules":[]}},{"id":"87Eej7uEvTxXeli7","slug":"riverside-tripkee","name":"Речной трипки","cat":"heritages","type":"heritage","text":"Ваши предки жили рядом с и в воде. Вы получаете Скорость плавания 15 футов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tripkee","slug":"tripkee","uuid":"Compendium.pf2e.ancestries.Item.hXM5jXezIki1cMI2"},"rules":[]}},{"id":"VAo6NnrCEAAOUSkc","slug":"resolute-fetchling","name":"Решительный фечлинг","cat":"heritages","type":"heritage","text":"Ваши предки уже давно сталкивались с ужасами, на Теневом плане или где-то еще, и вы несете их ментальную стойкость. Когда при спасброске против эффекта с признаком эмоция вы получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fetchling","slug":"fetchling","uuid":"Compendium.pf2e.ancestries.Item.hIA3qiUsxvLZXrFP"},"rules":[]}},{"id":"Q5NrFWKDMCoVn9qR","slug":"reef-merfolk","name":"Рифовый мерфолк","cat":"heritages","type":"heritage","text":"Вы выросли среди разноцветных кораллов и косяков тропических рыб. По сравнению с большинством мерфолков, ваше тело пестрит полосами, пятнами и узорами, как у рыбы-клоуна или рыбы-ангела. Вы привыкли к ядовитым обитателям вашего дома, и вас мало беспокоят укусы или мелкие яды. Вы получаете сопротивление яду, равное половине вашего уровня (минимум 1), и каждый из ваших успешных спасбросков против недуга-яда снижает его стадию на 2, или на 1 для вирулентного яда. Каждый критический успех против действующего яда снижает его стадию на 3, или на 2 для вирулентного яда.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Merfolk","slug":"merfolk","uuid":"Compendium.pf2e.ancestries.Item.FUqZRllwn6kmFA8K"},"rules":[]}},{"id":"w5801ArZQCU8IXnU","slug":"wishborn-poppet","name":"Рождённая желанием кукла","cat":"heritages","type":"heritage","text":"Ваша жизнь была дарована желанием либо могущественного заклинателя, либо искренней невинной личности, которая вас очень любила. Вы живое доказательство того, что дух надежды может преодолеть любую преграду. Если при спасброске против эффекта страха или эмоции вы получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Poppet","slug":"poppet","uuid":"Compendium.pf2e.ancestries.Item.6F2fSFC1Eo1JdpY4"},"rules":[]}},{"id":"buGlGWcCrdNxfCr4","slug":"born-of-animal","name":"Рождённый животным","cat":"heritages","type":"heritage","text":"Вы были простым животным, пока солнце не просветило вас.\n\nФорма гуманоида: Животные чувствуют силу вашего присутствия. Вы получаете бонус обстоятельства +1 к проверкам Запугивания против животных и чудовищ и не получаете штрафа за попытку Деморализовать животных или чудовищ, с которыми вы не говорите на одном языке.\n\nФорма яогая: Вы можете мчаться как животное. Если у вас свободны обе руки, вы можете увеличить свою Скорость до 30 футов, поскольку бежите на четырёх ногах.","level":0,"traits":["Яогай"],"tags":["yaoguai"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaoguai","slug":"yaoguai","uuid":"Compendium.pf2e.ancestries.Item.dnk0Rf7AUmyR5b8z"},"rules":[{"key":"FlatModifier","predicate":["change-shape:humanoid",{"or":["target:trait:animal","target:trait:beast"]}],"selector":"intimidation","type":"circumstance","value":1}]}},{"id":"Iaq8C3bbC9EzZhBJ","slug":"born-of-celestial","name":"Рождённый небожителем","cat":"heritages","type":"heritage","text":"Когда-то вы были могущественным небожителем, но после побега или великого наказания оказались заперты в смертной оболочке, имея лишь смутные воспоминания и ограниченные силы. Из-за остаточной божественной силы обычай заклинаний и магических умений, полученных от наследия или способности родословной яогая становится сакральным вместо любого другого (обычно оккультного).\n\nФорма гуманоида: Фрагменты божественной памяти всё ещё хранятся в вашем разуме. Вы получаете бонус обстоятельства +1 к проверкам Религии.\n\nФорма яогая: Через вас течёт небесная сила. Выберите одни чары из списка сакральных заклинаний. Вы можете сотворять это заклинание по желанию как врождённые сакральные чары. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округленной в большую сторону.","level":0,"traits":["Яогай"],"tags":["yaoguai"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaoguai","slug":"yaoguai","uuid":"Compendium.pf2e.ancestries.Item.dnk0Rf7AUmyR5b8z"},"rules":[{"key":"FlatModifier","predicate":["change-shape:humanoid"],"selector":"religion","type":"circumstance","value":1}]}},{"id":"kHvlHDq5hs2JDG0Y","slug":"born-of-item","name":"Рождённый предметом","cat":"heritages","type":"heritage","text":"Вы были предметом, пока луна не вдохнула в вас жизнь. Выберите один навык Знаний, связанный с тем, каким инструментом вы были, например Кулинарные знания для тесака или Фермерские знания для граблей. Вы обучены этому навыку.\n\nФорма гуманоида: Вы сохраняете воспоминания о задачах, которые вы выполняли как предмет. Вы получаете бонус обстоятельства +1 к навыку Знаний, полученному вами благодаря этому наследию.\n\nФорма яогая: То время, что вы были неразумным предметом, затрудняет ментальное воздействие на вас. Если при спасброске против ментального эффекта вы получаете успех, результат считается критическим успехом.","level":0,"traits":["Яогай"],"tags":["yaoguai"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaoguai","slug":"yaoguai","uuid":"Compendium.pf2e.ancestries.Item.dnk0Rf7AUmyR5b8z"},"rules":[]}},{"id":"y87jU1yU8Plz4Yhq","slug":"born-of-vegetation","name":"Рождённый растением","cat":"heritages","type":"heritage","text":"Вы были растением или грибом, пока дождь не подарил вам разум. Вы получаете признак растение или грибковый.\n\nФорма гуманоида: Благодаря свежей растительности вы можете лучше помогать тем, кто в этом нуждается. Вы получаете бонус обстоятельства +1 к проверкам Медицины, чтобы оказывать Первую помощь.\n\nФорма яогая: Когда кто-то использует навык Медицины, чтобы Лечить ваши раны, вы добавляете свой уровень к ОЗ, восстановленным в результате этого лечения. Кроме того, существо, совершающее эту проверку, получает бонус обстоятельства +1, если у вас есть признак растение и вы находитесь на ярком свету, или признак грибковый и вы находитесь в темноте.","level":0,"traits":["Яогай"],"tags":["yaoguai"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaoguai","slug":"yaoguai","uuid":"Compendium.pf2e.ancestries.Item.dnk0Rf7AUmyR5b8z"},"rules":[{"key":"FlatModifier","predicate":["action:administer-first-aid","change-shape:humanoid"],"selector":"medicine","type":"circumstance","value":1},{"key":"FlatModifier","predicate":["action:treat-wounds","change-shape:yaoguai","check:statistic:medicine"],"selector":"healing-received","value":"@actor.level"},{"choices":[{"label":"Грибковый","value":"fungus"},{"label":"Растение","value":"plant"}],"flag":"trait","key":"ChoiceSet","prompt":"Выберите признак."}]}},{"id":"RXn2y7QVHVB0XHr8","slug":"born-of-elements","name":"Рождённый стихией","cat":"heritages","type":"heritage","text":"Вы были аспектом природы — дождём, ветром, лучом солнца — пока дикие сущности не наделили вас душой. Из-за вашей природной связи обычай заклинаний и магических умений, полученных от наследия или способности родословной яогая становится природным вместо любого другого (обычно оккультного).\n\nФорма гуманоида: Вы сохраняете связь с миром природы. Вы получаете бонус обстоятельства +1 к проверкам Выживания, чтобы Определять направление, и не получаете штрафа, если у вас нет компаса.\n\nФорма яогая: Сила природы течет через вас, готовая разить. Выберите одно из следующих чар: Воспламенение, Иглы-дротики, Лесоповал, Обморожение, Рассеять щебень, Столб воды, Хлёсткий ветер или Электрическая дуга. Вы можете сотворять эти чары как врождённое природное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округленной в большую сторону.","level":0,"traits":["Яогай"],"tags":["yaoguai"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Yaoguai","slug":"yaoguai","uuid":"Compendium.pf2e.ancestries.Item.dnk0Rf7AUmyR5b8z"},"rules":[{"key":"FlatModifier","predicate":["action:sense-direction","change-shape:humanoid"],"selector":"survival","type":"circumstance","value":1},{"adjustName":false,"choices":{"filter":[{"or":["item:slug:electric-arc","item:slug:frostbite","item:slug:ignition","item:slug:needle-darts","item:slug:timber","item:slug:scatter-scree","item:slug:slashing-gust","item:slug:spout"]}],"itemType":"spell","slugsAsValues":true},"flag":"cantrip","key":"ChoiceSet","prompt":"Выберите чары.","rollOption":"born-of-elements"}]}},{"id":"BDBzVaZx3GfZXs5b","slug":"breaker-surki","name":"Роющий суркай","cat":"heritages","type":"heritage","text":"Ваши когти особенно тверды и могут пробиваться как сквозь землю, так и сквозь хищников. Вы получаете безоружную атаку когтями, которая наносит 1к4 рубящего урона. Ваши когти относятся к группе \"драка\", и имеют признаки безоружное, быстрое, универсальное Д и точное.\n\nЭволюция: Узлы на ваших запястьях проецируют магию в прочный копательный клин. Вы можете действием Взаимодействовать увеличить урон безоружной атаки когтем до 1к6, добавить ей признаки магический, универсальное сила и повреждающее и убрать признак быстрое. Вы можете потратить ещё одно действие, чтобы деактивировать клин и вернуть когтю его обычную статистику.\n\nЭволюция: Ваши голеностопные узлы могут выпускать заземляющие когтистые шипы магии, удерживающие вас на месте. Если какой-либо эффект вынуждает вас сдвинуться на 10 футов или более, вы можете решить сдвинуться только на половину расстояния. Дополнительное сцепление с поверхностью благодаря когтевым шипам позволяет вам Карабкаться с одной занятой рукой (или обеими занятыми руками, если у вас есть способность Боевой альпинист). Вы получаете реакцию Рытьё траншеи.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Surki","slug":"surki","uuid":"Compendium.pf2e.ancestries.Item.ALOmLePjbc37ca3Y"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"flags.system.surki.evolutions","value":{"label":"Копательный клин","predicate":[{"not":"evolution:digging-wedge"}],"value":"digging-wedge"},"resolvedValues":{}},{"key":"ActiveEffectLike","mode":"add","path":"flags.system.surki.evolutions","value":{"label":"Заземляющие когтистые шипы","predicate":[{"not":"evolution:claw-spikes"}],"value":"claw-spikes"},"resolvedValues":{}},{"allowDuplicate":false,"key":"GrantItem","predicate":["evolution:claw-spikes"],"reevaluateOnUpdate":true,"uuid":"Compendium.pf2e.actionspf2e.Item.Trench Digging"}]}},{"id":"MoeWxhJEtteD3v9z","slug":"sanctuary-samsaran","name":"Самсар из убежища","cat":"heritages","type":"heritage","text":"Ваши прошлые воплощения перерождались в убежищах, расположенных в северном Чжи Ха, и Вы припоминаете, как обучались там концентрации и фокусировке. Ваши разрозненные воспоминания также могут касаться книг, которые Вы охотно изучали. Вы получаете действие Взгляд в прошлое.","level":0,"traits":["Самсар"],"tags":["samsaran"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Samsaran","slug":"samsaran","uuid":"Compendium.pf2e.ancestries.Item.l7vjMIbPAUvEIosU"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Tap the Past"}]}},{"id":"e4FaENGKRD3fxZeJ","slug":"wilderness-samsaran","name":"Самсар отшельник","cat":"heritages","type":"heritage","text":"Ваши прошлые жизни проходили в различных удаленных от цивилизации местах Тянь Ся и других регионов. Вам приходилось учиться выживать в дикой природе, и вы унаследовали часть воспоминаний о тех временах. Вы становитесь обучены Выживанию. Если вы автоматически становитесь обученным этому навыку (например, из-за предыстории или класса), вместо этого вы становитесь обучены навыку на свой выбор. Вы можете игнорировать Сложную местность, вызванную деревьями, листвой и зарослями.","level":0,"traits":["Самсар"],"tags":["samsaran"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Samsaran","slug":"samsaran","uuid":"Compendium.pf2e.ancestries.Item.l7vjMIbPAUvEIosU"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.survival.rank","value":1}]}},{"id":"DR6okTFLHi3MYbzK","slug":"oracular-samsaran","name":"Самсар провидец","cat":"heritages","type":"heritage","text":"Ваши прошлые жизни углубили понимание мира духов, а тенденция истории повторяться позволяет Вам предугадывать будущие события. Выберите арканный, оккультный или сакральный обычай. Вы получаете одни чары из списка заклинаний выбранного обычая. Вы можете сотворять эти врождённые чары по желанию, как заклинание выбранного обычая. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону.","level":0,"traits":["Самсар"],"tags":["samsaran"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Samsaran","slug":"samsaran","uuid":"Compendium.pf2e.ancestries.Item.l7vjMIbPAUvEIosU"},"rules":[]}},{"id":"NK88lPzi3SDAT8w5","slug":"healer-samsaran","name":"Самсар целитель","cat":"heritages","type":"heritage","text":"В поисках просветление Ваши прошлые воплощения покинули родные земли Чжи Ха, исследуя различные народы Тянь Ся и других мест Голариона. Вам приходилось попадать в опасные ситуации, и вы часто получаете обрывочные воспоминания о том, как обрабатывали раны. Вы становитесь обучены Медицине. Если вы уже стали обучены Медицине автоматически (например, благодаря своей предыстории или классу), вместо этого вы становитесь обучены другому навыку на свой выбор.\n\nЕсли вы используете Медицину для Лечения ран на себя, вы можете добавить свой уровень к количеству восстановленных ОЗ.","level":0,"traits":["Самсар"],"tags":["samsaran"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Samsaran","slug":"samsaran","uuid":"Compendium.pf2e.ancestries.Item.l7vjMIbPAUvEIosU"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.medicine.rank","value":1},{"key":"FlatModifier","predicate":["action:treat-wounds","check:statistic:medicine","origin:signature:{actor|signature}"],"selector":"healing-received","value":"@actor.level"}]}},{"id":"H2mbY3aypl6ikaSR","slug":"new-moon-sarangay","name":"Сарангай новолуния","cat":"heritages","type":"heritage","text":"Некоторые народы называют вас карликовым сарангаем, а ваш род — \"прячущимися\". Другие шепчут, что вы выходите с луной, когда луна \"выходит на охоту\", так в народе говорят, когда луна исчезает с неба в новолуние. Ваши неуловимые предки строили свои жилища в тени бамбуковых зарослей, а ваши родовые общины ценили осторожность и независимость, передавая по наследству знания о том, как ходить налегке и двигаться сквозь бамбук как дым. У ваших предков был темно-коричневый или серый мех с белыми отметинами и -образная пара плоских треугольных рогов. Ваш размер Маленький, а не Средний. Вы получаете 10 ОЗ от родословной вместо 8, и бонус обстоятельства +2 к проверкам Атлетики для Толкания.","level":0,"traits":["Сарангай"],"tags":["sarangay"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sarangay","slug":"sarangay","uuid":"Compendium.pf2e.ancestries.Item.7mpMGhVoaPANJnZ8"},"rules":[{"key":"ActiveEffectLike","mode":"override","path":"system.attributes.ancestryhp","value":10},{"key":"FlatModifier","predicate":["action:shove"],"selector":"athletics","type":"circumstance","value":2}]}},{"id":"6gK4A6dtN4LCpCXS","slug":"full-moon-sarangay","name":"Сарангай полнолуния","cat":"heritages","type":"heritage","text":"Вы выросли в шаманской традиции, выходящей за рамки одной общины или наследия сарангаев. Вы провели свою юность под руководством старейшины-шамана, научившего вас общаться с духами в надежде, что однажды вы будете использовать эти знания, чтобы давать советы и направлять свой народ. Представители вашей традиции — жрецы или шаманы, обращающиеся к духам и видящим то, что не видят другие. Вы получаете повышение атрибута Мудрости вместо Силы, и недостаток атрибута Телосложения вместо Мудрости. Вы получаете способность родословной Народный целитель.","level":0,"traits":["Сарангай"],"tags":["sarangay"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sarangay","slug":"sarangay","uuid":"Compendium.pf2e.ancestries.Item.7mpMGhVoaPANJnZ8"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Folk Healer","grantId":"ua0O6tQ3D5099mmH"}]}},{"id":"ImdAt4Ma9GfaNuZW","slug":"half-moon-sarangay","name":"Сарангай полулуния","cat":"heritages","type":"heritage","text":"Вы происходите из одной из многочисленных странствующих общин, сезонно мигрирующих вдоль обширных рек и гор Тянь Ся, принося новости и вести в деревни на своём пути. Ваш народ связывает общины сарангаев друг с другом на огромных расстояниях и символизируется половиной луны, соединяющей темное и светлое, так и вы соединяете темное со светлым, красное с синим, ветер с морем. Ваши предки были высокими и крепкими, с блестящим чёрным мехом, светлыми пятнами или отметинами и короткими, плотно изогнутыми рогами. Вы обучены двум навыкам Знаний по вашему выбору и получаете бонус обстоятельства +1 к проверкам Вспомнить информацию, используя эти навыки.","level":0,"traits":["Сарангай"],"tags":["sarangay"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sarangay","slug":"sarangay","uuid":"Compendium.pf2e.ancestries.Item.7mpMGhVoaPANJnZ8"},"rules":[]}},{"id":"BHiOV3ETYSv6k7kF","slug":"waxing-moon-sarangay","name":"Сарангай растущей луны","cat":"heritages","type":"heritage","text":"Ваши предки обитали на болотах и затопленных лесах, где они сражались со свирепыми хищниками и объединялись в рейдовые отряды, чтобы захватывать скудные ресурсы. Благословленный растущим полумесяцем, вы — один из истребителей, и вы можете преодолевать угрозы, скрывающиеся в мутной воде, так же как и те, что охотятся на суше. Ваши предки были сильными пловцами с коричневым или серым мехом и загнутыми назад или вниз рогами. Вы получаете бонус обстоятельства +2 к проверкам Атлетики для Прыжков в длину или Плавания.","level":0,"traits":["Сарангай"],"tags":["sarangay"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sarangay","slug":"sarangay","uuid":"Compendium.pf2e.ancestries.Item.7mpMGhVoaPANJnZ8"},"rules":[{"key":"FlatModifier","predicate":[{"or":["action:high-jump","action:swim"]}],"selector":"athletics","value":2}]}},{"id":"MNeg7vI854rB6fmz","slug":"waning-moon-sarangay","name":"Сарангай убывающей луны","cat":"heritages","type":"heritage","text":"Ваши предки были названы в честь переходной луны, вечно меняющейся и эфемерной. Они — хранители тайных искусств, подобно тому, как убывающая луна скрывает свой лик, и их общины высоко ценили своих сказителей, исполнителей и художников. Вы жили среди своей общины на окраинах лесов или рек, где многие ответы приходили в виде загадок и вы научились видеть мир с разных точек зрения. У ваших предков мех часто рыжего или коричневого цвета, их глаза выдающиеся, а рога — плоские и компактные. Вы обучены по вашему выбору Акробатике, Выступлению или Ремеслу. Раз в день, когда вы получаете критический провал при использовании выбранного навыка, вы можете перебросить проверку, используя новый результат, даже если он хуже. Этот переброс является эффектом удачи.","level":0,"traits":["Сарангай"],"tags":["sarangay"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sarangay","slug":"sarangay","uuid":"Compendium.pf2e.ancestries.Item.7mpMGhVoaPANJnZ8"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.{item|flags.system.rulesSelections.skill}.rank","value":1},{"adjustName":false,"choices":[{"label":"Акробатика","value":"acrobatics"},{"label":"Ремесло","value":"crafting"},{"label":"Выступление","value":"performance"}],"flag":"skill","key":"ChoiceSet","prompt":"Выберите навык."}]}},{"id":"LU4i3qXtyzeTGWZQ","slug":"luminous-sprite","name":"Светящийся спрайт","cat":"heritages","type":"heritage","text":"Вы светитесь магическим сиянием. Вы естественно излучаете свет как от Факела; этот свет имеет признаки природный и свет. Вы можете погасить, снова зажечь или изменить цвет этого света, используя одиночное действие (1 действие), которое имеет признак концентрация.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Sprite","slug":"sprite","uuid":"Compendium.pf2e.ancestries.Item.TRqoeYfGAFjQbviF"},"rules":[]}},{"id":"iOREr80Q0SsvPP8B","slug":"sacred-nagaji","name":"Священный нагаджи","cat":"heritages","type":"heritage","text":"Вы отличаетесь от большинства нагаджи — ваша верхняя часть тела красивая человеческая, а нижняя — зеленой или белой змеи. Легенды утверждают, что вашими предками были не нагаджи, созданные Налинивати, а верные змеи, вознесенные богиней. Вместо безоружной атаки клыками у вас есть атака хвостом, которая наносит 1к6 дробящего урона, относится к группе оружия \"драка\" и имеет признаки безоружное и точное. Вы получаете бонус обстоятельства +2 к вашим КС Стойкости и Рефлекса против попыток Захватить или Опрокинуть вас. Этот бонус также применяется к спасброскам против эффектов, которые Схватят, Сдержат или собьют вас Ничком.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Nagaji","slug":"nagaji","uuid":"Compendium.pf2e.ancestries.Item.J7T7bDLaQGoY1sMF"},"rules":[{"key":"FlatModifier","predicate":[{"or":["action:grapple","action:trip","inflicts:grabbed","inflicts:restrained","inflicts:prone"]}],"selector":["fortitude","reflex"],"type":"circumstance","value":2}]}},{"id":"bKr34Uvxc2XClr9q","slug":"strong-oak","name":"Сильный дуб","cat":"heritages","type":"heritage","text":"У большинства горанов тело состоит из гибких лиан и крепких стеблей, но вы покрыты прочной, грубой корой, а ваши ноги устойчивы, как корни. Вы получаете бонус обстоятельства +2 к вашим КС Стойкости и Рефлекса против попыток Захватить или Опрокинуть вас. Еще этот бонус применяется к спасброскам против эффектов, которые могут Схватить, Сдержать или сбить вас Ничком. Вы также получаете бонус обстоятельства +2 к проверкам Акробатики для Балансирования.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ghoran","slug":"ghoran","uuid":"Compendium.pf2e.ancestries.Item.tSurOqRcfumadTfr"},"rules":[{"key":"FlatModifier","predicate":[{"or":["action:grapple","action:trip","inflicts:grabbed","inflicts:restrained","inflicts:prone"]}],"selector":["fortitude","reflex"],"type":"circumstance","value":2},{"key":"FlatModifier","predicate":["action:balance"],"selector":"acrobatics","type":"circumstance","value":2}]}},{"id":"G8jfMayPv4vZvAVr","slug":"sylph","name":"Сильф","cat":"heritages","type":"heritage","text":"Вы произошли от элементалей воздуха или родились под влиянием этой стихии. В дополнение к признакам своей родословной, вы получаете признак сильф. Вы также получаете Сумеречное зрение или Ночное зрение, если ваша родословная уже имеет сумеречное зрение. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей сильфа и способностей своей родословной.\n\nСильф","level":0,"traits":["сильф"],"tags":["sylph"],"rarity":"необычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"key":"Sense","selector":"low-light-vision"},{"key":"Sense","predicate":["self:low-light-vision:from-ancestry"],"selector":"darkvision"}]}},{"id":"fCaFb3kv6Vob5ByX","slug":"cecaelia-merfolk","name":"Сисилиевый мерфолк","cat":"heritages","type":"heritage","text":"В то время как тела большинства мерфолков напоминают нижнюю половину рыбы, ваша нижняя половина похожа на головоногого. У вас множество щупалец вместо ног или рыбьего хвоста, и эти щупальца покрыты присосками. Ваша наземная Скорость становится 10 футов, и вы получаете Скорость карабканья 10 футов. Также, обилие ног позволяет вам Шагать в немагическую Сложную местность.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Merfolk","slug":"merfolk","uuid":"Compendium.pf2e.ancestries.Item.FUqZRllwn6kmFA8K"},"rules":[]}},{"id":"KDs97OkCmEYTLUp9","slug":"plane-hopper-jotunborn","name":"Скачущий по планам ётунорожденный","cat":"heritages","type":"heritage","text":"Вы были избраны за свой малый размер, позволяющий вам с лёгкостью двигаться между планарными пределами. Вы обычно выполняете роль гонца или разведчика, и планарное влияние наделило вас искрой магической силы. Вместо Большого, ваш размер Средний. Вы получаете одни чары из списка оккультных заклинаний. Вы можете по желанию сотворять эти чары как врождённое оккультное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой вверх.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Боевой клич!","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Jotunborn","slug":"jotunborn","uuid":"Compendium.pf2e.ancestries.Item.gayvFCiQcGNCA7aM"},"rules":[]}},{"id":"m4kFMTu2sOSWgnAU","slug":"keeper-jotunborn","name":"Смотритель ётунорожденный","cat":"heritages","type":"heritage","text":"Ваша работа в роли смотрителя за иивларами дало вам большее понимание этих священных существ и умение выслеживать их, какими бы изворотливыми они не были. Вы обучены Выживанию и получаете способность навыка Изучение дикой природы. Вы получаете бонус обстоятельства +1 к проверкам Выслеживания животных.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Боевой клич!","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Jotunborn","slug":"jotunborn","uuid":"Compendium.pf2e.ancestries.Item.gayvFCiQcGNCA7aM"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.survival.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Survey Wildlife","grantId":"tGIXuk0XeWmG04CX"},{"key":"FlatModifier","predicate":["action:track","target:trait:animal"],"selector":"survival","type":"circumstance","value":1}]}},{"id":"7lFPhRMAFXQsXUP2","slug":"snow-rat","name":"Снежная крыса","cat":"heritages","type":"heritage","text":"У вас более толстая шерсть и более массивное тело для защиты от холода, что дает вам сопротивление холоду, равное половине вашего уровня (минимум 1). Вы считаете воздействие эффектов Холодной окружающей среды так, как если бы они были на одну ступень лучше (невероятный холод становится экстремальным, экстремальный холод становится сильным и т.д.).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ratfolk","slug":"ratfolk","uuid":"Compendium.pf2e.ancestries.Item.P6PcVnCkh4XMdefw"},"rules":[]}},{"id":"gQyPU441J3rGt8mD","slug":"snow-goblin","name":"Снежный гоблин","cat":"heritages","type":"heritage","text":"Вы привыкли жить в холодных землях, и имеете кожу от небесно-голубого до темно-синего цвета, а также синий мех. Вы получаете сопротивление холоду, равное половине вашего уровня (минимум 1). Вы считаете воздействие эффектов Холодной окружающей среды так, как если бы они были на одну ступень лучше (невероятный холод становится экстремальным, экстремальный холод становится сильным и т.д.).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goblin","slug":"goblin","uuid":"Compendium.pf2e.ancestries.Item.sQfjTMDaZbT9DThq"},"rules":[]}},{"id":"0B0M6CUnVDkeznRv","slug":"dog-kholo","name":"Собачий кхоло","cat":"heritages","type":"heritage","text":"Вы — проворный кхоло с доисторическим, почти собачьим телосложением. Хотя вы обычно передвигаетесь как четвероногий, вы все равно можете стоять и сражаться на двух ногах, что позволяет вам нормально использовать все снаряжение. Если у вас свободны обе руки, вы можете увеличить свою скорость до 30 футов, когда бежите на всех четырех конечностях.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kholo","slug":"kholo","uuid":"Compendium.pf2e.ancestries.Item.vxbQ1Yw4qwgjTzqo"},"rules":[]}},{"id":"iY2CCqoMc2bRdoas","slug":"created-fleshwarp","name":"Созданный деформированный","cat":"heritages","type":"heritage","text":"Вы были созданы оккультными или алхимическими процессами, например, были выращены в чане или сшиты из частей тела других существ ученым из Усталава. Изготовленное вам тело надежно; вам не нужно есть и вы не голодаете. Вы получаете бонус обстоятельства +2 к спасброскам против болезней.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fleshwarp","slug":"fleshwarp","uuid":"Compendium.pf2e.ancestries.Item.FXlXmNBFiiz9oasi"},"rules":[{"key":"FlatModifier","label":"против болезней","predicate":["disease"],"selector":"saving-throw","type":"circumstance","value":2}]}},{"id":"KaokXdiE3ewXprdL","slug":"pine-leshy","name":"Сосновый леший","cat":"heritages","type":"heritage","text":"Вы выделяете густой, липкий сок из своей похожей на кору плоти, благодаря чему вам легче карабкаться и удерживать снаряжение. Вы получаете способность Боевой альпинист и бонус обстоятельства +2 к КС Рефлекса против попыток Разоружить вас.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Combat Climber","grantId":"09PurtIanNUPfNRq"},{"hideIfDisabled":true,"key":"FlatModifier","predicate":["action:disarm"],"selector":"reflex","type":"circumstance","value":2}]}},{"id":"BFOsMnWfXL1oaWkY","slug":"steelskin-hobgoblin","name":"Сталекожий хобгоблин","cat":"heritages","type":"heritage","text":"Когда вы получаете порезы или ожоги, ваше тело реагирует, образуя на месте травмы жесткие, но гибкие мозоли. Со временем это делает наиболее уязвимые части вашего тела более твердыми и устойчивыми к урону. Многие сталекожие хобгоблины намеренно используют клинки и пламя, чтобы формировать замысловатые шрамы, однако это верно не для всех. Ваша чистая проверка при восстановлении от продолжительного физического (включая кровотечение), энергетического или урона ядом равняется КС 13 (КС 13) (вместо КС 15), или КС 8 (КС 8) при получении особенно эффективной помощи.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Hobgoblin","slug":"hobgoblin","uuid":"Compendium.pf2e.ancestries.Item.piNLXUrm9iaGqD2i"},"rules":[]}},{"id":"j0R1SyJP8k4G2Hkn","slug":"scavenger-strix","name":"Стрикс собиратель","cat":"heritages","type":"heritage","text":"Ваши предки родом из страны, где еды было мало, а угроз много. Вы обучены Выживанию. Вы получаете бонусную способность навыка Добытчик еды. Ваша тщательность при сборе еды дает вам бонус обстоятельства +1 к проверкам Выживания для Проживание.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Strix","slug":"strix","uuid":"Compendium.pf2e.ancestries.Item.GXcC6oVa5quzgNHD"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.survival.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Forager","grantId":"8qebBeOJsyRIchcu"},{"key":"FlatModifier","predicate":["action:subsist"],"selector":"survival","type":"circumstance","value":1}]}},{"id":"MUujYQYWg6PNVaaN","slug":"predator-strix","name":"Стрикс хищник","cat":"heritages","type":"heritage","text":"Вы происходите из рода стриксов с исключительно широкими крыльями и длинными когтями. Вы получаете безоружную атаку ближнего боя когтями, которая наносит 1к4 рубящего урона. Ваша атака когтями относится к группе \"драка\" и имеет признаки безоружное, быстрое и точное.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Strix","slug":"strix","uuid":"Compendium.pf2e.ancestries.Item.GXcC6oVa5quzgNHD"},"rules":[]}},{"id":"RKz7Z5pefXKiv9JE","slug":"suli","name":"Сули","cat":"heritages","type":"heritage","text":"Вы произошли от джанна или иным образом воплощаете дихотомию противоположных стихийных планарных сил. В дополнение к признакам своей родословной, вы получаете признак сули. Вы также получаете Сумеречное зрение или Ночное зрение, если ваша родословная уже имеет сумеречное зрение. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей сули и способностей своей родословной.\n\nСули","level":0,"traits":["джинникин","сули"],"tags":["geniekin","suli"],"rarity":"необычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"key":"Sense","selector":"low-light-vision"},{"key":"Sense","predicate":["self:low-light-vision:from-ancestry"],"selector":"darkvision"}]}},{"id":"ZZKZkeSP5TuT62IA","slug":"duskwalker","name":"Сумеречный","cat":"heritages","type":"heritage","text":"Благодаря древней сделке ваша душа возродилась как сумеречный — планарный отпрыск, связанный с психопомпами и Могильником. Вы получаете признак сумеречный. Вы также получаете Сумеречное зрение или Ночное зрение, если ваша родословная уже имеет сумеречное зрение. Ваше тело и дух никогда не могут стать нежитью. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей сумеречного и способностей своей родословной.\n\nСумеречный","level":0,"traits":["сумеречный"],"tags":["duskwalker"],"rarity":"необычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[{"key":"Sense","selector":"low-light-vision"},{"key":"Sense","predicate":["self:low-light-vision:from-ancestry"],"selector":"darkvision"}]}},{"id":"cCy8vsZENlwiAyZ6","slug":"twilight-halfling","name":"Сумеречный полурослик","cat":"heritages","type":"heritage","text":"Подобру или поздорову, ваши предки совершали много тайных дел под покровом сумерек, и со временем они развили способность видеть в сумерках даже с учётом обычного острого зрения полуросликов. Вы получаете Сумеречное зрение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Halfling","slug":"halfling","uuid":"Compendium.pf2e.ancestries.Item.GgZAHbrjnzWOZy2v"},"rules":[{"key":"Sense","selector":"low-light-vision"}]}},{"id":"uxtcKTkD62SmrUoh","slug":"shapewrought-fleshwarp","name":"Сформированный деформированный","cat":"heritages","type":"heritage","text":"Вы — жертва искажения плоти, скорее всего, имеете обвисшую плоть, торчащие кости или черты нечеловеческих существ, прорастающих из вашей кожи. Тем не менее, вы превратили в силу психические потери своего превращения. Вы получаете сопротивление ментальному урону, равное половине вашего уровня (минимум 1).","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fleshwarp","slug":"fleshwarp","uuid":"Compendium.pf2e.ancestries.Item.FXlXmNBFiiz9oasi"},"rules":[]}},{"id":"qbWaybAX1LK7kUyY","slug":"thalassic-azarketi","name":"Талассический азаркет","cat":"heritages","type":"heritage","text":"Вы ведете свой род от азаркетов, которые прожили свою жизнь среди великих мировых морей и океанов. Вы знаете, как использовать течения и природную магию воды, чтобы направлять свои атаки. Вы получаете способность навыка Подводный мародёр, и при сражении с подводными целями ваши колющие дистанционные атаки не имеют сниженный вдвое шаг дистанции.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Azarketi","slug":"azarketi","uuid":"Compendium.pf2e.ancestries.Item.yFoojz6q3ZjvceFw"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Underwater Marauder","grantId":"iOY6YfGBaOvMNAor"}]}},{"id":"Ga7UEU186pjq7LBD","slug":"talos","name":"Талос","cat":"heritages","type":"heritage","text":"Ваши физические особенности отражают влияние зура или другого элементаля металла на вашу родословную. Ваша кожа, скорее всего, имеет металлический блеск — от тусклого оттенка необработанной руды до сверкающей полировки нового клинка, а износ от возраста или невзгод выражается в потускнении, ржавчине или потертостях. Ваши волосы могут напоминать пряденое золото, свернутую сталь, медную проволоку или плетеные цепи. Вы получаете признак талос в дополнение к признакам вашей родословной. Вы получаете сопротивление электричеству, равное половине вашего уровня (минимум 1). Вы можете сотворять чары Обнаружение металла как врождённое арканное заклинание по желанию. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону.\n\nПри получении способности родословной вы можете выбирать из способностей талосов, способностей джинникинов и способностей своей родословной.\n\nТалос","level":0,"traits":["талос"],"tags":["talos"],"rarity":"необычный","remaster":true,"source":"Ярость стихий","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[]}},{"id":"tarfuEXmi0E0Enfy","slug":"shadow-rat","name":"Теневая крыса","cat":"heritages","type":"heritage","text":"Ваши предки жили в темных пространствах под землей, что наделило вас темным мехом и смутно неестественной внешностью. Вы становитесь обучены Запугиванию и можете использовать Запугивание, чтобы использовать Принуждение на зверей. Когда вы используете Деморализовать на животное, то не получаете штраф из-за того, что не говорите с ним на одном языке. Если вы уже стали обучены Запугиванию автоматически (например, благодаря своей предыстории или классу), вместо этого вы становитесь обучены другому навыку на свой выбор.\n\nОтношение животных к вам начинается на одну ступень хуже чем обычно, как правило начинаясь с недружественного вместо безразличного для одомашненных животных, или враждебного вместо недружественного в случае с дикими животными.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ratfolk","slug":"ratfolk","uuid":"Compendium.pf2e.ancestries.Item.P6PcVnCkh4XMdefw"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.intimidation.rank","value":1}]}},{"id":"d0bNxgGqvaCkFlhN","slug":"umbral-gnome","name":"Теневой гном","cat":"heritages","type":"heritage","text":"Будь то из-за связи с темными или теневыми феями, или подземными гномами, известными как дратнелары, или по другой причине, но вы можете видеть в полной темноте. Вы получаете ночное зрение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Gnome","slug":"gnome","uuid":"Compendium.pf2e.ancestries.Item.CYlfsYLJcBOgqKtD"},"rules":[{"key":"Sense","selector":"darkvision"}]}},{"id":"VHln8G1GNaSzNNHq","slug":"shadow-of-the-smith","name":"Тень кузнеца","cat":"heritages","type":"heritage","text":"Ваша тень густая и жидкая, будто она способна закалить самую лучшую руду. Вы получаете действие Начертать теневой узор.","level":0,"traits":["Ваянг"],"tags":["wayang"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Wayang","slug":"wayang","uuid":"Compendium.pf2e.ancestries.Item.8FpI46oVxYVku04u"},"rules":[]}},{"id":"5apoJtHGL0lIz1cz","slug":"shadow-of-the-sailor","name":"Тень моряка","cat":"heritages","type":"heritage","text":"Ваша тень порхает по поверхности воды, как и вы. Вы можете ходить по поверхности воды и других не наносящих урон жидкостей, двигаясь со Скоростью, равной половине вашей обычной Скорости. Вы можете попытаться двигаться по поверхности текущей воды, всё ещё с половиной вашей обычной Скорости, но для этого вы должны преуспеть в проверке Акробатики, чтобы Балансировать используя КС проверки Плавания для движения в этой воде; при провале вы падаете в воду. Эта проверка Акробатики не тратит действия.","level":0,"traits":["Ваянг"],"tags":["wayang"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Wayang","slug":"wayang","uuid":"Compendium.pf2e.ancestries.Item.8FpI46oVxYVku04u"},"rules":[]}},{"id":"yxZtNE87im9yZFXk","slug":"shadow-of-the-hermit","name":"Тень отшельника","cat":"heritages","type":"heritage","text":"Ваша тень, кажется, каким-то образом полна секретов и тайн, и она делится ими с вами. Выберите одни чары из списка оккультных заклинаний. Вы можете по желанию сотворять эти чары как врождённое оккультное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округленной вверх.","level":0,"traits":["Ваянг"],"tags":["wayang"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Wayang","slug":"wayang","uuid":"Compendium.pf2e.ancestries.Item.8FpI46oVxYVku04u"},"rules":[]}},{"id":"GvtOzLp4kIuYfx1R","slug":"shadow-of-the-courtier","name":"Тень придворного","cat":"heritages","type":"heritage","text":"Ваша тень кружит вокруг вас. Вы получаете способность навыка Впечатляющее выступление, позволяющую вам Произвести впечатление, используя Выступление вместо Дипломатии. Раз в день, если вы провалили, но не критически провалили проверку, чтобы \"Произвести впечатление\", вы можете разыграть это как часть представления, что позволит вам перебросить эту проверку; это эффект удачи.","level":0,"traits":["Ваянг"],"tags":["wayang"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Wayang","slug":"wayang","uuid":"Compendium.pf2e.ancestries.Item.8FpI46oVxYVku04u"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Impressive Performance","grantId":"xqAdXRd2gSQcqp5E"}]}},{"id":"fcsYmaIfMR9iXv06","slug":"shadow-of-the-wanderer","name":"Тень странника","cat":"heritages","type":"heritage","text":"Ваша тень проносится перед вами, расчищая путь. Ваша Скорость увеличивается на 5 футов.","level":0,"traits":["Ваянг"],"tags":["wayang"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Wayang","slug":"wayang","uuid":"Compendium.pf2e.ancestries.Item.8FpI46oVxYVku04u"},"rules":[{"key":"FlatModifier","selector":"land-speed","value":5}]}},{"id":"n2DKA0OQQcfvZRly","slug":"technological-fleshwarp","name":"Технологический деформированный","cat":"heritages","type":"heritage","text":"Ваше преобразование происходит из-за манипуляций с помощью передовых технологий, вроде тех, что можно найти в Нумерии. Ваши эмоции притуплены, и на них трудно повлиять. Когда при спасброске против эффекта с признаком эмоция вы получаете успех, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fleshwarp","slug":"fleshwarp","uuid":"Compendium.pf2e.ancestries.Item.FXlXmNBFiiz9oasi"},"rules":[]}},{"id":"LlUEmCDOLSZaGOyI","slug":"titan-nagaji","name":"Титанический нагаджи","cat":"heritages","type":"heritage","text":"Вы росли воином или телохранителем, и ваше особое питание и накачанные мышцы сделали вашу чешую прочной, как пластины доспеха.\n\nВаша чешуя является средним доспехом из группы латных, дающая бонус предмета +4 к КБ, и ограничение модификатора Ловкости к КБ равное +1, штраф проверки −2, штраф Скорости −5 футов, значение Силы +3 и признак удобный. Вы никогда не сможете надеть другой доспех или снять чешую. Вы можете гравировать на чешую руны доспехов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Nagaji","slug":"nagaji","uuid":"Compendium.pf2e.ancestries.Item.J7T7bDLaQGoY1sMF"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.equipment-srd.Item.Titan Nagaji Scales","grantId":"KA0Ku5qOQfXqw3BK"}]}},{"id":"K0NerdkFnce9KeHw","slug":"weaver-jotunborn","name":"Ткач ётунорожденный","cat":"heritages","type":"heritage","text":"Вы овладели искусством плетения из иивларского шёлка — техникой, требующей тонкого внимания к деталям. Вы обучены Ремеслу и получаете бонус обстоятельства +1 к проверкам Восприятия для Поиска спрятанных вещей, таких как потайные двери или ловушки.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Боевой клич!","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Jotunborn","slug":"jotunborn","uuid":"Compendium.pf2e.ancestries.Item.gayvFCiQcGNCA7aM"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.crafting.rank","value":1},{"key":"FlatModifier","predicate":["action:seek","secret-doors-or-traps"],"selector":"perception","type":"circumstance","value":1}]}},{"id":"2QLKvmCimT9ai0Bi","slug":"thickskin-tripkee","name":"Толстокожий трипки","cat":"heritages","type":"heritage","text":"Ваша толстая кожа напоминает кожу жабы. Вы получаете 8 Очков Здоровья от своей родословной вместо 6. Вы получаете бонус обстоятельство +1 к спасброскам против болезней и ядов.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tripkee","slug":"tripkee","uuid":"Compendium.pf2e.ancestries.Item.hXM5jXezIki1cMI2"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.attributes.ancestryhp","priority":51,"value":8},{"key":"FlatModifier","predicate":[{"or":["item:trait:disease","item:trait:poison"]}],"selector":"saving-throw","type":"circumstance","value":1}]}},{"id":"MhXHEh7utEfxBwmc","slug":"thickcoat-shoony","name":"Толстошкурый шуни","cat":"heritages","type":"heritage","text":"Вы — редкий шуни, родом из холодных краев. Вы получаете сопротивление холоду, равное половине вашего уровня (минимум 1), и считаете эффекты Холодной окружающей среды так, как если бы они были на одну ступень легче (невероятный холод становится экстремальным, экстремальный холод становится сильным и так далее). Вам не надо делать чистую проверку, чтобы целиться в Скрытое существо, если это существо {скрыто} только снегом. Если вы не носите защитное снаряжение или не укрываетесь в убежище, вы считаете эффекты жаркой окружающей среды так, как если бы они были на одну ступень хуже.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Shoony","slug":"shoony","uuid":"Compendium.pf2e.ancestries.Item.q6rsqYARyOGXZA8F"},"rules":[]}},{"id":"kHHcvJBJNiPJTuna","slug":"wisp-fetchling","name":"Тонкий фечлинг","cat":"heritages","type":"heritage","text":"Воздействие Теневого плана на ваших предков привело к большим физическим изменениям. Ваши волосы или кожа иногда кажутся непрочными, а вы более тонкий и подвижный, чем другие фечлинги. Вы Маленького размера, вместо Среднего. Вы становитесь обучены Акробатике, получаете способность навыка Быстро протиснуться, и бонус обстоятельства +1 к проверкам Акробатики для Проскочить. Если вы станете автоматически обучены Акробатике (например, от вашей предыстории или класса), то вместо этого вы становитесь обучены навыку на свой выбор.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fetchling","slug":"fetchling","uuid":"Compendium.pf2e.ancestries.Item.hIA3qiUsxvLZXrFP"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.acrobatics.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Quick Squeeze","grantId":"3G8xUlgCjRmRJNfP"},{"key":"FlatModifier","predicate":["action:tumble-through"],"selector":"acrobatics","type":"circumstance","value":1}]}},{"id":"AVZJI5wP2X5o0LL3","slug":"trogloshi","name":"Троглоши","cat":"heritages","type":"heritage","text":"Вы приспособлены к районам густых джунглей и глубоких пещер где мало солнца, у вас мягкая плоть, лишенная пигмента, и необычайно прозрачные кристаллические рога. Вы получаете способность родословной Кристаллическое свечение.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kashrishi","slug":"kashrishi","uuid":"Compendium.pf2e.ancestries.Item.dw2K1AJR9mQ25nDP"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Crystal Luminescence","grantId":"TLuFqQwvnlJNeEsv"}]}},{"id":"U882U2NUUGL6u3rL","slug":"tunnel-rat","name":"Туннельная крыса","cat":"heritages","type":"heritage","text":"Вы легко можете сжимать свое тело и протискивать через отверстия. Вы получаете бонусную способность Быстро протиснуться даже если не обучены Акробатике. Узкие пространства, которые не настолько узкие, чтобы требовать от вас Протиснуться, не являются для вас Сложной местностью.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Ratfolk","slug":"ratfolk","uuid":"Compendium.pf2e.ancestries.Item.P6PcVnCkh4XMdefw"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Quick Squeeze","grantId":"3G8xUlgCjRmRJNfP"}]}},{"id":"wNnsjird4OQe0s6p","slug":"gourd-leshy","name":"Тыквенный леший","cat":"heritages","type":"heritage","text":"У вас вместо черепа большая тыква. Ваше знание исходит не от физического мозга, а от вашего духа, и вы нашли более удобное применение для пространства внутри своей головы. Вы можете хранить в своей голове набор предметов вплоть до 1 массы. Для того, чтобы Украсть предметы из вашей головы, КС проверки увеличивается на 4. Дополнительно, если вы храните только один объект внутри своей головы, то можете без усилий вытащить его в вашу руку, как часть другого действия для использования этого объекта. Вытаскивание предмета дает этого другому действию признак воздействие.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[{"key":"FlatModifier","predicate":["action:steal","gourd-head"],"selector":"perception-dc","value":4}]}},{"id":"ptpK6H1rM4Bu3ry4","slug":"mountainkeeper-tengu","name":"Тэнгу хранитель гор","cat":"heritages","type":"heritage","text":"Вы происходите из рода аскетов тэнгу, и это дает вам связь с духами мира и Великого Запределья. Вы можете по желанию колдовать чары Опалить жизненностью как врождённое природное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону. Каждый раз, когда вы колдуете заклинание наследия тэнгу или способности родословной, вы можете решить, является ли оно сакральным или природным.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tengu","slug":"tengu","uuid":"Compendium.pf2e.ancestries.Item.18xDKYPDBLEv2myX"},"rules":[]}},{"id":"zVf0Hlp5xG0Q7kmc","slug":"skilled-human","name":"Умелый человек","cat":"heritages","type":"heritage","text":"Ваша изобретательность позволяет вам обучаться самым разным навыкам. Вы становитесь обучены одному навыку на свой выбор. На 5-м уровне вы становитесь экспертом выбранного навыка.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Human","slug":"human","uuid":"Compendium.pf2e.ancestries.Item.IiG7DgeLWYrSNXuX"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.{item|flags.system.rulesSelections.skill}.rank","value":"ternary(gte(@actor.level,5),2,1)"},{"choices":{"config":"skills"},"flag":"skill","key":"ChoiceSet","prompt":"Выберите навык."}]}},{"id":"Gmk7oNITvMVBy78Z","slug":"undine","name":"Ундина","cat":"heritages","type":"heritage","text":"На ваше наследие крови повлиял предок водяной элементаль. В дополнение к признакам своей родословной, вы получаете признак ундина. Вы получаете Скорость плавания 10 футов и признак земноводный. Как все существа с признаком земноводный вы можете дышать воздухом и водой. Всякий раз, когда вы получаете способность родословной, вы можете выбирать из способностей ундины и способностей своей родословной.\n\nУндина","level":0,"traits":["земноводный","ундина"],"tags":["amphibious","undine"],"rarity":"необычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":null,"rules":[]}},{"id":"KJ2dSDXP9d5hJHzd","slug":"frightful-goloma","name":"Устрашающий голома","cat":"heritages","type":"heritage","text":"Ваше лицо обладает особенно отталкивающей внешностью. Вы обучены Запугиванию (или другому навыку на свой выбор, если вы уже были обучены Запугиванию) и получаете бонусную способность навыка Запугивающий взгляд.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goloma","slug":"goloma","uuid":"Compendium.pf2e.ancestries.Item.c4secsSNG2AO7I5i"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.intimidation.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Intimidating Glare","grantId":"xQMz6eDgX75WX2ce"}]}},{"id":"Y1cG8cw4qoHR145y","slug":"fey-dragonet","name":"Фейский дракончик","cat":"heritages","type":"heritage","text":"У вас яркое тело с блестящей чешуёй, которая с возрастом становится ещё более блестящей, и переливающиеся крылья бабочки. Вы можете изменить окраску и узор своих крыльев за одно действие, чтобы слиться с окружающим пространством.\n\nКогда ваши крылья будут соответствовать окружению, вы получаете бонус обстоятельства +2 к проверкам Скрытности, пока ваше окружение не изменит окраску или узор. Вы получаете признак фея и добавляете Фейский язык к своим языкам.","level":0,"traits":["фея"],"tags":["fey"],"rarity":"обычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Dragonet","slug":"dragonet","uuid":"Compendium.pf2e.ancestries.Item.B5Ewz31nJBOzHSMg"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"system.build.languages.granted","value":{"slug":"fey","source":"{item|name}"}},{"key":"FlatModifier","predicate":["fey-dragonet-wing-color"],"selector":["stealth"],"type":"circumstance","value":2}]}},{"id":"Wyw1tkO0e199Wm8o","slug":"lantern-surki","name":"Фонарный суркай","cat":"heritages","type":"heritage","text":"Ваши брюшинные узлы светятся особенно ярко. Вы можете \"Взаимодействовать\", чтобы испускать свет в 20-футовом радиусе (и тусклый свет на следующие 20 футов). Это магический эффект света с рангом противодействия, равным половине вашего уровня, округлённой в большую сторону. Вы можете сменить его цвет или погасить другим действием \"Взаимодействовать\".\n\nЭволюция: Ваши брюшинные узлы превратились в пару вторичных конечностей, проецирующих магические фокусирующие линзы. Вы получаете действие Луч фонаря.\n\nЭволюция: Из ваших плечевых узлов вырастают вторичные излучатели, которые мерцают в такт вашему фонарю. Вы получаете действие Мерцание фонаря.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Рёв дикой природы","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Surki","slug":"surki","uuid":"Compendium.pf2e.ancestries.Item.ALOmLePjbc37ca3Y"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"flags.system.surki.evolutions","value":{"label":"Луч фонаря","predicate":[{"not":"evolution:lantern-beam"}],"value":"lantern-beam"},"resolvedValues":{}},{"key":"ActiveEffectLike","mode":"add","path":"flags.system.surki.evolutions","value":{"label":"Мерцание фонаря","predicate":[{"not":"evolution:lantern-strobe"}],"value":"lantern-strobe"},"resolvedValues":{}},{"allowDuplicate":false,"key":"GrantItem","predicate":["evolution:lantern-beam"],"reevaluateOnUpdate":true,"uuid":"Compendium.pf2e.actionspf2e.Item.Lantern Beam"},{"allowDuplicate":false,"key":"GrantItem","predicate":["evolution:lantern-strobe"],"reevaluateOnUpdate":true,"uuid":"Compendium.pf2e.actionspf2e.Item.Lantern Strobe"}]}},{"id":"L6zfGzLMDLHbZ7VV","slug":"fruit-leshy","name":"Фруктовый леший","cat":"heritages","type":"heritage","text":"Ваше тело постоянно производит небольшие фрукты, наполненные природной магией. Каждый день на рассвете созревает новый плод. Вы или ваш союзник можете сорвать этот фрукт использовав действие Взаимодействовать. Если живое существо, способное получать питательные вещества от фрукта, в течение следующего часа съедает его, использовав действие \"Взаимодействовать\", то восстанавливает ((уровень персонажа/2))к8 (жизненная энергия, исцеление)| ОЗ + дополнительные 1к8 ОЗ за каждые ваши 2 уровня после 1-го. Этот эффект имеет признаки исцеление и жизненность.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[]}},{"id":"2kSzKDtwbcILZTIe","slug":"snaptongue-tripkee","name":"Хватающий языком трипки","cat":"heritages","type":"heritage","text":"Ваш язык особенно длинный, и вы можете выбрасывать его далеко и с необычайной точностью. Вы можете использовать свой язык, чтобы доставлять заклинания с дистанцией \"касание\" и выполнять чрезвычайно простые действия Взаимодействовать, такие как открытие некоторых видов незапертых дверей. Ваш язык не может выполнять действия, для которых нужны пальцы или значительная ловкость рук, включая любые действия, которые для выполнения потребуют совершить проверку, и вы не можете использовать его, чтобы держать предметы.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tripkee","slug":"tripkee","uuid":"Compendium.pf2e.ancestries.Item.hXM5jXezIki1cMI2"},"rules":[]}},{"id":"8wGUh9RsMUamOKjh","slug":"tailed-goblin","name":"Хвостатый гоблин","cat":"heritages","type":"heritage","text":"У вас мощный хвост, вероятно потому, что вы происходите из сообщества гоблинов-обезьян. Вы получаете бонус обстоятельства +2 к проверкам Атлетики когда Карабкаетесь, получаете способность Боевой альпинист в качестве бонусной, и снижаете количество требуемых свободных рук на 1 для \"Карабканья\" и Опрокидывания.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Goblin","slug":"goblin","uuid":"Compendium.pf2e.ancestries.Item.sQfjTMDaZbT9DThq"},"rules":[{"key":"FlatModifier","label":"Tailed Goblin (Climb)","predicate":["action:climb"],"selector":"athletics","type":"circumstance","value":2},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Combat Climber","grantId":"09PurtIanNUPfNRq"}]}},{"id":"CzOHITB2ihLGqMuJ","slug":"runtboss-hobgoblin","name":"Хобгоблин босс коротышек","cat":"heritages","type":"heritage","text":"Вы происходите из длинного рода хобгоблинов, которые командовали гоблинами. Вы меньше других хобгоблинов, но гоблины всё равно слушаются любых команд, которые вы выкрикиваете. Вы получаете способность навыка Групповое принуждение. Если при совершении проверки Запугивания вы получаете успех для Принуждения гоблина, результат считается критическим успехом; если при броске вы получаете критический провал, результат считается обычным провалом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Hobgoblin","slug":"hobgoblin","uuid":"Compendium.pf2e.ancestries.Item.piNLXUrm9iaGqD2i"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Group Coercion","grantId":"gUqvezs2zzoTXFAI"}]}},{"id":"n2eJEjA8pnOMiuCm","slug":"smokeworker-hobgoblin","name":"Хобгоблин курильщик","cat":"heritages","type":"heritage","text":"Ваша семья была алхимиками, инженерами и учеными в течение многих поколений, делая проекты, дающие дым и огонь на поле битвы. Вы получаете сопротивление огню, равное половине вашего уровня (минимум 1). Вы автоматически преуспеваете в чистых проверках КС 5, когда целитесь в Скрытое существо, если это {сокрытие} вызвано дымом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Hobgoblin","slug":"hobgoblin","uuid":"Compendium.pf2e.ancestries.Item.piNLXUrm9iaGqD2i"},"rules":[]}},{"id":"ikNJZRxUjcRLisO6","slug":"elfbane-hobgoblin","name":"Хобгоблин эльфогуб","cat":"heritages","type":"heritage","text":"Хобгоблины были созданы давным-давно из ненадежных и плодовитых гоблинов, чтобы использоваться в качестве армии против эльфов. Хотя эльфы в конечном счете освободили хобгоблинов от их рабства, некоторые хобгоблины сохраняют наследственное сопротивление магии, которую они называют \"эльфийской магией\". Вы получаете реакцию Противиться эльфийской магии.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Hobgoblin","slug":"hobgoblin","uuid":"Compendium.pf2e.ancestries.Item.piNLXUrm9iaGqD2i"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Resist Elf Magic"}]}},{"id":"lDT5h3f5GXRj42Ir","slug":"stonestep-shisk","name":"Ходящий по камням шиск","cat":"heritages","type":"heritage","text":"Путешествие по горам и другой каменистой местности — ваша вторая натура. Вы можете игнорировать немагическую Сложную местность, вызванную щебнем и Неровную землю из камня и земли.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Shisk","slug":"shisk","uuid":"Compendium.pf2e.ancestries.Item.x1YinOddgUxwOLqP"},"rules":[]}},{"id":"Mj7uHxxVkRUlOFwJ","slug":"hillock-halfling","name":"Холмовой полурослик","cat":"heritages","type":"heritage","text":"Привыкшие к спокойной жизни в холмах, ваши люди находят отдых и расслабление особенно полезными, в частности когда наслаждаются комфортом. Когда вы восстанавливаете Очки Здоровья во время ночного отдыха, добавьте ваш уровень к количеству восстановленных ОЗ. Когда кто-либо использует на вас навык Медицины для Лечения ран, вы можете съесть снек, чтобы добавить ваш уровень к количеству восстановленных при лечении ОЗ.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Halfling","slug":"halfling","uuid":"Compendium.pf2e.ancestries.Item.GgZAHbrjnzWOZy2v"},"rules":[{"key":"ActiveEffectLike","mode":"add","path":"system.attributes.hp.recoveryAddend","value":"@actor.level"},{"key":"FlatModifier","predicate":["action:treat-wounds"],"selector":"healing-received","value":"@actor.level"}]}},{"id":"CpjsxaXYjlkCI5nc","slug":"chrysanthemum-leshy","name":"Хризантемовый леший","cat":"heritages","type":"heritage","text":"Вы похожи на человеческого ребенка, но на голове у вас растет огромная корона из хризантем, богато украшенная, как у императора. Эти лепестки обладают целебными свойствами, давая вам бонус обстоятельства +1 к спасброскам против ядов.\n\nКроме того, во время ежедневных приготовлений вы можете безвредно сорвать несколько лепестков с головы и заварить их в свежей воде, чтобы создать одно Противоядие (Малое), принимающее форму чая. На 6-м уровне вы можете создать Противоядие (Среднее); на 10-м уровне вы можете создать Противоядие (Большое); на 14-м уровне вы можете создать Противоядие (Сильное). Чай теряет свою эффективность, если его не употребить до следующих ежедневных приготовлений.","level":0,"traits":["Леший"],"tags":["leshy"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Leshy","slug":"leshy","uuid":"Compendium.pf2e.ancestries.Item.cdhgByGG1WtuaK73"},"rules":[{"key":"FlatModifier","predicate":["item:trait:posion"],"selector":"saving-throw","type":"circumstance","value":1}]}},{"id":"cKgxEWnRVazFPi3M","slug":"tsukumogami-poppet","name":"Цукумогами кукла","cat":"heritages","type":"heritage","text":"У вас есть форма и воспоминания обычного инструмента. Выберите один навык, связанный с тем, каким инструментом вы были; например Знаниям кулинарии для кухонного ножа или ложки. Вы обучены этому навыку и получаете бонус обстоятельства +2 к проверкам Помощи с этим навыком. Если вы возьмёте способность Полезная кукла, бонус увеличивается до +3.\n\nВ то время как большинство кукол сделаны из набивки, ткани или мягких металлов, некоторые цукумогами сделаны из других материалов, что меняет слабость кукол к огню. Если ваше тело состоит преимущественно из металла, то вы получаете слабость к электричеству, а если из керамики, то к холоду.","level":0,"traits":["Кукла"],"tags":["poppet"],"rarity":"необычный","remaster":true,"source":"Дополнение к правилам","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Poppet","slug":"poppet","uuid":"Compendium.pf2e.ancestries.Item.6F2fSFC1Eo1JdpY4"},"rules":[{"adjustName":false,"choices":[{"label":"Из ткани или дерева","value":"fire"},{"label":"Металл","value":"electricity"},{"label":"Керамический","value":"cold"}],"flag":"weakness","key":"ChoiceSet","label":"Выберите материал.","rollOption":"tsukumogami-poppet"}]}},{"id":"0Iv6LfT3UEt8taj5","slug":"warden-human-bb","name":"Человек хранитель","cat":"heritages","type":"heritage","text":"Вы и члены вашей — выживальщики, и вы научились заботиться о себе. Выберите одно из следующих преимуществ.\n\nУвеличьте свой максимум ОЗ на 4.\n\nВаше мастерство спасбросков Стойкости улучшается до эксперта.\n\nВы становитесь обучены средним доспехам.\n\nЗаметка: Это наследие относится к Стартовому набору и имеет нестандартные особенности наследия.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Human","slug":"human","uuid":"Compendium.pf2e.ancestries.Item.IiG7DgeLWYrSNXuX"},"rules":[{"key":"FlatModifier","predicate":["heritage:warden-human:hp"],"selector":"hp","value":4},{"key":"ActiveEffectLike","mode":"upgrade","path":"system.proficiencies.defenses.medium.rank","predicate":["heritage:warden-human:armor"],"value":1},{"key":"ActiveEffectLike","mode":"upgrade","path":"system.saves.fortitude.rank","predicate":["heritage:warden-human:fortitude"],"value":2},{"adjustName":false,"choices":[{"label":"4 ОЗ","value":"hp"},{"label":"Эксперт спасбросков Стойкости","value":"fortitude"},{"label":"Обучен средним доспехам","value":"armor"}],"flag":"wardenHumanBB","key":"ChoiceSet","label":"Сделайте выбор.","rollOption":"heritage:warden-human"}]}},{"id":"tXC5Gwn9D5x0ouJh","slug":"sensate-gnome","name":"Чувствительный гном","cat":"heritages","type":"heritage","text":"Вы видите все цвета более яркими, слышите все звуки как более богатые, и особенно, невероятно подробно чувствуете все ароматы. Вы получаете особое чувство: неточный нюх дальностью 30 футов. Это означает, что вы можете использовать ваше чувство обоняния, чтобы определять точное местоположение существа (см. Обнаружение существ). Обычно Мастер удвоит дистанцию если вы с подветренной стороны от существа или уменьшит вдвое, если против ветра.\n\nДополнительно, вы получаете бонус обстоятельства +2 к проверкам Восприятия, всякий раз, когда пытаетесь определить местоположение {необнаруженного} существа, которое в пределах дистанции вашего нюха.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Gnome","slug":"gnome","uuid":"Compendium.pf2e.ancestries.Item.CYlfsYLJcBOgqKtD"},"rules":[{"key":"FlatModifier","predicate":["action:seek",{"lte":["target:distance",30]}],"selector":"perception","type":"circumstance","value":2},{"acuity":"imprecise","key":"Sense","range":30,"selector":"scent"}]}},{"id":"hzW7VoRDYsKJB8ku","slug":"surgewise-fleshwarp","name":"Чувствительный к магии деформированный","cat":"heritages","type":"heritage","text":"Колебания ресничек вашего тела обладают повышенной чувствительностью к источникам магии; они дергаются и трепещут от ощущения оккультных энергий, и их вибрации предупреждают вас о присутствии секретов. Вы становитесь обучены Оккультизму. Если вы уже обучены Оккультизму, то вместо этого вы становитесь обученным другому навыку на свой выбор. Еще вы получаете способность навыка Определение странностей.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fleshwarp","slug":"fleshwarp","uuid":"Compendium.pf2e.ancestries.Item.FXlXmNBFiiz9oasi"},"rules":[{"key":"ActiveEffectLike","mode":"upgrade","path":"system.skills.occultism.rank","value":1},{"key":"GrantItem","uuid":"Compendium.pf2e.feats-srd.Item.Oddity Identification","grantId":"hDGosy2ZTwnyctEP"}]}},{"id":"1wVDYY9Wue0G5R9Q","slug":"whisper-elf","name":"Шепчущий эльф","cat":"heritages","type":"heritage","text":"Ваши уши особенно чувствительны, способны уловить даже малейший шепот или звук. Вы получаете бонус обстоятельства +2, когда Ищете Спрятанных или Необнаруженных существ в радиусе 30 футов. Когда вы выбираете целью Скрытого или {спрятанного} от вас противника, снизьте КС чистой проверки до 3 для {скрытой} цели и до 9 — для {спрятанной}. Это преимущество не применяется, если вы не можете слышать или если существо не способно издавать звуки (например, находится под действием заклинания Тишина.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Elf","slug":"elf","uuid":"Compendium.pf2e.ancestries.Item.PgKmsA2aKdbLU6O0"},"rules":[{"key":"FlatModifier","predicate":[{"or":["target:condition:undetected","target:condition:hidden"]},{"lte":["target:distance",30]},"target:audible"],"selector":"perception","type":"circumstance","value":2}]}},{"id":"0TFf82gcfxXG9A54","slug":"spellkeeper-shisk","name":"Шиск хранитель заклинаний","cat":"heritages","type":"heritage","text":"Ваши магические знания позволяют вам сотворять простые заклинания. Выберите оккультное или природное. Вы получаете одни чары из списка этого магического обычая. Вы можете по желанию сотворять его, как заклинание выбранного обычая. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Shisk","slug":"shisk","uuid":"Compendium.pf2e.ancestries.Item.x1YinOddgUxwOLqP"},"rules":[]}},{"id":"Fgysc0A1pFQE8PMA","slug":"lorekeeper-shisk","name":"Шиск хранитель знаний","cat":"heritages","type":"heritage","text":"Вы выросли в окружении знаний и секретов. Вы становитесь обучены одному навыку Знаний и одному другому навыку, основанному на Интеллекте или Мудрости на ваш выбор. На 5-м уровне вы становитесь экспертом выбранных навыков.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Shisk","slug":"shisk","uuid":"Compendium.pf2e.ancestries.Item.x1YinOddgUxwOLqP"},"rules":[]}},{"id":"7vHLPleFpSqKAjWG","slug":"stormtossed-tengu","name":"Штормовой тэнгу","cat":"heritages","type":"heritage","text":"Будь то благодаря благословению Хэй Фэна или вылуплению из яйца во время шквального ветра, вы устойчивы к штормам. Вы получаете сопротивление электричеству, равное половине вашего уровня (минимум 1). Вы автоматически преуспеваете в чистых проверках, когда целитесь в Скрытое существо, если это {сокрытие} вызвано дождём или туманом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tengu","slug":"tengu","uuid":"Compendium.pf2e.ancestries.Item.18xDKYPDBLEv2myX"},"rules":[]}},{"id":"z4cvqtpkkAYoFpHa","slug":"bloodhound-shoony","name":"Шуни ищейка","cat":"heritages","type":"heritage","text":"Ваши предки были знаменитыми следопытами, и вы несете в своей крови тот же дар охоты.\n\nВы получаете особое чувство: неточный нюх с дистанцией 30 футов. Это означает, что вы можете использовать свое обоняние, чтобы определить местоположение существа, но оно остаётся Спрятанным.\n\nВы также получаете бонус обстоятельства +2 к проверкам Выживания для Выслеживания существ, которых вы ранее почувствовали с помощью своего нюха.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Shoony","slug":"shoony","uuid":"Compendium.pf2e.ancestries.Item.q6rsqYARyOGXZA8F"},"rules":[{"key":"FlatModifier","label":"Bloodhound Shoony (Track smelled creatures)","predicate":["action:track","target:previously-smelled"],"selector":"survival","type":"circumstance","value":2},{"acuity":"imprecise","key":"Sense","range":30,"selector":"scent"}]}},{"id":"mnhpCk9dIwMuFegM","slug":"paddler-shoony","name":"Шуни пловец","cat":"heritages","type":"heritage","text":"Вы происходите от шуни, которые долго и успешно жили среди тростника и камышей на болотах и топях, и приспособились к трудностям жизни вблизи заболоченных мест. Вы игнорируете сложную местность и особо сложную местность, создаваемую болотами. Когда вы получаете успех при попытке Плыть, результат считается критическим успехом.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Shoony","slug":"shoony","uuid":"Compendium.pf2e.ancestries.Item.q6rsqYARyOGXZA8F"},"rules":[]}},{"id":"isJhIPhT4MsjJvoq","slug":"fishseeker-shoony","name":"Шуни рыбак","cat":"heritages","type":"heritage","text":"Вы происходите из древнего рода рыбаков и унаследовали быстрые рефлексы, необходимые для ловли и подтягивания крупной рыбы. Если вы получаете успех, Хватаясь за уступ, результат считается критическим успехом; если вы получаете критический провал, результат считается обычным провалом. Существо, получившее провал при проверке Разоружить вас, получает вместо этого критический провал.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Shoony","slug":"shoony","uuid":"Compendium.pf2e.ancestries.Item.q6rsqYARyOGXZA8F"},"rules":[]}},{"id":"jEtVesbqYcWGbBYk","slug":"seer-elf","name":"Эльф провидец","cat":"heritages","type":"heritage","text":"У вас есть врожденная способность обнаруживать и понимать магические феномены. Вы по желанию можете сотворять чары Обнаружение магии как врождённое арканное заклинание. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону.\n\nВ дополнение, вы получаете бонус обстоятельства +1 на проверки Идентификации магии и Расшифровки текста магического свойства. Эти действия навыков обычно используют навык Аркана, Оккультизм, Природа или Религия.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Elf","slug":"elf","uuid":"Compendium.pf2e.ancestries.Item.PgKmsA2aKdbLU6O0"},"rules":[{"key":"FlatModifier","predicate":[{"or":["action:identify-magic","action:decipher-writing"]}],"selector":"skill-check","type":"circumstance","value":1}]}},{"id":"bmA9JK06rnOKpNLr","slug":"poisonhide-tripkee","name":"Ядовитошкурый трипки","cat":"heritages","type":"heritage","text":"Быть может вы и маленький, но ядовитые железы, спрятанные в вашем теле, таят смертельную защиту. Вы получаете реакцию Токсичная кожа.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Tripkee","slug":"tripkee","uuid":"Compendium.pf2e.ancestries.Item.hXM5jXezIki1cMI2"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Toxic Skin"}]}},{"id":"kTlJqhC7ZSE8P8lu","slug":"venomous-anadi","name":"Ядовитый анади","cat":"heritages","type":"heritage","text":"Клыки вашей естественной формы способны вводить противникам яд. Вы получаете умение Яд анади.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Anadi","slug":"anadi","uuid":"Compendium.pf2e.ancestries.Item.TQEqWqc7BYiadUdY"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Anadi Venom"}]}},{"id":"OBxrlZKg0IC5n238","slug":"venom-resistant-vishkanya","name":"Ядостойкий вишканья","cat":"heritages","type":"heritage","text":"В вашем теле содержится не только яд, но и многочисленные противоядия. Вы получаете сопротивление яду, равное половине вашего уровня (минимум 1), и каждый из ваших успешных спасбросков против недуга-яда снижает его стадию на 2, или на 1 для вирулентного яда. Каждый критический успех против действующего яда снижает его стадию на 3, или на 2 для вирулентного яда.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Vishkanya","slug":"vishkanya","uuid":"Compendium.pf2e.ancestries.Item.u1VJEXsVlmh3Fyx0"},"rules":[]}},{"id":"2jsWmnKtidCTpaQV","slug":"venomshield-nagaji","name":"Ядостойкий нагаджи","cat":"heritages","type":"heritage","text":"Ваша внутренняя связь с нагами и обычными змеями дает вам врождённое сопротивление к токсинам любого вида. Вы получаете сопротивление яду, равное половине вашего уровня (минимальное сопротивление 1), и получаете бонус обстоятельства +1 ко всем спасброскам против яда.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Nagaji","slug":"nagaji","uuid":"Compendium.pf2e.ancestries.Item.J7T7bDLaQGoY1sMF"},"rules":[{"key":"FlatModifier","predicate":["poison"],"selector":"saving-throw","type":"circumstance","value":1}]}},{"id":"m9rrlchS10xHFA2G","slug":"venomtail-kobold","name":"Ядохвостный кобольд","cat":"heritages","type":"heritage","text":"Благодаря близости ядовитого существа к вашему логову, вы родились с рудиментарной шпорой в вашем хвосте, которая каждый день выделяет смертельный яд. Вы получаете действие Хвостовой токсин.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":true,"source":"Основная книга игрока 2","license":"ORC","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Kobold","slug":"kobold","uuid":"Compendium.pf2e.ancestries.Item.7oQxL6wgsokD3QXG"},"rules":[{"key":"GrantItem","uuid":"Compendium.pf2e.actionspf2e.Item.Tail Toxin"}]}},{"id":"wHO5luJMODbDLXNi","slug":"bright-fetchling","name":"Яркий фечлинг","cat":"heritages","type":"heritage","text":"Ваше тело доказывает, что тень не может существовать без света. Возможно ваши глаза светятся ярче или вены пульсируют светом. Вы излучаете яркий свет в 5 футах вокруг себя. Вы можете активировать или подавлять это умение за действие (1 действие), которое имеет признак концентрация. Дополнительно, вы можете заставить фрагменты своей тени светиться, и сотворять Свет как оккультные врождённые чары. Чары усиливаются до ранга заклинания, равного половине вашего уровня, округлённой в большую сторону.","level":0,"traits":[],"tags":[],"rarity":"обычный","remaster":false,"source":"Дополнение к правилам","license":"OGL","actions":null,"actionType":"","category":"","prereq":"","mechanics":{"ancestry":{"name":"Fetchling","slug":"fetchling","uuid":"Compendium.pf2e.ancestries.Item.hIA3qiUsxvLZXrFP"},"rules":[]}}]);
